{
  "name": "Epiroc Rockdrill Management System",
  "description": "A comprehensive project and task management application for Epiroc Rockdrill AB, featuring dynamic dashboards, Gantt charts, KPI tracking, and interactive calendars.",
  "requestFramePermissions": []
}

export type Status = 'Not Started' | 'In Progress' | 'Completed' | 'Blocked' | 'On Hold';
export type Priority = 'High' | 'Medium' | 'Low';
export type ProjectStatus = 'Planning' | 'In Progress' | 'On Hold' | 'Completed' | 'Cancelled';

export interface Task {
  id: string;
  category: string;
  task: string;
  owner: string;
  project: string;
  status: Status;
  priority: Priority;
  progress: number;
  hours: number;
  startDate: string;
  dueDate: string;
  completionDate?: string;
  notes: string;
}

export interface Project {
  id: string;
  name: string;
  manager: string;
  status: ProjectStatus;
  startDate: string;
  endDate: string;
  hours: number;
  description: string;
}

export interface Activity {
  id: string;
  date: string;
  person: string;
  activity: string;
  hours: number;
  status: 'Completed' | 'In Progress' | 'Blocked';
  remarks: string;
}

export interface KPI {
  id: string;
  name: string;
  target: string;
  completion: number;
  remarks: string;
}

export interface SafetyStatus {
  [date: string]: {
    status: 'green' | 'yellow' | 'red';
    notes: string;
  };
}

export interface AppState {
  tasks: Task[];
  projects: Project[];
  activities: Activity[];
  kpis: KPI[];
  users: string[];
  categories: string[];
  safetyStatus: SafetyStatus;
  dailyAgenda: Record<string, string>;
}

export const BRAND = {
  YELLOW: "#FDB913",
  BLACK: "#000000",
  DARK_GRAY: "#2B2B2B",
  SUCCESS: "#2ECC71",
  WARNING: "#F39C12",
  DANGER: "#E74C3C",
  INFO: "#3498DB"
};

export const DEFAULT_USERS = [
  "Safety Team", "Engineering", "Project Team", "Safety Manager", 
  "Production Manager", "Quality Control", "Maintenance Team"
];

export const DEFAULT_CATEGORIES = [
  "Safety", "Priority", "Support Required", "Long Term Project", 
  "Short Term Project", "Task Wise Activity", "Results Achieved", 
  "Information & Team Suggestions", "External Dependencies", "Quality", 
  "Rockdrill Operations", "Equipment Maintenance"
];

export const DEFAULT_AGENDA: Record<string, string> = {
  "Monday": "Machine Orders (MO) & BOM - Rockdrill Operations",
  "Tuesday": "SOP and Fixtures - Safety Review",
  "Wednesday": "Project Updates - Engineering Focus",
  "Thursday": "CN and EITC Support - Technical Review",
  "Friday": "Weekly Review & Planning - Team Alignment",
  "Saturday": "Cleanup & Maintenance - Equipment Check",
  "Sunday": "Strategy & Innovation - Continuous Improvement"
};

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) throw new Error("Could not find root element");

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect, useCallback } from 'react';
import { 
  Calendar, 
  CheckSquare, 
  LayoutDashboard, 
  Target, 
  Clock, 
  TrendingUp, 
  Settings, 
  Download, 
  Upload, 
  RefreshCw, 
  Bell, 
  BrainCircuit,
  FileDown
} from 'lucide-react';
import { AppState, Task, Project, Activity, KPI, SafetyStatus } from './types';
import { BRAND, DEFAULT_USERS, DEFAULT_CATEGORIES, DEFAULT_AGENDA } from './constants';
import Dashboard from './components/Dashboard';
import TaskBoard from './components/TaskBoard';
import ProjectBoard from './components/ProjectBoard';
import CalendarView from './components/CalendarView';
import ActivityTracker from './components/ActivityTracker';
import KPITracker from './components/KPITracker';
import Masters from './components/Masters';

const STORAGE_KEY = 'epiroc_management_data';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('calendar');
  const [data, setData] = useState<AppState>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) return JSON.parse(saved);
    return {
      tasks: [],
      projects: [],
      activities: [],
      kpis: [],
      users: DEFAULT_USERS,
      categories: DEFAULT_CATEGORIES,
      safetyStatus: {},
      dailyAgenda: DEFAULT_AGENDA
    };
  });

  const [notifications, setNotifications] = useState<string[]>([]);

  // Persist data
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  }, [data]);

  // Automated checks (Simulated reminders)
  useEffect(() => {
    const today = new Date().toISOString().split('T')[0];
    const overdue = data.tasks.filter(t => t.dueDate < today && t.status !== 'Completed').length;
    const dueToday = data.tasks.filter(t => t.dueDate === today && t.status !== 'Completed').length;

    const newNotifications = [];
    if (overdue > 0) newNotifications.push(`⚠️ ${overdue} Overdue tasks need attention.`);
    if (dueToday > 0) newNotifications.push(`📅 ${dueToday} tasks are due today.`);
    setNotifications(newNotifications);
  }, [data.tasks]);

  const updateData = (newData: Partial<AppState>) => {
    setData(prev => ({ ...prev, ...newData }));
  };

  const handleExport = () => {
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `epiroc_backup_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const imported = JSON.parse(event.target?.result as string);
        setData(imported);
        alert('Data imported successfully!');
      } catch (err) {
        alert('Invalid data file');
      }
    };
    reader.readAsText(file);
  };

  const tabs = [
    { id: 'calendar', name: 'Calendar', icon: <Calendar size={20} /> },
    { id: 'tasks', name: 'Tasks', icon: <CheckSquare size={20} /> },
    { id: 'dashboard', name: 'Dashboard', icon: <LayoutDashboard size={20} /> },
    { id: 'projects', name: 'Projects', icon: <Target size={20} /> },
    { id: 'activities', name: 'Activities', icon: <Clock size={20} /> },
    { id: 'kpis', name: 'KPI Tracker', icon: <TrendingUp size={20} /> },
    { id: 'masters', name: 'Masters', icon: <Settings size={20} /> },
  ];

  return (
    <div className="min-h-screen flex flex-col bg-[#F8F9FA]">
      {/* Header */}
      <header className="bg-black text-white h-24 flex items-center px-8 relative overflow-hidden">
        <div className="absolute top-0 right-0 w-1/3 h-full bg-[#FDB913] skew-x-[-20deg] translate-x-20 z-0"></div>
        <div className="flex items-center z-10 space-x-6">
          <div className="bg-[#FDB913] w-14 h-14 flex items-center justify-center font-bold text-3xl text-black rounded-sm shadow-lg">
            E
          </div>
          <div>
            <h1 className="text-2xl font-bold tracking-tight">EPIROC ROCKDRILL AB</h1>
            <p className="text-sm opacity-80 uppercase tracking-widest font-medium">Complete Management System • Ultimate Edition</p>
          </div>
        </div>

        <div className="flex-1"></div>

        <div className="flex items-center space-x-4 z-10 text-black font-semibold">
           <button onClick={handleExport} className="flex items-center space-x-2 bg-white px-3 py-1.5 rounded hover:bg-gray-100 transition shadow-sm text-sm">
             <Download size={16} /> <span>Export</span>
           </button>
           <label className="flex items-center space-x-2 bg-white px-3 py-1.5 rounded hover:bg-gray-100 cursor-pointer transition shadow-sm text-sm">
             <Upload size={16} /> <span>Import</span>
             <input type="file" className="hidden" onChange={handleImport} />
           </label>
           <div className="relative group">
              <button className="p-2 bg-white rounded shadow-sm hover:bg-gray-100 transition">
                <Bell size={20} className={notifications.length > 0 ? "text-red-500 animate-pulse" : ""} />
                {notifications.length > 0 && <span className="absolute -top-1 -right-1 bg-red-600 text-white text-[10px] w-4 h-4 rounded-full flex items-center justify-center">{notifications.length}</span>}
              </button>
              <div className="absolute right-0 top-full mt-2 w-64 bg-white border border-gray-200 rounded shadow-xl opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none group-hover:pointer-events-auto z-50 p-3">
                <h3 className="font-bold border-bottom pb-2 mb-2 text-xs uppercase text-gray-400">Notifications</h3>
                {notifications.length === 0 ? <p className="text-gray-500 text-xs">No alerts today</p> : 
                  notifications.map((n, i) => <p key={i} className="text-xs mb-2 text-gray-800 border-l-2 border-[#FDB913] pl-2">{n}</p>)}
              </div>
           </div>
        </div>
      </header>

      {/* Tabs Navigation */}
      <nav className="bg-white border-b border-gray-200 sticky top-0 z-40">
        <div className="max-w-7xl mx-auto flex">
          {tabs.map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex items-center space-x-2 px-6 py-4 transition-all border-b-2 ${
                activeTab === tab.id 
                ? 'border-[#FDB913] text-black font-bold bg-gray-50' 
                : 'border-transparent text-gray-500 hover:text-black hover:bg-gray-50'
              }`}
            >
              {tab.icon}
              <span className="text-sm uppercase tracking-wide">{tab.name}</span>
            </button>
          ))}
        </div>
      </nav>

      {/* Main Content Area */}
      <main className="flex-1 p-6 max-w-[1600px] mx-auto w-full">
        {activeTab === 'calendar' && (
          <CalendarView 
            tasks={data.tasks} 
            safetyStatus={data.safetyStatus} 
            updateSafetyStatus={(newStatus) => updateData({ safetyStatus: newStatus })} 
          />
        )}
        {activeTab === 'tasks' && (
          <TaskBoard 
            tasks={data.tasks} 
            users={data.users} 
            categories={data.categories} 
            projects={data.projects}
            updateTasks={(tasks) => updateData({ tasks })} 
          />
        )}
        {activeTab === 'dashboard' && <Dashboard state={data} />}
        {activeTab === 'projects' && (
          <ProjectBoard 
            projects={data.projects} 
            users={data.users} 
            updateProjects={(projects) => updateData({ projects })} 
          />
        )}
        {activeTab === 'activities' && (
          <ActivityTracker 
            activities={data.activities} 
            users={data.users} 
            updateActivities={(activities) => updateData({ activities })} 
          />
        )}
        {activeTab === 'kpis' && (
          <KPITracker 
            kpis={data.kpis} 
            updateKpis={(kpis) => updateData({ kpis })} 
          />
        )}
        {activeTab === 'masters' && (
          <Masters 
            users={data.users} 
            categories={data.categories} 
            updateUsers={(users) => updateData({ users })} 
            updateCategories={(categories) => updateData({ categories })} 
          />
        )}
      </main>

      {/* Footer / Status Bar */}
      <footer className="bg-white border-t border-gray-200 py-3 px-8 flex justify-between items-center text-[10px] text-gray-400 font-medium uppercase tracking-widest">
        <div className="flex items-center space-x-4">
          <span>© {new Date().getFullYear()} EPIROC ROCKDRILL AB</span>
          <span className="text-[#FDB913]">● AUTO-SAVE ACTIVE</span>
          <span className="flex items-center"><BrainCircuit size={10} className="mr-1" /> AI ANALYTICS READY</span>
        </div>
        <div className="flex items-center space-x-2">
           <span>DB STATUS: CONNECTED</span>
           <span className="w-1.5 h-1.5 rounded-full bg-green-500"></span>
        </div>
      </footer>
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, 
  PieChart, Pie, Cell, LineChart, Line 
} from 'recharts';
import { AppState } from '../types';
import { BRAND } from '../constants';
import { 
  Briefcase, CheckCircle2, Clock, AlertTriangle, 
  BarChart3, Users, CalendarDays, Zap
} from 'lucide-react';

const COLORS = [BRAND.INFO, BRAND.SUCCESS, BRAND.WARNING, BRAND.DANGER, '#9b59b6', '#1abc9c', '#34495e'];

const Dashboard: React.FC<{ state: AppState }> = ({ state }) => {
  const stats = useMemo(() => {
    const total = state.tasks.length;
    const completed = state.tasks.filter(t => t.status === 'Completed').length;
    const inProgress = state.tasks.filter(t => t.status === 'In Progress').length;
    const today = new Date().toISOString().split('T')[0];
    const overdue = state.tasks.filter(t => t.dueDate < today && t.status !== 'Completed').length;
    const completionRate = total > 0 ? Math.round((completed / total) * 100) : 0;

    return { total, completed, inProgress, overdue, completionRate };
  }, [state.tasks]);

  const workloadData = useMemo(() => {
    const counts: Record<string, number> = {};
    state.tasks.forEach(t => {
      if (t.status !== 'Completed') {
        counts[t.owner] = (counts[t.owner] || 0) + 1;
      }
    });
    return Object.entries(counts).map(([name, value]) => ({ name, value }));
  }, [state.tasks]);

  const categoryData = useMemo(() => {
    const counts: Record<string, number> = {};
    state.tasks.forEach(t => {
      counts[t.category] = (counts[t.category] || 0) + 1;
    });
    return Object.entries(counts).map(([name, value]) => ({ name, value }));
  }, [state.tasks]);

  const statusData = useMemo(() => {
    const counts: Record<string, number> = {
      'Not Started': 0, 'In Progress': 0, 'Completed': 0, 'Blocked': 0, 'On Hold': 0
    };
    state.tasks.forEach(t => {
      counts[t.status] = (counts[t.status] || 0) + 1;
    });
    return Object.entries(counts).map(([name, value]) => ({ name, value }));
  }, [state.tasks]);

  const kpiData = useMemo(() => {
    return state.kpis.map(k => ({
      name: k.name.substring(0, 20),
      completion: k.completion
    }));
  }, [state.kpis]);

  return (
    <div className="space-y-6">
      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        {[
          { label: 'Total Tasks', value: stats.total, icon: <Briefcase size={24} />, color: 'bg-blue-600' },
          { label: 'Completion', value: `${stats.completionRate}%`, icon: <CheckCircle2 size={24} />, color: 'bg-green-600' },
          { label: 'In Progress', value: stats.inProgress, icon: <Clock size={24} />, color: 'bg-orange-500' },
          { label: 'Overdue', value: stats.overdue, icon: <AlertTriangle size={24} />, color: 'bg-red-600' },
        ].map((card, i) => (
          <div key={i} className={`${card.color} text-white p-6 rounded-lg shadow-md relative overflow-hidden`}>
            <div className="flex justify-between items-start">
              <div>
                <p className="text-xs uppercase font-bold opacity-80 mb-1">{card.label}</p>
                <p className="text-3xl font-extrabold">{card.value}</p>
              </div>
              <div className="bg-white/20 p-2 rounded">{card.icon}</div>
            </div>
            <div className="absolute -bottom-2 -right-2 opacity-10 rotate-12">{card.icon}</div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Workload */}
        <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-100">
          <div className="flex items-center space-x-2 mb-6">
            <Users className="text-[#FDB913]" size={20} />
            <h3 className="text-lg font-bold">Workload Distribution</h3>
          </div>
          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={workloadData} layout="vertical">
                <CartesianGrid strokeDasharray="3 3" horizontal={false} />
                <XAxis type="number" />
                <YAxis dataKey="name" type="category" width={120} tick={{fontSize: 12}} />
                <Tooltip />
                <Bar dataKey="value" fill={BRAND.INFO} radius={[0, 4, 4, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Task Categories */}
        <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-100">
          <div className="flex items-center space-x-2 mb-6">
            <Zap className="text-[#FDB913]" size={20} />
            <h3 className="text-lg font-bold">Category Distribution</h3>
          </div>
          <div className="h-[300px] flex">
             <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={categoryData}
                    cx="50%"
                    cy="50%"
                    innerRadius={60}
                    outerRadius={80}
                    paddingAngle={5}
                    dataKey="value"
                  >
                    {categoryData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                    ))}
                  </Pie>
                  <Tooltip />
                  <Legend verticalAlign="bottom" height={36} wrapperStyle={{fontSize: '11px'}} />
                </PieChart>
              </ResponsiveContainer>
          </div>
        </div>

        {/* Status Chart */}
        <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-100">
          <div className="flex items-center space-x-2 mb-6">
            <BarChart3 className="text-[#FDB913]" size={20} />
            <h3 className="text-lg font-bold">Task Progress Status</h3>
          </div>
          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={statusData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} />
                <XAxis dataKey="name" tick={{fontSize: 12}} />
                <YAxis />
                <Tooltip />
                <Bar dataKey="value" fill={BRAND.SUCCESS} radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* KPI Tracking */}
        <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-100">
          <div className="flex items-center space-x-2 mb-6">
            <Target className="text-[#FDB913]" size={20} />
            <h3 className="text-lg font-bold">KPI Performance Overview</h3>
          </div>
          {kpiData.length > 0 ? (
            <div className="h-[300px]">
              <ResponsiveContainer width="100%" height="100%">
                <LineChart data={kpiData}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="name" tick={{fontSize: 10}} />
                  <YAxis domain={[0, 100]} />
                  <Tooltip />
                  <Line type="monotone" dataKey="completion" stroke={BRAND.WARNING} strokeWidth={3} dot={{r: 6}} />
                </LineChart>
              </ResponsiveContainer>
            </div>
          ) : (
            <div className="h-[300px] flex items-center justify-center text-gray-400 italic">
              No KPI data available
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { Task, Status, Priority } from '../types';
import { BRAND } from '../constants';
import { Plus, Edit2, Trash2, Search, Filter, Download } from 'lucide-react';

interface TaskBoardProps {
  tasks: Task[];
  users: string[];
  categories: string[];
  projects: any[];
  updateTasks: (tasks: Task[]) => void;
}

const TaskBoard: React.FC<TaskBoardProps> = ({ tasks, users, categories, projects, updateTasks }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterOwner, setFilterOwner] = useState('All');
  const [editingTask, setEditingTask] = useState<Task | null>(null);
  const [showModal, setShowModal] = useState(false);

  const filteredTasks = useMemo(() => {
    return tasks.filter(t => {
      const matchSearch = t.task.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          t.owner.toLowerCase().includes(searchTerm.toLowerCase());
      const matchOwner = filterOwner === 'All' || t.owner === filterOwner;
      return matchSearch && matchOwner;
    });
  }, [tasks, searchTerm, filterOwner]);

  const handleSaveTask = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const taskData: Partial<Task> = {
      task: formData.get('task') as string,
      owner: formData.get('owner') as string,
      category: formData.get('category') as string,
      project: formData.get('project') as string,
      status: formData.get('status') as Status,
      priority: formData.get('priority') as Priority,
      progress: parseInt(formData.get('progress') as string),
      hours: parseFloat(formData.get('hours') as string),
      startDate: formData.get('startDate') as string,
      dueDate: formData.get('dueDate') as string,
      notes: formData.get('notes') as string,
    };

    if (editingTask) {
      updateTasks(tasks.map(t => t.id === editingTask.id ? { ...t, ...taskData } : t));
    } else {
      const newTask: Task = {
        id: Math.random().toString(36).substr(2, 9),
        ...taskData as any
      };
      updateTasks([...tasks, newTask]);
    }
    setShowModal(false);
    setEditingTask(null);
  };

  const handleDelete = (id: string) => {
    if (confirm('Delete this task?')) {
      updateTasks(tasks.filter(t => t.id !== id));
    }
  };

  const getStatusColor = (status: Status) => {
    switch (status) {
      case 'Completed': return 'bg-green-100 text-green-800';
      case 'In Progress': return 'bg-blue-100 text-blue-800';
      case 'Blocked': return 'bg-red-100 text-red-800';
      case 'On Hold': return 'bg-gray-100 text-gray-800';
      default: return 'bg-yellow-100 text-yellow-800';
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap justify-between items-center gap-4 bg-white p-4 rounded-lg shadow-sm border border-gray-100">
        <div className="flex items-center space-x-4 flex-1 max-w-2xl">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
            <input
              type="text"
              placeholder="Search tasks or owners..."
              className="w-full pl-10 pr-4 py-2 border border-gray-200 rounded-md focus:outline-none focus:ring-2 focus:ring-[#FDB913]"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="flex items-center space-x-2">
            <Filter size={18} className="text-gray-400" />
            <select
              className="border border-gray-200 rounded-md px-3 py-2 text-sm"
              value={filterOwner}
              onChange={(e) => setFilterOwner(e.target.value)}
            >
              <option value="All">All Owners</option>
              {users.map(u => <option key={u} value={u}>{u}</option>)}
            </select>
          </div>
        </div>
        <button
          onClick={() => { setEditingTask(null); setShowModal(true); }}
          className="bg-black text-[#FDB913] px-6 py-2 rounded-md font-bold flex items-center space-x-2 hover:bg-[#222] transition"
        >
          <Plus size={20} />
          <span>ADD TASK</span>
        </button>
      </div>

      <div className="bg-white rounded-lg shadow-sm border border-gray-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead className="bg-gray-50 border-b border-gray-200">
              <tr>
                <th className="px-6 py-4 text-xs font-bold uppercase tracking-wider text-gray-500">Task</th>
                <th className="px-6 py-4 text-xs font-bold uppercase tracking-wider text-gray-500">Owner</th>
                <th className="px-6 py-4 text-xs font-bold uppercase tracking-wider text-gray-500">Status</th>
                <th className="px-6 py-4 text-xs font-bold uppercase tracking-wider text-gray-500">Priority</th>
