  return (
    <div className="min-h-screen flex flex-col bg-[#F8F9FA]">
      <header className={`transition-all duration-500 h-24 flex items-center px-8 relative overflow-hidden ${fileHandle ? 'bg-black text-white' : 'bg-[#FDB913] text-black'}`}>
