interface TaskBoardProps {
  tasks: Task[];
  users: string[];
  categories: string[];
  projects: any[];
  okrs: OKR[];
  updateTasks: (tasks: Task[]) => void;
}

const TaskBoard: React.FC<TaskBoardProps> = ({ tasks, users, categories, projects, okrs, updateTasks }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterOwner, setFilterOwner] = useState('All');
  const [editingTask, setEditingTask] = useState<Task | null>(null);
  const [showModal, setShowModal] = useState(false);
  const [activeSubTab, setActiveSubTab] = useState<'details' | 'history'>('details');

  const filteredTasks = useMemo(() => {
    return tasks.filter(t => {
      const matchSearch = t.task.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          t.owner.toLowerCase().includes(searchTerm.toLowerCase());
      const matchOwner = filterOwner === 'All' || t.owner === filterOwner;
      return matchSearch && matchOwner;
    });
  }, [tasks, searchTerm, filterOwner]);

  const handleSaveTask = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const taskData: Partial<Task> = {
      task: formData.get('task') as string,
      owner: formData.get('owner') as string,
      category: formData.get('category') as string,
      project: formData.get('project') as string,
      status: formData.get('status') as Status,
      priority: formData.get('priority') as Priority,
      progress: parseInt(formData.get('progress') as string),
      hours: parseFloat(formData.get('hours') as string),
      startDate: formData.get('startDate') as string,
      dueDate: formData.get('dueDate') as string,
      okrLink: formData.get('okrLink') as string,
      notes: formData.get('notes') as string,
    };

    if (editingTask) {
      const history = [...(editingTask.history || [])];
      if (editingTask.status !== taskData.status) {
        history.push({ timestamp: new Date().toISOString(), change: `Status changed to ${taskData.status}` });
      }
      if (editingTask.owner !== taskData.owner) {
        history.push({ timestamp: new Date().toISOString(), change: `Owner reassigned to ${taskData.owner}` });
      }
      updateTasks(tasks.map(t => t.id === editingTask.id ? { ...t, ...taskData, history } : t));
    } else {
      const newTask: Task = {
        id: Math.random().toString(36).substr(2, 9),
        history: [{ timestamp: new Date().toISOString(), change: 'Task created' }],
        comments: [],
        ...taskData as any
      };
      updateTasks([...tasks, newTask]);
    }
    setShowModal(false);
    setEditingTask(null);
  };

  const getStatusColor = (status: Status) => {
    switch (status) {
      case 'Completed': return 'bg-green-100 text-green-800';
      case 'In Progress': return 'bg-blue-100 text-blue-800';
      case 'Blocked': return 'bg-red-100 text-red-800';
      case 'On Hold': return 'bg-gray-100 text-gray-800';
      default: return 'bg-yellow-100 text-yellow-800';
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap justify-between items-center gap-4 bg-white p-4 rounded shadow-sm border border-gray-100">
        <div className="flex items-center space-x-4 flex-1 max-w-2xl">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
            <input
              type="text"
              placeholder="Filter tasks..."
              className="w-full pl-10 pr-4 py-2 border border-gray-200 rounded text-sm outline-none"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <select
            className="border border-gray-200 rounded px-3 py-2 text-xs font-black uppercase"
            value={filterOwner}
            onChange={(e) => setFilterOwner(e.target.value)}
          >
            <option value="All">All People</option>
            {users.map(u => <option key={u} value={u}>{u}</option>)}
          </select>
        </div>
        <button
          onClick={() => { setEditingTask(null); setShowModal(true); setActiveSubTab('details'); }}
          className="bg-black text-[#FDB913] px-6 py-2 rounded font-black text-xs uppercase tracking-widest shadow-lg"
        >
          Add Pulse Task
        </button>
      </div>

      <div className="bg-white rounded shadow-sm border border-gray-100 overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-gray-50 border-b border-gray-200">
            <tr>
              <th className="px-6 py-4 text-[10px] font-black uppercase text-gray-400 tracking-widest">Operation Detail</th>
              <th className="px-6 py-4 text-[10px] font-black uppercase text-gray-400 tracking-widest">Stakeholder</th>
              <th className="px-6 py-4 text-[10px] font-black uppercase text-gray-400 tracking-widest">Status</th>
              <th className="px-6 py-4 text-[10px] font-black uppercase text-gray-400 tracking-widest text-right">Progress</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-100">
            {filteredTasks.map(t => (
              <tr key={t.id} className="hover:bg-gray-50/50 transition group cursor-pointer" onClick={() => { setEditingTask(t); setShowModal(true); }}>
                <td className="px-6 py-4">
                  <p className="font-bold text-gray-800 text-sm">{t.task}</p>
                  <div className="flex items-center space-x-2 mt-1">
                    <span className="text-[9px] font-black uppercase bg-gray-100 px-2 py-0.5 rounded">{t.category}</span>
                    <span className={`text-[9px] font-black uppercase ${t.priority === 'High' ? 'text-red-500' : 'text-gray-400'}`}>{t.priority} PRIORITY</span>
                  </div>
                </td>
                <td className="px-6 py-4 text-sm font-bold text-gray-700">{t.owner}</td>
                <td className="px-6 py-4">
                  <span className={`px-2 py-1 rounded text-[9px] font-black uppercase ${getStatusColor(t.status)}`}>{t.status}</span>
                </td>
                <td className="px-6 py-4 text-right">
                  <div className="flex flex-col items-end">
                    <span className="text-xs font-black text-gray-900">{t.progress}%</span>
                    <div className="w-24 bg-gray-100 h-1 rounded-full mt-1">
                      <div className="bg-black h-1 rounded-full" style={{ width: `${t.progress}%` }}></div>
                    </div>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="bg-white rounded shadow-2xl w-full max-w-3xl max-h-[90vh] overflow-hidden flex flex-col">
            <div className="p-6 bg-[#FDB913] text-black flex justify-between items-center shrink-0">
              <h2 className="text-xl font-black uppercase tracking-tight">{editingTask ? 'Manage Operation' : 'Initiate New Operation'}</h2>
              <button onClick={() => setShowModal(false)} className="font-black text-2xl">×</button>
            </div>

            <div className="flex bg-gray-50 border-b shrink-0">
              <button onClick={() => setActiveSubTab('details')} className={`px-8 py-3 text-[10px] font-black uppercase tracking-widest ${activeSubTab === 'details' ? 'border-b-2 border-black bg-white' : 'text-gray-400'}`}>Details</button>
              {editingTask && (
                <button onClick={() => setActiveSubTab('history')} className={`px-8 py-3 text-[10px] font-black uppercase tracking-widest ${activeSubTab === 'history' ? 'border-b-2 border-black bg-white' : 'text-gray-400'}`}>History Log</button>
              )}
            </div>

            <div className="flex-1 overflow-y-auto p-6 custom-scrollbar">
              {activeSubTab === 'details' ? (
                <form id="taskForm" onSubmit={handleSaveTask} className="space-y-4">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="col-span-2">
                      <label className="block text-[10px] font-black uppercase text-gray-500 mb-1 tracking-widest">Task Description *</label>
                      <input name="task" required defaultValue={editingTask?.task} className="w-full border p-3 rounded font-bold" />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black uppercase text-gray-500 mb-1 tracking-widest">Stakeholder *</label>
                      <select name="owner" required defaultValue={editingTask?.owner} className="w-full border p-2 rounded">
                        {users.map(u => <option key={u} value={u}>{u}</option>)}
                      </select>
                    </div>
                    <div>
                      <label className="block text-[10px] font-black uppercase text-gray-500 mb-1 tracking-widest">Taxonomy Category</label>
                      <select name="category" defaultValue={editingTask?.category} className="w-full border p-2 rounded">
                        {categories.map(c => <option key={c} value={c}>{c}</option>)}
                      </select>
                    </div>
                    <div>
                      <label className="block text-[10px] font-black uppercase text-gray-500 mb-1 tracking-widest">Associated Project</label>
                      <select name="project" defaultValue={editingTask?.project} className="w-full border p-2 rounded">
                        <option value="">No Project</option>
                        {projects.map(p => <option key={p.id} value={p.name}>{p.name}</option>)}
                      </select>
                    </div>
                    <div>
                      <label className="block text-[10px] font-black uppercase text-gray-500 mb-1 tracking-widest">Strategic OKR Link</label>
                      <select name="okrLink" defaultValue={editingTask?.okrLink} className="w-full border p-2 rounded">
                        <option value="">No Strategic Link</option>
                        {okrs.map(o => <option key={o.id} value={o.id}>{o.objective}</option>)}
                      </select>
                    </div>
                    <div>
                      <label className="block text-[10px] font-black uppercase text-gray-500 mb-1 tracking-widest">Status</label>
                      <select name="status" defaultValue={editingTask?.status || 'Not Started'} className="w-full border p-2 rounded">
                        {['Not Started', 'In Progress', 'Completed', 'Blocked', 'On Hold'].map(s => <option key={s} value={s}>{s}</option>)}
                      </select>
                    </div>
                    <div>
                      <label className="block text-[10px] font-black uppercase text-gray-500 mb-1 tracking-widest">Priority Level</label>
                      <select name="priority" defaultValue={editingTask?.priority || 'Medium'} className="w-full border p-2 rounded">
                        <option value="Low">Low</option>
                        <option value="Medium">Medium</option>
                        <option value="High">High Priority</option>
                      </select>
                    </div>
                    <div>
                      <label className="block text-[10px] font-black uppercase text-gray-500 mb-1 tracking-widest">Progress (%)</label>
                      <input type="number" name="progress" min="0" max="100" defaultValue={editingTask?.progress || 0} className="w-full border p-2 rounded" />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black uppercase text-gray-500 mb-1 tracking-widest">Est. Duration (Hrs)</label>
                      <input type="number" step="0.5" name="hours" defaultValue={editingTask?.hours || 0} className="w-full border p-2 rounded" />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black uppercase text-gray-500 mb-1 tracking-widest">Deployment Date</label>
                      <input type="date" name="startDate" defaultValue={editingTask?.startDate} className="w-full border p-2 rounded" />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black uppercase text-gray-500 mb-1 tracking-widest">Target Delivery Date</label>
                      <input type="date" name="dueDate" defaultValue={editingTask?.dueDate} className="w-full border p-2 rounded" />
                    </div>
                    <div className="col-span-2">
                      <label className="block text-[10px] font-black uppercase text-gray-500 mb-1 tracking-widest">Operational Notes</label>
                      <textarea name="notes" rows={3} defaultValue={editingTask?.notes} className="w-full border p-3 rounded text-sm"></textarea>
                    </div>
                  </div>
                </form>
              ) : (
                <div className="space-y-4">
                  {editingTask?.history?.map((entry, idx) => (
                    <div key={idx} className="flex space-x-4">
                      <div className="w-24 shrink-0 text-[9px] font-black text-gray-400 mt-1 uppercase leading-none">
                        {format(parseISO(entry.timestamp), 'MMM d, HH:mm')}
                      </div>
                      <div className="flex-1 pb-4 border-l-2 border-gray-100 pl-6 relative">
                         <div className="absolute w-2 h-2 rounded-full bg-black -left-1.5 top-0.5"></div>
                         <p className="text-xs font-black text-gray-800 uppercase tracking-tight">{entry.change}</p>
                      </div>
                    </div>
                  ))}
                  {(!editingTask?.history || editingTask.history.length === 0) && (
                    <p className="text-sm text-gray-400 italic">No history logged for this operation.</p>
                  )}
                </div>
              )}
            </div>

            <div className="p-6 border-t bg-gray-50 flex justify-between items-center shrink-0">
               {editingTask && (
                 <button type="button" onClick={() => { if(confirm('Purge this operation?')) { updateTasks(tasks.filter(t => t.id !== editingTask.id)); setShowModal(false); } }} className="text-red-500 text-[10px] font-black uppercase tracking-widest">Delete Operation</button>
               )}
               <div className="flex space-x-3 ml-auto">
                <button type="button" onClick={() => setShowModal(false)} className="px-6 py-2 text-[10px] font-black uppercase">Cancel</button>
                <button type="submit" form="taskForm" className="px-8 py-3 bg-black text-[#FDB913] rounded font-black uppercase tracking-widest shadow-xl">Commit Changes</button>
               </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default TaskBoard;

export type Status = 'Not Started' | 'In Progress' | 'Completed' | 'Blocked' | 'On Hold';
export type Priority = 'High' | 'Medium' | 'Low';
export type ProjectStatus = 'Planning' | 'In Progress' | 'On Hold' | 'Completed' | 'Cancelled';

export interface HistoryEntry {
  timestamp: string;
  change: string;
}

export interface Comment {
  user: string;
  timestamp: string;
  comment: string;
}

export interface Booking {
  id: string;
  date: string;
  userId: string;
  targetId: string; // Task or Project ID
  targetType: 'task' | 'project';
  hours: number;
  description: string;
}

export interface Task {
  id: string;
  category: string;
  task: string;
  owner: string;
  project: string;
  status: Status;
  priority: Priority;
  progress: number;
  hours: number; // Estimated hours
  startDate: string;
  dueDate: string;
  originalDueDate?: string;
  notes: string;
  okrLink?: string;
  history: HistoryEntry[];
  comments: Comment[];
}

export interface Project {
  id: string;
  name: string;
  manager: string;
  status: ProjectStatus;
  startDate: string;
  endDate: string;
  hours: number; // Estimated hours
  description: string;
}

export interface Idea {
  id: string;
  idea: string;
  proposer: string;
  impact: 'High' | 'Medium' | 'Low';
  cost: 'High' | 'Medium' | 'Low';
  status: 'New' | 'Under Review' | 'Approved' | 'Implemented' | 'Rejected';
  date: string;
}

export interface Kudos {
  id: string;
  from: string;
  to: string;
  reason: string;
  date: string;
}

export interface KeyResult {
  id: string;
  kr: string;
}

export interface OKR {
  id: string;
  objective: string;
  keyResults: KeyResult[];
}

export interface User {
  name: string;
  capacity: number;
}

export type SafetyStatusEntry = { status: 'green' | 'yellow' | 'red'; notes: string };
export type SafetyStatus = Record<string, SafetyStatusEntry>;

export interface AppState {
  tasks: Task[];
  projects: Project[];
  ideas: Idea[];
  kudos: Kudos[];
  okrs: OKR[];
  users: User[];
  bookings: Booking[];
  categories: string[];
  safetyStatus: Record<string, { status: 'green' | 'yellow' | 'red'; notes: string }>;
  dailyAgenda: Record<string, string>;
  lastBackupDate?: string;
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { 
  Calendar, CheckSquare, LayoutDashboard, Target, Clock, 
  Settings, Save, HardDrive, FileCode, Wifi, WifiOff,
  Lightbulb, Award, BarChart3, ListChecks, RefreshCw,
  Download, Upload, ShieldCheck, Database, History, Eye
} from 'lucide-react';
import { AppState, Task, Project, User, Idea, Kudos, OKR, Booking } from './types';
import { DEFAULT_USERS, DEFAULT_CATEGORIES, DEFAULT_AGENDA } from './constants';
import Dashboard from './components/Dashboard';
import TaskBoard from './components/TaskBoard';
import ProjectBoard from './components/ProjectBoard';
import CalendarView from './components/CalendarView';
import IdeaMatrix from './components/IdeaMatrix';
import KudosBoard from './components/KudosBoard';
import OKRBoard from './components/OKRBoard';
import Masters from './components/Masters';
import HoursBooking from './components/HoursBooking';

const STORAGE_KEY = 'epiroc_management_data_v4';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isReadOnly, setIsReadOnly] = useState(false);
  const [data, setData] = useState<AppState>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) return JSON.parse(saved);
    return {
      tasks: [],
      projects: [],
      ideas: [],
      kudos: [],
      okrs: [],
      users: DEFAULT_USERS.map(name => ({ name, capacity: 160 })), // Monthly capacity default
      bookings: [],
      categories: DEFAULT_CATEGORIES,
      safetyStatus: {},
      dailyAgenda: DEFAULT_AGENDA
    };
  });

  const [fileHandle, setFileHandle] = useState<FileSystemFileHandle | null>(null);
  const [backupDirHandle, setBackupDirHandle] = useState<FileSystemDirectoryHandle | null>(null);
  const [isAutoSaving, setIsAutoSaving] = useState(false);
  const [lastFileHash, setLastFileHash] = useState<string>('');
  const [lastSyncTime, setLastSyncTime] = useState<Date | null>(null);

  const isUpdatingRef = useRef(false);
  const dataRef = useRef(data);

  useEffect(() => {
    dataRef.current = data;
    if (!isReadOnly) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
    }
  }, [data, isReadOnly]);

  // Auto Backup Logic
  useEffect(() => {
    const runBackup = async () => {
      if (!backupDirHandle || isReadOnly) return;
      const today = new Date().toISOString().split('T')[0];
      if (data.lastBackupDate === today) return;

      try {
        const fileName = `epiroc_backup_${today}.json`;
        const fileHandle = await backupDirHandle.getFileHandle(fileName, { create: true });
        // @ts-ignore
        const writable = await fileHandle.createWritable();
        await writable.write(JSON.stringify(data, null, 2));
        await writable.close();
        setData(prev => ({ ...prev, lastBackupDate: today }));
        console.log("Daily backup completed:", fileName);
      } catch (e) {
        console.error("Backup failed", e);
      }
    };
    runBackup();
  }, [backupDirHandle, data.lastBackupDate, isReadOnly]);

  const mergeData = (local: AppState, remote: AppState): AppState => {
    // Smart merge: unique IDs preserved, latest versions taken
    const mergeById = (a: any[], b: any[]) => {
      const map = new Map();
      [...a, ...b].forEach(item => {
        const existing = map.get(item.id);
        if (!existing) {
          map.set(item.id, item);
        }
      });
      return Array.from(map.values());
    };

    return {
      ...remote,
      tasks: mergeById(local.tasks || [], remote.tasks || []),
      projects: mergeById(local.projects || [], remote.projects || []),
      ideas: mergeById(local.ideas || [], remote.ideas || []),
      kudos: mergeById(local.kudos || [], remote.kudos || []),
      okrs: mergeById(local.okrs || [], remote.okrs || []),
      bookings: mergeById(local.bookings || [], remote.bookings || []),
      safetyStatus: { ...(local.safetyStatus || {}), ...(remote.safetyStatus || {}) }
    };
  };

  const linkSharedFile = async () => {
    try {
      // @ts-ignore
      const [handle] = await window.showOpenFilePicker({
        types: [{ description: 'Epiroc Database', accept: { 'application/json': ['.json'] } }],
        excludeAcceptAllOption: true,
        multiple: false
      });
      setFileHandle(handle);
      setIsReadOnly(false);
      const file = await handle.getFile();
      const content = await file.text();
      if (content) {
        const remoteData = JSON.parse(content);
        setData(prev => mergeData(prev, remoteData));
        setLastFileHash(content);
      }
      setLastSyncTime(new Date());
    } catch (err) { console.error(err); }
  };

  const linkBackupDir = async () => {
    try {
      // @ts-ignore
      const handle = await window.showDirectoryPicker();
      setBackupDirHandle(handle);
    } catch (e) { console.error(e); }
  };

  const importBackupFile = async () => {
    try {
      // @ts-ignore
      const [handle] = await window.showOpenFilePicker({
        types: [{ description: 'Epiroc Backup', accept: { 'application/json': ['.json'] } }],
        multiple: false
      });
      const file = await handle.getFile();
      const content = await file.text();
      const backupData = JSON.parse(content);
      setData(backupData);
      setIsReadOnly(true); // Enter Read-Only View
      setActiveTab('dashboard');
      alert("VIEW-ONLY MODE: You are viewing a backup. Edits are disabled.");
    } catch (e) { console.error(e); }
  };

  const exportData = () => {
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `epiroc_full_export_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
  };

  const importData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const newData = JSON.parse(evt.target?.result as string);
        if (confirm("Restore this data? Current local data will be replaced.")) {
          setData(newData);
          setIsReadOnly(false);
        }
      } catch (err) { alert("Invalid JSON file"); }
    };
    reader.readAsText(file);
  };

  useEffect(() => {
    if (!fileHandle || isReadOnly) return;
    const interval = setInterval(async () => {
      try {
        setIsAutoSaving(true);
        const file = await fileHandle.getFile();
        const content = await file.text();
        if (content !== lastFileHash) {
          const remoteData = JSON.parse(content);
          isUpdatingRef.current = true;
          const merged = mergeData(dataRef.current, remoteData);
          setData(merged);
          setLastFileHash(JSON.stringify(merged));
          setLastSyncTime(new Date());
          setTimeout(() => { isUpdatingRef.current = false; }, 500);
        } else {
          const localContent = JSON.stringify(dataRef.current, null, 2);
          if (localContent !== lastFileHash) {
            // @ts-ignore
            const writable = await fileHandle.createWritable();
            await writable.write(localContent);
            await writable.close();
            setLastFileHash(localContent);
            setLastSyncTime(new Date());
          }
        }
      } catch (err) { console.error(err); } finally { setTimeout(() => setIsAutoSaving(false), 500); }
    }, 5000);
    return () => clearInterval(interval);
  }, [fileHandle, lastFileHash, isReadOnly]);

  const updateData = (newData: Partial<AppState>) => {
    if (isReadOnly) return;
    setData(prev => ({ ...prev, ...newData }));
  };

  const tabs = [
    { id: 'dashboard', name: 'Dashboard', icon: <LayoutDashboard size={18} /> },
    { id: 'calendar', name: 'Calendar', icon: <Calendar size={18} /> },
    { id: 'tasks', name: 'Tasks', icon: <CheckSquare size={18} /> },
    { id: 'projects', name: 'Projects', icon: <Target size={18} /> },
    { id: 'bookings', name: 'Time Logs', icon: <Clock size={18} /> },
    { id: 'okrs', name: 'OKRs', icon: <ListChecks size={18} /> },
    { id: 'ideas', name: 'Ideas', icon: <Lightbulb size={18} /> },
    { id: 'kudos', name: 'Kudos', icon: <Award size={18} /> },
    { id: 'masters', name: 'Masters', icon: <Settings size={18} /> },
  ];

  return (
    <div className="min-h-screen flex flex-col bg-[#F8F9FA]">
      {isReadOnly && (
        <div className="bg-red-600 text-white text-[10px] font-black uppercase tracking-[0.2em] py-1 px-8 text-center flex items-center justify-center space-x-4">
          <Eye size={12} />
          <span>VIEWING HISTORICAL BACKUP - READ ONLY MODE</span>
          <button onClick={() => { setIsReadOnly(false); window.location.reload(); }} className="underline ml-4">Exit & Refresh</button>
        </div>
      )}

      <header className={`transition-all duration-500 h-24 flex items-center px-8 relative overflow-hidden ${isReadOnly ? 'bg-zinc-800 text-white' : fileHandle ? 'bg-black text-white' : 'bg-[#FDB913] text-black'}`}>
        <div className="absolute top-0 right-0 w-1/3 h-full bg-white/5 skew-x-[-20deg] translate-x-20 z-0"></div>
        <div className="flex items-center z-10 space-x-6">
          <div className={`w-14 h-14 flex items-center justify-center font-black text-3xl rounded-sm border-2 ${fileHandle ? 'bg-[#FDB913] text-black border-black/10' : 'bg-black text-[#FDB913] border-white/10'}`}>E</div>
          <div>
            <h1 className="text-2xl font-black tracking-tight uppercase">Epiroc Pulse</h1>
            <div className="flex items-center space-x-3 text-[10px] uppercase tracking-widest font-black opacity-80">
              <span className="flex items-center">
                {fileHandle ? <Wifi size={10} className="text-green-400 mr-1" /> : <WifiOff size={10} className="mr-1" />}
                {fileHandle ? 'TEAM SYNC ACTIVE' : 'LOCAL MODE'}
              </span>
              <span>•</span>
              <span className="flex items-center">
                <ShieldCheck size={10} className={`mr-1 ${backupDirHandle ? 'text-green-400' : 'text-gray-400'}`} />
                BACKUP: {backupDirHandle ? 'ENABLED' : 'OFF'}
              </span>
            </div>
          </div>
        </div>

        <div className="flex-1"></div>

        <div className="flex items-center space-x-4 z-10">
           {!isReadOnly && (
             <div className="flex space-x-2">
                <button onClick={exportData} title="Export Data" className="p-2 bg-white/10 rounded hover:bg-white/20 transition"><Download size={18} /></button>
                <label className="p-2 bg-white/10 rounded hover:bg-white/20 transition cursor-pointer" title="Import Data">
                  <Upload size={18} />
                  <input type="file" className="hidden" accept=".json" onChange={importData} />
                </label>
             </div>
           )}

           <button onClick={importBackupFile} className="bg-white/10 text-white px-4 py-3 rounded font-black text-[10px] uppercase tracking-widest flex items-center space-x-2 border border-white/10 hover:bg-white/20 transition">
             <History size={14} />
             <span>Restore Backup</span>
           </button>

           {fileHandle ? (
             <div className="flex items-center bg-white/10 px-6 py-3 rounded border border-white/5 space-x-6">
                <div className="flex flex-col items-end border-r border-white/10 pr-6">
                  <span className="text-[8px] opacity-50 font-black tracking-widest uppercase">Auto-Save</span>
                  <div className="flex items-center space-x-2">
                    {isAutoSaving ? <RefreshCw size={12} className="text-[#FDB913] animate-spin" /> : <Save size={12} className="text-green-400" />}
                    <span className="text-[10px] font-black">{isAutoSaving ? 'WRITING...' : 'IDLE'}</span>
                  </div>
                </div>
                <div className="flex flex-col items-end">
                   <span className="text-[8px] opacity-50 font-black tracking-widest uppercase">Last Sync</span>
                   <span className="text-[10px] font-black text-[#FDB913]">{lastSyncTime ? lastSyncTime.toLocaleTimeString() : '--:--'}</span>
                </div>
             </div>
           ) : !isReadOnly && (
             <button onClick={linkSharedFile} className="bg-black text-[#FDB913] hover:brightness-110 px-6 py-3 rounded font-black text-xs uppercase tracking-widest shadow-2xl flex items-center space-x-2 border-2 border-[#FDB913]/20 transition-all">
               <FileCode size={18} />
               <span>Connect Shared Drive (Z:\)</span>
             </button>
           )}
        </div>
      </header>

      <nav className="bg-white border-b border-gray-200 sticky top-0 z-40 shadow-sm overflow-x-auto">
        <div className="max-w-7xl mx-auto flex min-w-max">
          {tabs.map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex items-center space-x-3 px-8 py-5 transition-all border-b-4 ${
                activeTab === tab.id ? 'border-[#FDB913] text-black font-black bg-gray-50' : 'border-transparent text-gray-400 hover:text-black hover:bg-gray-50'
              }`}
            >
              {tab.icon}
              <span className="text-[11px] uppercase tracking-[0.15em] font-black">{tab.name}</span>
            </button>
          ))}
        </div>
      </nav>

      <main className="flex-1 p-6 max-w-[1600px] mx-auto w-full">
        {activeTab === 'dashboard' && <Dashboard state={data} />}
        {activeTab === 'calendar' && <CalendarView tasks={data.tasks} safetyStatus={data.safetyStatus} updateSafetyStatus={(newStatus) => updateData({ safetyStatus: newStatus })} />}
        {activeTab === 'tasks' && <TaskBoard readOnly={isReadOnly} tasks={data.tasks} users={data.users.map(u => u.name)} categories={data.categories} projects={data.projects} okrs={data.okrs} bookings={data.bookings} updateTasks={(tasks) => updateData({ tasks })} />}
        {activeTab === 'projects' && <ProjectBoard readOnly={isReadOnly} projects={data.projects} users={data.users.map(u => u.name)} updateProjects={(projects) => updateData({ projects })} />}
        {activeTab === 'bookings' && <HoursBooking readOnly={isReadOnly} bookings={data.bookings} tasks={data.tasks} projects={data.projects} users={data.users.map(u => u.name)} updateBookings={(bookings) => updateData({ bookings })} />}
