}

export interface Kudos {
  id: string;
  from: string;
  to: string;
  reason: string;
  date: string;
}

export interface KeyResult {
  id: string;
  kr: string;
}

export interface OKR {
  id: string;
  objective: string;
  keyResults: KeyResult[];
}

export interface User {
