  const [needsBackupAuth, setNeedsBackupAuth] = useState(false);

  const dataRef = useRef(data);
  useEffect(() => { dataRef.current = data; }, [data]);

  // Save to local cache
  useEffect(() => {
    if (!isReadOnly) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
    }
  }, [data, isReadOnly]);

  // Automated Daily Backup Logic
  const performAutoBackup = async () => {
    if (!backupDirHandle || isReadOnly) return;

    const today = new Date().toISOString().split('T')[0];
    if (data.lastBackupDate === today) {
      console.log("Daily backup already exists for today.");
      return;
    }

    try {
      // Browsers require permission on every page load for existing handles
      // @ts-ignore
      const permission = await backupDirHandle.queryPermission({ mode: 'readwrite' });
      if (permission !== 'granted') {
        setNeedsBackupAuth(true);
        return;
      }

      const fileName = `epiroc_backup_${today}.json`;
      const newFileHandle = await backupDirHandle.getFileHandle(fileName, { create: true });
      // @ts-ignore
      const writable = await newFileHandle.createWritable();
      await writable.write(JSON.stringify(data, null, 2));
      await writable.close();

      setData(prev => ({ ...prev, lastBackupDate: today }));
      setNeedsBackupAuth(false);
      console.log(`✓ Daily backup successful: ${fileName}`);
    } catch (err) {
      console.error("Auto backup failed:", err);
      setNeedsBackupAuth(true);
    }
  };

  // Trigger backup check on data change or load
  useEffect(() => {
    if (backupDirHandle) performAutoBackup();
  }, [backupDirHandle, data.lastBackupDate]);

  const mergeData = (local: AppState, remote: AppState): AppState => {
    const mergeById = (a: any[], b: any[]) => {
      const map = new Map();
      [...(a || []), ...(b || [])].forEach(item => {
        if (item && item.id) map.set(item.id, item);
      });
      return Array.from(map.values());
    };

    return {
      ...remote,
      version: APP_VERSION,
      tasks: mergeById(local.tasks, remote.tasks),
      projects: mergeById(local.projects, remote.projects),
      ideas: mergeById(local.ideas, remote.ideas),
      kudos: mergeById(local.kudos, remote.kudos),
      okrs: mergeById(local.okrs, remote.okrs),
      bookings: mergeById(local.bookings, remote.bookings),
      safetyStatus: { ...(local.safetyStatus || {}), ...(remote.safetyStatus || {}) }
    };
  };

  const linkSharedFile = async () => {
    try {
      // @ts-ignore
      const [handle] = await window.showOpenFilePicker({
        types: [{ description: 'Epiroc Database', accept: { 'application/json': ['.json'] } }],
        multiple: false
      });
      setFileHandle(handle);
      setIsReadOnly(false);
      const file = await handle.getFile();
      const content = await file.text();
      if (content) {
        const remoteData = JSON.parse(content);
        setData(prev => mergeData(prev, remoteData));
        setLastFileHash(content);
      }
      setLastSyncTime(new Date());
    } catch (err) { console.error(err); }
  };

  const linkBackupDir = async () => {
    try {
      // @ts-ignore
      const handle = await window.showDirectoryPicker();
      setBackupDirHandle(handle);
      setNeedsBackupAuth(false);
    } catch (e) { console.error(e); }
  };

  const reAuthBackup = async () => {
    if (!backupDirHandle) return;
    try {
      // @ts-ignore
      const permission = await backupDirHandle.requestPermission({ mode: 'readwrite' });
      if (permission === 'granted') {
        setNeedsBackupAuth(false);
        performAutoBackup();
      }
    } catch (e) { linkBackupDir(); }
  };

  const exportData = () => {
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `epiroc_pulse_export_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
  };

  const importData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const newData = JSON.parse(evt.target?.result as string);
        if (confirm("Replace all local data with this file?")) {
          setData(newData);
        }
      } catch (err) { alert("Invalid JSON file"); }
    };
    reader.readAsText(file);
  };

  useEffect(() => {
    if (!fileHandle || isReadOnly) return;
    const interval = setInterval(async () => {
      try {
        setIsAutoSaving(true);
        const file = await fileHandle.getFile();
        const content = await file.text();
        if (content !== lastFileHash) {
          const remoteData = JSON.parse(content);
          const merged = mergeData(dataRef.current, remoteData);
          setData(merged);
          setLastFileHash(JSON.stringify(merged));
          setLastSyncTime(new Date());
        } else {
          const localContent = JSON.stringify(dataRef.current, null, 2);
          if (localContent !== lastFileHash) {
            // @ts-ignore
            const writable = await fileHandle.createWritable();
            await writable.write(localContent);
            await writable.close();
            setLastFileHash(localContent);
            setLastSyncTime(new Date());
          }
        }
      } catch (err) { console.error(err); } finally { setIsAutoSaving(false); }
    }, 5000);
    return () => clearInterval(interval);
  }, [fileHandle, lastFileHash, isReadOnly]);

  const updateData = (newData: Partial<AppState>) => {
    if (isReadOnly) return;
    setData(prev => ({ ...prev, ...newData }));
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#F8F9FA]">
      {/* Session Re-Auth Alert for Auto Backup */}
      {needsBackupAuth && !isReadOnly && (
        <div className="bg-orange-600 text-white py-2 px-8 flex items-center justify-between text-[11px] font-black uppercase tracking-widest animate-pulse z-[100]">
          <div className="flex items-center space-x-3">
             <AlertTriangle size={14} />
             <span>Daily Backup Requires Authorization to Write to Folder</span>
          </div>
          <button onClick={reAuthBackup} className="bg-white text-orange-600 px-4 py-1 rounded-full flex items-center space-x-2 hover:bg-zinc-100 transition">
            <Play size={10} fill="currentColor" />
            <span>Enable Sync Now</span>
          </button>
        </div>
      )}

      <header className={`transition-all duration-500 h-24 flex items-center px-8 relative overflow-hidden ${isReadOnly ? 'bg-zinc-800 text-white' : fileHandle ? 'bg-black text-white' : 'bg-[#FDB913] text-black'}`}>
        <div className="absolute top-0 right-0 w-1/3 h-full bg-white/5 skew-x-[-20deg] translate-x-20 z-0"></div>
        <div className="flex items-center z-10 space-x-6">
          <div className={`w-14 h-14 flex items-center justify-center font-black text-3xl rounded-sm border-2 ${fileHandle ? 'bg-[#FDB913] text-black border-black/10' : 'bg-black text-[#FDB913] border-white/10'}`}>E</div>
          <div>
            <h1 className="text-2xl font-black tracking-tight uppercase">Operations Development Pulse</h1>
            <div className="flex items-center space-x-3 text-[10px] uppercase tracking-widest font-black opacity-80">
              <span className="flex items-center">
                {fileHandle ? <Wifi size={10} className="text-green-400 mr-1" /> : <WifiOff size={10} className="mr-1" />}
                {fileHandle ? 'TEAM SYNC ACTIVE' : 'LOCAL MODE'}
              </span>
              <span>•</span>
              <span className="flex items-center">
                <ShieldCheck size={10} className={`mr-1 ${backupDirHandle ? 'text-green-400' : 'text-gray-400'}`} />
                AUTO-BACKUP: {backupDirHandle ? 'ACTIVE' : 'OFF'}
              </span>
            </div>
          </div>
        </div>

        <div className="flex-1"></div>

        <div className="flex items-center space-x-4 z-10">
           {!isReadOnly && (
              <div className="flex space-x-2">
                <button onClick={exportData} title="Export JSON" className="p-2 bg-white/10 rounded hover:bg-white/20 transition flex items-center space-x-2 border border-white/5">
                  <Download size={18} />
                  <span className="text-[10px] font-black uppercase">Export</span>
                </button>
                <label className="p-2 bg-white/10 rounded hover:bg-white/20 transition flex items-center space-x-2 border border-white/5 cursor-pointer">
                  <Upload size={18} />
                  <span className="text-[10px] font-black uppercase">Import</span>
                  <input type="file" accept=".json" onChange={importData} className="hidden" />
                </label>
              </div>
           )}

           {fileHandle ? (
             <div className="flex items-center bg-white/10 px-6 py-3 rounded border border-white/5 space-x-6">
                <div className="flex flex-col items-end border-r border-white/10 pr-6">
                  <span className="text-[8px] opacity-50 font-black tracking-widest uppercase">Shared Ledger</span>
                  <div className="flex items-center space-x-2">
                    {isAutoSaving ? <RefreshCw size={12} className="text-[#FDB913] animate-spin" /> : <Save size={12} className="text-green-400" />}
                    <span className="text-[10px] font-black">{isAutoSaving ? 'SYNCING...' : 'UP-TO-DATE'}</span>
                  </div>
                </div>
                <div className="flex flex-col items-end">
                   <span className="text-[8px] opacity-50 font-black tracking-widest uppercase">Last Sync</span>
                   <span className="text-[10px] font-black text-[#FDB913]">{lastSyncTime ? lastSyncTime.toLocaleTimeString() : '--:--'}</span>
                </div>
             </div>
           ) : !isReadOnly && (
             <button onClick={linkSharedFile} className="bg-black text-[#FDB913] hover:brightness-110 px-6 py-3 rounded font-black text-xs uppercase tracking-widest shadow-2xl flex items-center space-x-2 border-2 border-[#FDB913]/20 transition-all">
               <FileCode size={18} />
               <span>Link Team Master (Z:\)</span>
             </button>
           )}
        </div>
      </header>

      <nav className="bg-white border-b border-gray-200 sticky top-0 z-40 shadow-sm overflow-x-auto">
        <div className="max-w-7xl mx-auto flex min-w-max">
          {tabs.map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex items-center space-x-3 px-8 py-5 transition-all border-b-4 ${
                activeTab === tab.id ? 'border-[#FDB913] text-black font-black bg-gray-50' : 'border-transparent text-gray-400 hover:text-black hover:bg-gray-50'
              }`}
            >
              {tab.icon}
              <span className="text-[11px] uppercase tracking-[0.15em] font-black">{tab.name}</span>
            </button>
          ))}
        </div>
      </nav>

      <main className="flex-1 p-6 max-w-[1600px] mx-auto w-full">
        {activeTab === 'dashboard' && <Dashboard state={data} />}
        {activeTab === 'calendar' && <CalendarView tasks={data.tasks} safetyStatus={data.safetyStatus} updateSafetyStatus={(newStatus) => updateData({ safetyStatus: newStatus })} />}
        {activeTab === 'tasks' && <TaskBoard readOnly={isReadOnly} tasks={data.tasks} users={data.users.map(u => u.name)} categories={data.categories} projects={data.projects} okrs={data.okrs} bookings={data.bookings} updateTasks={(tasks) => updateData({ tasks })} />}
        {activeTab === 'projects' && <ProjectBoard projects={data.projects} users={data.users.map(u => u.name)} updateProjects={(projects) => updateData({ projects })} />}
        {activeTab === 'bookings' && <HoursBooking readOnly={isReadOnly} bookings={data.bookings} tasks={data.tasks} projects={data.projects} users={data.users.map(u => u.name)} updateBookings={(bookings) => updateData({ bookings })} />}
        {activeTab === 'okrs' && <OKRBoard okrs={data.okrs} tasks={data.tasks} updateOkrs={(okrs) => updateData({ okrs })} />}
        {activeTab === 'ideas' && <IdeaMatrix ideas={data.ideas} users={data.users.map(u => u.name)} updateIdeas={(ideas) => updateData({ ideas })} />}
        {activeTab === 'kudos' && <KudosBoard kudos={data.kudos} users={data.users.map(u => u.name)} updateKudos={(kudos) => updateData({ kudos })} />}
        {activeTab === 'masters' && (
          <div className="space-y-6">
            <div className="bg-white p-6 rounded shadow-sm border border-gray-100 flex items-center justify-between">
               <div className="flex items-center space-x-4">
                  <div className={`p-3 rounded-lg ${backupDirHandle ? 'bg-green-50 text-green-600' : 'bg-gray-50 text-gray-400'}`}>
                    <Database size={24} />
                  </div>
                  <div>
                    <h3 className="font-black uppercase tracking-tight">Security & Backup</h3>
                    <p className="text-xs text-gray-500 uppercase font-bold">
                      {backupDirHandle ? `Syncing Daily to: ${backupDirHandle.name}` : 'Folder not selected for auto-backups'}
                    </p>
                  </div>
               </div>
               <button onClick={linkBackupDir} className="bg-black text-[#FDB913] px-6 py-3 rounded text-[10px] font-black uppercase tracking-widest shadow-lg">
                 {backupDirHandle ? 'Update Backup Folder' : 'Enable Daily Snapshot'}
               </button>
            </div>
            <Masters users={data.users} categories={data.categories} updateUsers={(users) => updateData({ users })} updateCategories={(categories) => updateData({ categories })} />
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useMemo, useState } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, 
  PieChart, Pie, Cell 
} from 'recharts';
import { AppState, Task, Project, SafetyStatusEntry } from '../types';
import { BRAND } from '../constants';
import { 
  Briefcase, CheckCircle2, Clock, AlertTriangle, 
  Users, Target, Calendar, ZoomIn, ZoomOut, Layers
} from 'lucide-react';
import { 
  format, parseISO, differenceInDays, startOfMonth, 
  endOfMonth, startOfYear, endOfYear, addMonths, eachMonthOfInterval,
  isSameMonth, startOfWeek, endOfWeek, eachDayOfInterval, eachWeekOfInterval, 
  addWeeks, subWeeks, isWithinInterval
} from 'date-fns';

const Dashboard: React.FC<{ state: AppState }> = ({ state }) => {
  const [timelineZoom, setTimelineZoom] = useState<'week' | 'month' | 'year'>('month');
  const [utilizationFilter, setUtilizationFilter] = useState<'week' | 'month' | 'year'>('month');

  // Safety Snapshot Logic
  const safetyStats = useMemo(() => {
    const today = new Date();
    const currentMonthData = Object.entries(state.safetyStatus || {})
      .filter(([date]) => isSameMonth(parseISO(date), today));

    const statusCounts = { green: 0, yellow: 0, red: 0 };
    currentMonthData.forEach(([_, val]) => {
      const entry = val as SafetyStatusEntry;
      if (entry && entry.status) statusCounts[entry.status]++;
    });

    return [
      { name: 'Safe Ops', value: statusCounts.green || 0 },
      { name: 'Risks Identified', value: statusCounts.yellow || 0 },
      { name: 'Incidents', value: statusCounts.red || 0 }
    ].filter(s => s.value > 0 || s.name === 'Safe Ops');
  }, [state.safetyStatus]);

  // Team Resource Utilization Filtered
  const workloadData = useMemo(() => {
    const now = new Date();
    let intervals: Date[] = [];

    if (utilizationFilter === 'week') {
      intervals = eachWeekOfInterval({ start: subWeeks(now, 2), end: addWeeks(now, 5) });
    } else if (utilizationFilter === 'month') {
      intervals = eachMonthOfInterval({ start: startOfYear(now), end: addMonths(startOfYear(now), 11) });
    } else {
      intervals = [startOfYear(now), startOfYear(addMonths(now, 12))];
    }

    return intervals.map(start => {
      const label = utilizationFilter === 'week' ? `W${format(start, 'w')}` : format(start, 'MMM yy');
      let assigned = 0;
      let totalCapacity = state.users.reduce((acc, u) => acc + (u.capacity || 160), 0);

      // Distribute Project hours across its duration
      state.projects.forEach(p => {
        if (p.status !== 'Completed' && p.status !== 'Cancelled') {
          const pStart = parseISO(p.startDate);
          const pEnd = parseISO(p.endDate);
          const intervalEnd = utilizationFilter === 'week' ? addWeeks(start, 1) : addMonths(start, 1);

          if (isWithinInterval(start, { start: pStart, end: pEnd }) || isWithinInterval(pStart, { start, end: intervalEnd })) {
             const durationDays = differenceInDays(pEnd, pStart) || 1;
             const hoursPerDay = (p.hours || 0) / durationDays;
             assigned += hoursPerDay * (utilizationFilter === 'week' ? 7 : 30);
          }
        }
      });

      // Task hours on due date
      state.tasks.forEach(t => {
        if (t.status !== 'Completed') {
          const tDate = parseISO(t.dueDate);
          if (utilizationFilter === 'month' && isSameMonth(tDate, start)) assigned += (t.hours || 0);
          else if (utilizationFilter === 'week' && tDate >= start && tDate < addWeeks(start, 1)) assigned += (t.hours || 0);
          else if (utilizationFilter === 'year' && tDate.getFullYear() === start.getFullYear()) assigned += (t.hours || 0);
        }
      });

      return { 
        name: label, 
        assigned: Math.round(assigned), 
        capacity: utilizationFilter === 'week' ? Math.round(totalCapacity / 4) : totalCapacity 
      };
    });
  }, [state.tasks, state.projects, state.users, utilizationFilter]);

  // Waterfall Zooming Logic
  const timelineRange = useMemo(() => {
    const now = new Date();
    if (timelineZoom === 'week') return { start: startOfWeek(now), end: endOfWeek(now), total: 7 };
    if (timelineZoom === 'month') return { start: startOfMonth(now), end: endOfMonth(now), total: differenceInDays(endOfMonth(now), startOfMonth(now)) + 1 };
    return { start: startOfYear(now), end: endOfYear(now), total: 365 };
  }, [timelineZoom]);

  // Waterfall Items Calculation
  const waterfallItems = useMemo(() => {
    return [
      ...state.tasks.filter(t => t.status !== 'Completed').map(t => ({...t, type: 'Task', name: t.task, end: t.dueDate})),
      ...state.projects.filter(p => p.status !== 'Completed').map(p => ({...p, type: 'Project', name: p.name, end: p.endDate}))
    ].map(item => {
      const start = parseISO(item.startDate);
      const end = parseISO(item.end);
      const offset = differenceInDays(start, timelineRange.start);
      const duration = differenceInDays(end, start) + 1;

      const startPct = (offset / timelineRange.total) * 100;
      const widthPct = (duration / timelineRange.total) * 100;

      return { 
        ...item, 
        startPct: Math.max(0, Math.min(100, startPct)), 
        widthPct: Math.max(1, Math.min(100 - startPct, widthPct)) 
      };
    }).filter(i => i.startPct < 100 && (i.startPct + i.widthPct) > 0);
  }, [state.tasks, state.projects, timelineRange]);

  // Ruler Ticks
  const rulerTicks = useMemo(() => {
    const days = eachDayOfInterval({ start: timelineRange.start, end: timelineRange.end });
    if (timelineZoom === 'year') {
      return eachMonthOfInterval({ start: timelineRange.start, end: timelineRange.end }).map(m => ({
        label: format(m, 'MMM'),
        pos: (differenceInDays(m, timelineRange.start) / timelineRange.total) * 100
      }));
    }
    return days.filter((_, i) => timelineZoom === 'week' || i % 5 === 0).map(d => ({
      label: format(d, timelineZoom === 'week' ? 'EEE' : 'd MMM'),
      pos: (differenceInDays(d, timelineRange.start) / timelineRange.total) * 100
    }));
  }, [timelineZoom, timelineRange]);

  return (
    <div className="space-y-6">
      {/* Top Level Summary Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        {[
          { label: 'Pending Operations', value: state.tasks.filter(t => t.status !== 'Completed').length, icon: <Briefcase size={20} />, color: 'bg-black' },
          { label: 'Strategic Objectives', value: state.okrs.length, icon: <Target size={20} />, color: 'bg-[#FDB913] text-black' },
          { label: 'Resource Load', value: utilizationFilter.toUpperCase(), icon: <Clock size={20} />, color: 'bg-green-600' },
          { label: 'Health Status', value: 'NOMINAL', icon: <CheckCircle2 size={20} />, color: 'bg-zinc-800' },
        ].map((card, i) => (
          <div key={i} className={`${card.color} ${card.color.includes('text-black') ? '' : 'text-white'} p-6 rounded shadow-sm flex justify-between items-center transition hover:scale-[1.02]`}>
            <div>
              <p className="text-[10px] font-black uppercase opacity-60 mb-1">{card.label}</p>
              <p className="text-2xl font-black">{card.value}</p>
            </div>
            <div className="opacity-30">{card.icon}</div>
          </div>
        ))}
      </div>

      {/* Waterfall Operational Roadmap */}
      <div className="bg-white p-6 rounded shadow-sm border border-gray-100">
        <div className="flex justify-between items-center mb-8">
           <div className="flex items-center space-x-3">
              <Layers className="text-[#FDB913]" size={22} />
              <div>
                <h3 className="text-lg font-black uppercase tracking-tight">Operation Waterfall</h3>
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Active Roadmap & Timeline</p>
              </div>
           </div>
           <div className="flex bg-gray-100 p-1 rounded-md">
              {(['week', 'month', 'year'] as const).map(z => (
                <button key={z} onClick={() => setTimelineZoom(z)} className={`px-5 py-2 text-[9px] font-black uppercase rounded transition ${timelineZoom === z ? 'bg-black text-[#FDB913] shadow-sm' : 'text-gray-400 hover:text-black'}`}>{z}</button>
              ))}
           </div>
        </div>

        <div className="relative border-l border-gray-100 ml-4 pb-8 overflow-x-auto">
          {/* Timeline Ruler */}
          <div className="h-10 w-full border-b border-gray-200 relative mb-8 min-w-[800px]">
             {rulerTicks.map((tick, i) => (
               <div key={i} className="absolute border-l border-gray-200 h-3 top-7" style={{ left: `${tick.pos}%` }}>
                 <span className="absolute -top-7 -left-4 text-[9px] font-black text-gray-400 uppercase whitespace-nowrap">{tick.label}</span>
               </div>
             ))}
          </div>

          <div className="space-y-6 min-w-[800px]">
             {waterfallItems.length === 0 ? (
               <div className="text-center py-12 text-gray-300 font-black uppercase tracking-widest text-xs">No active operations in this view range</div>
             ) : waterfallItems.map((item) => (
               <div key={item.id} className="relative group">
                 <div className="flex items-center mb-1.5 ml-4">
                    <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded-full mr-2 ${item.type === 'Project' ? 'bg-purple-100 text-purple-700' : 'bg-blue-100 text-blue-700'}`}>
                      {item.type}
                    </span>
                    <span className="text-[11px] font-black text-gray-700 tracking-tight group-hover:text-black transition">{item.name}</span>
                 </div>
                 <div className="h-6 w-full bg-gray-50 rounded-r-full relative overflow-hidden">
                    {/* Vertical grid lines helper */}
                    {rulerTicks.map((t, i) => <div key={i} className="absolute h-full border-l border-gray-100 z-0" style={{ left: `${t.pos}%` }}></div>)}

                    <div className="absolute top-0 h-full bg-[#FDB913] rounded shadow-sm transition-all duration-700 z-10 hover:brightness-110" style={{ left: `${item.startPct}%`, width: `${item.widthPct}%` }}>
                      <div className="h-full bg-black/20" style={{ width: `${item.progress}%` }}></div>
                      <span className="absolute inset-0 flex items-center justify-center text-[9px] font-black text-white mix-blend-difference">{item.progress}%</span>
                    </div>
                 </div>
               </div>
             ))}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Resource Utilization Chart */}
        <div className="bg-white p-6 rounded shadow-sm border border-gray-100">
          <div className="flex items-center justify-between mb-8">
            <div className="flex items-center space-x-2">
              <Users className="text-[#FDB913]" size={20} />
              <h3 className="text-lg font-black uppercase tracking-tight">Team Utilization</h3>
            </div>
            <div className="flex bg-gray-50 p-1 rounded-md">
               {(['week', 'month', 'year'] as const).map(f => (
