import React, { useState, useEffect } from 'react';
import { ResponsiveContainer, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend } from 'recharts';
import { DateRange } from 'react-date-range';
import 'react-date-range/dist/styles.css';
import 'react-date-range/dist/theme/default.css';
import { subWeeks, isSameMonth, addDays, getWeek, getDay } from 'date-fns';

interface WorkloadData {
  name: string;
  assigned: number;
  capacity: number;
}

const Dashboard = () => {
  const [workloadData, setWorkloadData] = useState<WorkloadData[]>([]);
  const [utilizationFilter, setUtilizationFilter] = useState<string>('All');
  const [stakeholderFilter, setStakeholderFilter] = useState<string>('All');
  const [dateRange, setDateRange] = useState([{
    startDate: subWeeks(new Date(), 2),
    endDate: new Date(),
    key: 'selection',
  }]);

  useEffect(() => {
    // Generate sample data - replace with your data fetching logic
    const generateWorkloadData = (startDate: Date, endDate: Date): WorkloadData[] => {
      const data: WorkloadData[] = [];
      let currentDate = new Date(startDate);

      while (currentDate <= endDate) {
        const week = getWeek(currentDate);
        const day = getDay(currentDate);
        const name = `Week ${week} - Day ${day}`; // Format date
        const assigned = Math.floor(Math.random() * 50) + 20; // Simulated assigned load
        const capacity = Math.floor(Math.random() * 80) + 50; // Simulated capacity
        data.push({ name, assigned, capacity });
        currentDate = addDays(currentDate, 1);
      }

      return data;
    };

