import React, { useState } from 'react';
import { 
  format, addMonths, endOfMonth, 
  endOfWeek, eachDayOfInterval, isSameMonth, 
  isSameDay, addDays 
} from 'date-fns';
import { Task, SafetyStatus } from '../types';
import { ChevronLeft, ChevronRight, AlertCircle, CheckCircle2, Info } from 'lucide-react';
import { BRAND } from '../constants';

interface CalendarViewProps {
  tasks: Task[];
  safetyStatus: SafetyStatus;
  updateSafetyStatus: (status: SafetyStatus) => void;
}

const CalendarView: React.FC<CalendarViewProps> = ({ tasks, safetyStatus, updateSafetyStatus }) => {
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState(new Date());

  const onDateClick = (day: Date) => {
    setSelectedDate(day);
  };

  const nextMonth = () => setCurrentMonth(addMonths(currentMonth, 1));
  const prevMonth = () => setCurrentMonth(addMonths(currentMonth, -1));

  const jumpToToday = () => {
    const now = new Date();
    setCurrentMonth(now);
    setSelectedDate(now);
  };

  const renderHeader = () => (
    <div className="flex justify-between items-center bg-white p-4 rounded-t-lg border-b border-gray-100">
      <h2 className="text-xl font-bold flex items-center space-x-2">
        <span>{format(currentMonth, 'MMMM yyyy')}</span>
      </h2>
      <div className="flex items-center space-x-2">
        <button onClick={prevMonth} className="p-2 hover:bg-gray-100 rounded-full transition"><ChevronLeft size={20} /></button>
        <button onClick={jumpToToday} className="px-4 py-1 text-xs font-bold uppercase border border-gray-200 rounded hover:bg-gray-50">Today</button>
        <button onClick={nextMonth} className="p-2 hover:bg-gray-100 rounded-full transition"><ChevronRight size={20} /></button>
      </div>
    </div>
  );

  const renderDays = () => {
    const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    return (
      <div className="grid grid-cols-7 bg-gray-50 border-b border-gray-200">
        {days.map(d => (
          <div key={d} className="py-2 text-center text-[10px] font-bold uppercase text-gray-400 tracking-widest">{d}</div>
        ))}
      </div>
    );
  };

  const renderCells = () => {
    const monthStart = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), 1);
    const monthEnd = endOfMonth(monthStart);
    const startDate = new Date(monthStart);
    startDate.setDate(startDate.getDate() - startDate.getDay());
    const endDate = endOfWeek(monthEnd);
    const calendarDays = eachDayOfInterval({ start: startDate, end: endDate });

    const rows = [];
    let days = [];

    calendarDays.forEach((day, i) => {
      const dateStr = format(day, 'yyyy-MM-dd');
      const status = safetyStatus[dateStr]?.status || null;
      const dayTasks = tasks.filter(t => t.dueDate === dateStr);

      const isSelected = isSameDay(day, selectedDate);
      const isCurrentMonth = isSameMonth(day, monthStart);

      days.push(
        <div
          key={dateStr}
          className={`min-h-[100px] border-r border-b border-gray-100 p-2 cursor-pointer transition-colors relative
            ${!isCurrentMonth ? 'bg-gray-50 text-gray-300' : 'bg-white'}
            ${isSelected ? 'bg-yellow-50/50 ring-1 ring-inset ring-[#FDB913]' : ''}
            hover:bg-gray-50
          `}
          onClick={() => onDateClick(day)}
        >
          <div className="flex justify-between items-start">
            <span className={`text-sm font-bold ${isSelected ? 'text-[#FDB913]' : ''}`}>
              {format(day, 'd')}
            </span>
            {status && (
              <div className={`w-2 h-2 rounded-full ${status === 'green' ? 'bg-green-500' : status === 'yellow' ? 'bg-orange-500' : 'bg-red-500'}`}></div>
            )}
          </div>
          <div className="mt-2 space-y-1">
            {dayTasks.slice(0, 3).map(t => (
              <div key={t.id} className="text-[9px] px-1 bg-gray-100 rounded text-gray-600 truncate font-medium">
                {t.task}
              </div>
            ))}
            {dayTasks.length > 3 && (
              <div className="text-[8px] text-gray-400 pl-1 font-bold">+{dayTasks.length - 3} more</div>
            )}
          </div>
        </div>
      );

      if ((i + 1) % 7 === 0) {
        rows.push(<div key={i} className="grid grid-cols-7">{days}</div>);
        days = [];
      }
    });

    return <div className="bg-white border-l border-t border-gray-100">{rows}</div>;
  };

  const setDayStatus = (status: 'green' | 'yellow' | 'red') => {
    const dateStr = format(selectedDate, 'yyyy-MM-dd');
    const newSafety = { ...safetyStatus };
    newSafety[dateStr] = { ...newSafety[dateStr], status };
    updateSafetyStatus(newSafety);
  };

  const setDayNotes = (notes: string) => {
    const dateStr = format(selectedDate, 'yyyy-MM-dd');
    const newSafety = { ...safetyStatus };
    newSafety[dateStr] = { ...newSafety[dateStr], notes };
    updateSafetyStatus(newSafety);
  };

  const selectedDateStr = format(selectedDate, 'yyyy-MM-dd');
  const selectedTasks = tasks.filter(t => t.dueDate === selectedDateStr);
  const currentSafety = safetyStatus[selectedDateStr];

  return (
    <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
      <div className="lg:col-span-3 bg-white rounded-lg shadow-sm border border-gray-100 overflow-hidden">
        {renderHeader()}
        {renderDays()}
        {renderCells()}
      </div>

      <div className="space-y-6">
        <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-100">
          <h3 className="text-sm font-bold uppercase tracking-widest text-gray-400 mb-4">Date Details</h3>
          <p className="text-xl font-bold mb-6">{format(selectedDate, 'EEEE, MMM do')}</p>

          <div className="space-y-4">
            <div>
              <label className="block text-[10px] font-bold text-gray-500 uppercase mb-2">Safety & Health Status</label>
              <div className="flex space-x-2">
                {[
                  { val: 'green', color: 'bg-green-500', label: 'Good' },
                  { val: 'yellow', color: 'bg-orange-500', label: 'Mod.' },
                  { val: 'red', color: 'bg-red-500', label: 'Poor' }
                ].map(s => (
                  <button
                    key={s.val}
                    onClick={() => setDayStatus(s.val as any)}
                    className={`flex-1 py-2 px-1 rounded flex flex-col items-center justify-center transition-all border-2 
                      ${currentSafety?.status === s.val ? 'border-black' : 'border-transparent opacity-40 hover:opacity-100'}
                    `}
                  >
                    <div className={`w-3 h-3 rounded-full ${s.color} mb-1`}></div>
                    <span className="text-[10px] font-bold">{s.label}</span>
                  </button>
                ))}
              </div>
            </div>

            <div>
              <label className="block text-[10px] font-bold text-gray-500 uppercase mb-2">Daily Notes</label>
              <textarea
                className="w-full border border-gray-200 rounded p-2 text-sm focus:outline-none focus:ring-2 focus:ring-[#FDB913]"
                rows={4}
                placeholder="Shift notes, safety reports..."
                value={currentSafety?.notes || ''}
                onChange={(e) => setDayNotes(e.target.value)}
              ></textarea>
            </div>
          </div>
        </div>

        <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-100">
          <h3 className="text-sm font-bold uppercase tracking-widest text-gray-400 mb-4">Tasks Due ({selectedTasks.length})</h3>
          <div className="space-y-3 max-h-[300px] overflow-y-auto pr-2">
            {selectedTasks.length === 0 ? (
              <p className="text-sm text-gray-400 italic">No tasks due this day</p>
            ) : (
              selectedTasks.map(t => (
                <div key={t.id} className="p-3 bg-gray-50 rounded border-l-4 border-[#FDB913]">
                  <p className="text-sm font-bold text-gray-800 line-clamp-2">{t.task}</p>
                  <div className="flex justify-between items-center mt-1">
                    <span className="text-[10px] font-bold uppercase text-gray-500">{t.owner}</span>
                    <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded ${t.status === 'Completed' ? 'bg-green-100 text-green-700' : 'bg-gray-200'}`}>
                      {t.status}
                    </span>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default CalendarView;

import React, { useState } from 'react';
import { Idea, Task } from '../types';
import { Lightbulb, Plus, Trash2, TrendingUp, DollarSign } from 'lucide-react';

interface IdeaMatrixProps {
  ideas: Idea[];
  tasks: Task[];
  users: string[];
  updateIdeas: (ideas: Idea[]) => void;
  updateTasks: (tasks: Task[]) => void;
}

const IdeaMatrix: React.FC<IdeaMatrixProps> = ({ ideas, tasks, users, updateIdeas, updateTasks }) => {
  const [showModal, setShowModal] = useState(false);

  const quadrants = [
    { impact: 'High', cost: 'Low', label: 'Quick Wins 🚀', color: 'bg-green-50' },
    { impact: 'High', cost: 'Medium', label: 'Growth Ops 📈', color: 'bg-blue-50' },
    { impact: 'High', cost: 'High', label: 'Major Projects ⛰️', color: 'bg-purple-50' },
    { impact: 'Medium', cost: 'Low', label: 'Steady Wins ✨', color: 'bg-green-50/50' },
    { impact: 'Medium', cost: 'Medium', label: 'Tactical Needs 🛠️', color: 'bg-gray-50' },
    { impact: 'Medium', cost: 'High', label: 'Review Carefully 🧐', color: 'bg-orange-50' },
    { impact: 'Low', cost: 'Low', label: 'Fill-ins 🧹', color: 'bg-gray-100' },
    { impact: 'Low', cost: 'Medium', label: 'Low Priority 📉', color: 'bg-orange-50/50' },
    { impact: 'Low', cost: 'High', label: 'Reconsider ❌', color: 'bg-red-50' },
  ];

  const handleSaveIdea = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const ideaText = formData.get('idea') as string;
    const proposer = formData.get('proposer') as string;

    const newIdea: Idea = {
      id: Math.random().toString(36).substr(2, 9),
      idea: ideaText,
      proposer: proposer,
      impact: formData.get('impact') as any,
      cost: formData.get('cost') as any,
      status: 'New',
      date: new Date().toISOString().split('T')[0]
    };

    // Auto-generate a Task from the Idea
    const newTask: Task = {
      id: Math.random().toString(36).substr(2, 9),
      category: 'Information & Team Suggestions',
      task: `Improvement: ${ideaText}`,
      owner: proposer,
      project: '',
      status: 'Not Started',
      priority: 'Medium',
      progress: 0,
      hours: 0,
      startDate: new Date().toISOString().split('T')[0],
      dueDate: new Date().toISOString().split('T')[0],
      notes: `Auto-generated from Idea Matrix. Impact: ${newIdea.impact}, Cost: ${newIdea.cost}`,
      ideaLink: newIdea.id,
      history: [{ timestamp: new Date().toISOString(), change: 'Operation initialized from Idea Matrix' }],
      comments: []
    };

    updateIdeas([...ideas, newIdea]);
    updateTasks([...tasks, newTask]);
    setShowModal(false);
  };

  const deleteIdea = (id: string) => {
    if (confirm('Delete this idea?')) {
      updateIdeas(ideas.filter(i => i.id !== id));
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center bg-white p-6 rounded-lg shadow-sm border border-gray-100">
        <div className="flex items-center space-x-4">
          <div className="bg-[#FDB913] p-3 rounded-lg text-black">
            <Lightbulb size={24} />
          </div>
          <div>
            <h2 className="text-xl font-black uppercase tracking-tight">Idea & Improvement Matrix</h2>
            <p className="text-sm text-gray-500 font-medium">Strategic categorization of team innovations</p>
          </div>
        </div>
        <button
          onClick={() => setShowModal(true)}
          className="bg-black text-[#FDB913] px-6 py-2 rounded font-black text-xs uppercase tracking-widest shadow-lg hover:brightness-110"
        >
          Submit New Idea
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {quadrants.map((q, idx) => {
          const matchingIdeas = ideas.filter(i => i.impact === q.impact && i.cost === q.cost);
          return (
            <div key={idx} className={`${q.color} border border-gray-200 rounded-lg p-4 min-h-[200px] flex flex-col`}>
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-xs font-black uppercase tracking-widest text-gray-900">{q.label}</h3>
                <span className="text-[10px] font-black bg-white/50 px-2 rounded">{matchingIdeas.length}</span>
              </div>
              <div className="flex-1 space-y-2">
                {matchingIdeas.map(idea => (
                  <div key={idea.id} className="bg-white p-3 rounded shadow-sm border border-gray-100 group">
                    <div className="flex justify-between items-start mb-1">
                      <p className="text-xs font-bold text-gray-800 leading-tight">{idea.idea}</p>
                      <button onClick={() => deleteIdea(idea.id)} className="opacity-0 group-hover:opacity-100 text-red-500"><Trash2 size={12} /></button>
                    </div>
                    <p className="text-[9px] text-gray-400 font-black uppercase tracking-tighter">— {idea.proposer}</p>
                  </div>
                ))}
              </div>
            </div>
          );
        })}
      </div>

      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="bg-white rounded shadow-2xl w-full max-w-lg overflow-hidden">
            <div className="p-6 bg-[#FDB913] text-black flex justify-between items-center">
              <h2 className="text-xl font-black uppercase tracking-tight">Propose Improvement</h2>
              <button onClick={() => setShowModal(false)} className="font-black text-2xl">×</button>
            </div>
            <form onSubmit={handleSaveIdea} className="p-6 space-y-4">
              <div>
                <label className="block text-[10px] font-black uppercase tracking-widest text-gray-500 mb-1">Your Idea *</label>
                <textarea name="idea" required className="w-full border p-3 rounded outline-none focus:ring-1 focus:ring-black" rows={3}></textarea>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-[10px] font-black uppercase tracking-widest text-gray-500 mb-1">Proposed By</label>
                  <select name="proposer" className="w-full border p-2 rounded">
                    {users.map(u => <option key={u} value={u}>{u}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-[10px] font-black uppercase tracking-widest text-gray-500 mb-1">Strategic Impact</label>
                  <select name="impact" className="w-full border p-2 rounded">
                    <option value="High">High</option>
                    <option value="Medium">Medium</option>
                    <option value="Low">Low</option>
                  </select>
                </div>
                <div>
                  <label className="block text-[10px] font-black uppercase tracking-widest text-gray-500 mb-1">Cost / Effort</label>
                  <select name="cost" className="w-full border p-2 rounded">
                    <option value="Low">Low</option>
                    <option value="Medium">Medium</option>
                    <option value="High">High</option>
                  </select>
                </div>
              </div>
              <div className="pt-4 flex justify-end">
                <button type="submit" className="bg-black text-[#FDB913] px-8 py-3 rounded font-black uppercase tracking-widest shadow-xl">Submit to Matrix</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default IdeaMatrix;

import React, { useState, useMemo } from 'react';
import { Task, Status, Priority, OKR, Booking, Idea } from '../types';
import { Plus, Trash2, Search, Target, Clock, AlertTriangle, ListChecks, History, Link } from 'lucide-react';
import { format } from 'date-fns';

interface TaskBoardProps {
  tasks: Task[];
  users: string[];
  categories: string[];
  projects: any[];
  okrs: OKR[];
  ideas?: Idea[];
  bookings: Booking[];
  readOnly?: boolean;
  updateTasks: (tasks: Task[]) => void;
}

const TaskBoard: React.FC<TaskBoardProps> = ({ tasks, users, categories, projects, okrs, ideas = [], bookings, readOnly, updateTasks }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterOwner, setFilterOwner] = useState('All');
  const [editingTask, setEditingTask] = useState<Task | null>(null);
  const [showModal, setShowModal] = useState(false);
  const [activeSubTab, setActiveSubTab] = useState<'details' | 'history'>('details');
  const [tempProgress, setTempProgress] = useState(0);

  const filteredTasks = useMemo(() => {
    return tasks.filter(t => {
      const matchSearch = t.task.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          t.owner.toLowerCase().includes(searchTerm.toLowerCase());
      const matchOwner = filterOwner === 'All' || t.owner === filterOwner;
      return matchSearch && matchOwner;
    });
  }, [tasks, searchTerm, filterOwner]);

  const handleSaveTask = (e: React.FormEvent<HTMLFormElement>) => {
    if (readOnly) return;
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const taskData: Partial<Task> = {
      task: formData.get('task') as string,
      owner: formData.get('owner') as string,
      category: formData.get('category') as string,
      project: formData.get('project') as string,
      status: formData.get('status') as Status,
      priority: formData.get('priority') as Priority,
      progress: tempProgress,
      hours: parseFloat(formData.get('hours') as string) || 0,
      startDate: formData.get('startDate') as string,
      dueDate: formData.get('dueDate') as string,
      okrLink: formData.get('okrLink') as string,
      ideaLink: formData.get('ideaLink') as string,
      notes: formData.get('notes') as string,
    };

    if (editingTask) {
      const history = [...(editingTask.history || [])];
      if (editingTask.status !== taskData.status) {
        history.push({ timestamp: new Date().toISOString(), change: `Status transitioned to ${taskData.status}` });
      }
      updateTasks(tasks.map(t => t.id === editingTask.id ? { ...t, ...taskData, history } : t));
    } else {
      const newTask: Task = {
        id: Math.random().toString(36).substr(2, 9),
        history: [{ timestamp: new Date().toISOString(), change: 'Operation initialized' }],
        comments: [],
        ...taskData as any
      };
      updateTasks([...tasks, newTask]);
    }
    setShowModal(false);
    setEditingTask(null);
  };

  const handleDeleteTask = (taskId: string) => {
    if (readOnly) return;
    if (confirm('Are you sure you want to permanently delete this operation? This cannot be undone.')) {
        updateTasks(tasks.filter(t => t.id !== taskId));
        setShowModal(false);
        setEditingTask(null);
    }
  };

  const getActualHours = (taskId: string) => {
    return bookings.filter(b => b.targetId === taskId).reduce((acc, b) => acc + b.hours, 0);
  };

  const getStatusColor = (status: Status) => {
    switch (status) {
      case 'Completed': return 'bg-green-100 text-green-800';
      case 'In Progress': return 'bg-blue-100 text-blue-800';
      case 'Blocked': return 'bg-red-100 text-red-800';
      case 'On Hold': return 'bg-gray-100 text-gray-800';
      default: return 'bg-yellow-100 text-yellow-800';
    }
  };

  const openEdit = (task: Task | null) => {
    setEditingTask(task);
    setTempProgress(task ? task.progress : 0);
    setActiveSubTab('details');
    setShowModal(true);
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap justify-between items-center gap-4 bg-white p-5 rounded shadow-sm border border-gray-100">
        <div className="flex items-center space-x-4 flex-1 max-w-2xl">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-400" size={18} />
            <input type="text" placeholder="Search operations..." className="w-full pl-10 pr-4 py-3 border border-zinc-100 bg-zinc-50 rounded font-bold text-sm outline-none focus:bg-white focus:ring-1 focus:ring-black transition" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
          </div>
          <select className="border border-zinc-100 bg-zinc-50 rounded px-4 py-3 text-xs font-black uppercase tracking-widest outline-none" value={filterOwner} onChange={(e) => setFilterOwner(e.target.value)}>
            <option value="All">All Stakeholders</option>
            {users.map(u => <option key={u} value={u}>{u}</option>)}
          </select>
        </div>
        {!readOnly && (
          <button onClick={() => openEdit(null)} className="bg-black text-[#FDB913] px-8 py-3 rounded font-black text-xs uppercase tracking-widest shadow-xl transition hover:brightness-110">Initiate New Operation</button>
        )}
      </div>

      <div className="bg-white rounded shadow-sm border border-gray-100 overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-zinc-50 border-b border-gray-100">
            <tr>
              <th className="px-6 py-5 text-[10px] font-black uppercase text-gray-400 tracking-widest">Operation Detail</th>
              <th className="px-6 py-5 text-[10px] font-black uppercase text-gray-400 tracking-widest">Stakeholder</th>
              <th className="px-6 py-5 text-[10px] font-black uppercase text-gray-400 tracking-widest">Duration (Est)</th>
              <th className="px-6 py-5 text-[10px] font-black uppercase text-gray-400 tracking-widest">Burn Efficiency</th>
              <th className="px-6 py-5 text-[10px] font-black uppercase text-gray-400 tracking-widest text-right">Progress</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-50">
            {filteredTasks.length === 0 ? (
              <tr><td colSpan={5} className="px-6 py-12 text-center text-gray-300 font-black uppercase text-xs tracking-widest">No matching operations found</td></tr>
            ) : filteredTasks.map(t => {
              const actual = getActualHours(t.id);
              const est = t.hours || 0;
              const burnPct = est > 0 ? Math.min(100, (actual / est) * 100) : 0;

              return (
                <tr key={t.id} className="hover:bg-zinc-50 transition group cursor-pointer" onClick={() => openEdit(t)}>
                  <td className="px-6 py-5">
                    <p className="font-black text-zinc-900 text-sm leading-tight mb-1">{t.task}</p>
                    <div className="flex items-center space-x-2">
                      <span className="text-[8px] font-black uppercase bg-zinc-100 text-zinc-500 px-2 py-0.5 rounded tracking-tighter">{t.category}</span>
                      <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase ${getStatusColor(t.status)}`}>{t.status}</span>
                    </div>
                  </td>
                  <td className="px-6 py-5 text-xs font-black text-zinc-700 uppercase">{t.owner}</td>
                  <td className="px-6 py-5 text-xs font-black text-zinc-900">{est} Hrs</td>
                  <td className="px-6 py-5">
                    <div className="flex items-center space-x-3">
                       <div className="w-24 bg-zinc-100 h-1.5 rounded-full overflow-hidden">
                          <div className={`h-full ${actual > est && est > 0 ? 'bg-red-500' : 'bg-[#FDB913]'}`} style={{ width: `${burnPct}%` }}></div>
                       </div>
                       <span className="text-[10px] font-black uppercase text-gray-400">{actual}h Actual</span>
                    </div>
                  </td>
                  <td className="px-6 py-5 text-right">
                    <div className="flex flex-col items-end">
                      <span className="text-xs font-black text-zinc-900">{t.progress}%</span>
                      <div className="w-24 bg-zinc-100 h-1.5 rounded-full mt-1.5">
                        <div className="bg-black h-1.5 rounded-full transition-all duration-1000" style={{ width: `${t.progress}%` }}></div>
                      </div>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="bg-white rounded shadow-2xl w-full max-w-3xl max-h-[90vh] overflow-hidden flex flex-col">
            <div className="p-8 bg-[#FDB913] text-black flex justify-between items-center shrink-0">
              <div>
                <h2 className="text-2xl font-black uppercase tracking-tight">{editingTask ? 'Edit Operation' : 'Initiate Operation'}</h2>
                <p className="text-[10px] font-black uppercase opacity-60">Epiroc Management Console</p>
              </div>
              <button onClick={() => setShowModal(false)} className="font-black text-3xl hover:rotate-90 transition-all duration-300">×</button>
            </div>

            <div className="flex bg-zinc-50 border-b shrink-0 px-8">
              <button onClick={() => setActiveSubTab('details')} className={`px-8 py-4 text-[11px] font-black uppercase tracking-widest flex items-center space-x-2 ${activeSubTab === 'details' ? 'border-b-4 border-black text-black bg-white' : 'text-gray-400 hover:text-black'}`}>
                <ListChecks size={14} />
                <span>Operational Parameters</span>
              </button>
              {editingTask && (
                <button onClick={() => setActiveSubTab('history')} className={`px-8 py-4 text-[11px] font-black uppercase tracking-widest flex items-center space-x-2 ${activeSubTab === 'history' ? 'border-b-4 border-black text-black bg-white' : 'text-gray-400 hover:text-black'}`}>
                  <History size={14} />
                  <span>Audit Trail</span>
                </button>
              )}
            </div>

            <div className="flex-1 overflow-y-auto p-8 bg-white">
              {activeSubTab === 'details' ? (
                <form id="taskForm" onSubmit={handleSaveTask} className="space-y-8">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div className="col-span-2">
                      <label className="block text-[10px] font-black uppercase text-gray-400 mb-2 tracking-widest">Operational Description *</label>
                      <input name="task" required defaultValue={editingTask?.task} className="w-full border-b-2 border-zinc-100 p-3 bg-zinc-50 text-lg font-black outline-none focus:border-[#FDB913] focus:bg-white transition" readOnly={readOnly} />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black uppercase text-gray-400 mb-2 tracking-widest">Stakeholder Owner *</label>
                      <select name="owner" required defaultValue={editingTask?.owner} className="w-full border p-3 rounded font-bold outline-none" disabled={readOnly}>
                        {users.map(u => <option key={u} value={u}>{u}</option>)}
                      </select>
                    </div>
                    <div>
                      <label className="block text-[10px] font-black uppercase text-gray-400 mb-2 tracking-widest">Estimated Duration (Total Hrs)</label>
                      <input type="number" step="0.5" name="hours" defaultValue={editingTask?.hours || 0} className="w-full border p-3 rounded font-black text-zinc-900 outline-none" readOnly={readOnly} placeholder="e.g. 40" />
                    </div>
                    <div>
                       <label className="block text-[10px] font-black uppercase text-gray-400 mb-2 tracking-widest">Operational Status</label>
                       <select name="status" defaultValue={editingTask?.status || 'Not Started'} className="w-full border p-3 rounded font-black outline-none" disabled={readOnly}>
                          {['Not Started', 'In Progress', 'Completed', 'Blocked', 'On Hold'].map(s => <option key={s} value={s}>{s}</option>)}
                       </select>
                    </div>
                    <div>
                       <div className="flex justify-between items-center mb-2">
                          <label className="block text-[10px] font-black uppercase text-gray-400 tracking-widest">Target Progress (%)</label>
                          <span className="text-[11px] font-black text-white bg-black px-3 py-1 rounded-full">{tempProgress}%</span>
                       </div>
                       <input type="range" name="progress" min="0" max="100" value={tempProgress} onChange={(e) => setTempProgress(parseInt(e.target.value))} className="w-full h-2 bg-zinc-100 rounded-lg appearance-none cursor-pointer accent-[#FDB913] mt-2" disabled={readOnly} />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black uppercase text-gray-400 mb-2 tracking-widest">Start Date</label>
                      <input type="date" name="startDate" defaultValue={editingTask?.startDate} className="w-full border p-3 rounded font-bold outline-none" readOnly={readOnly} />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black uppercase text-gray-400 mb-2 tracking-widest">Delivery Date</label>
                      <input type="date" name="dueDate" defaultValue={editingTask?.dueDate} className="w-full border p-3 rounded font-bold outline-none" readOnly={readOnly} />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black uppercase text-gray-400 mb-2 tracking-widest">Taxonomy Category</label>
                      <select name="category" defaultValue={editingTask?.category} className="w-full border p-3 rounded font-bold outline-none" disabled={readOnly}>
                        {categories.map(c => <option key={c} value={c}>{c}</option>)}
                      </select>
                    </div>
                  </div>

                  {/* Strategic Alignment Section */}
                  <div className="pt-6 border-t border-gray-100">
                    <h3 className="text-xs font-black uppercase tracking-widest text-black mb-4 flex items-center space-x-2">
                        <Link size={14} />
                        <span>Strategic Alignment (Optional)</span>
                    </h3>
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                        <div>
                            <label className="block text-[10px] font-black uppercase text-gray-400 mb-2 tracking-widest">Link to Project</label>
                            <select name="project" defaultValue={editingTask?.project || ''} className="w-full border p-3 rounded font-bold outline-none text-xs" disabled={readOnly}>
                                <option value="">-- No Project Link --</option>
                                {projects.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                            </select>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-gray-400 mb-2 tracking-widest">Link to OKR</label>
                            <select name="okrLink" defaultValue={editingTask?.okrLink || ''} className="w-full border p-3 rounded font-bold outline-none text-xs" disabled={readOnly}>
                                <option value="">-- No OKR Link --</option>
                                {okrs.map(o => <option key={o.id} value={o.id}>{o.objective}</option>)}
                            </select>
                        </div>
                        <div>
                            <label className="block text-[10px] font-black uppercase text-gray-400 mb-2 tracking-widest">Link to Improvement</label>
                            <select name="ideaLink" defaultValue={editingTask?.ideaLink || ''} className="w-full border p-3 rounded font-bold outline-none text-xs" disabled={readOnly}>
                                <option value="">-- No Improvement Link --</option>
                                {ideas.map(i => <option key={i.id} value={i.id}>{i.idea.substring(0, 30)}...</option>)}
                            </select>
                        </div>
                    </div>
                  </div>
                </form>
              ) : (
                <div className="space-y-6">
                  {editingTask?.history?.map((entry, idx) => (
                    <div key={idx} className="flex space-x-6">
                      <div className="w-28 shrink-0 text-[10px] font-black text-gray-400 mt-1 uppercase tracking-tighter">
                        {/* Fix: Replaced parseISO with native Date constructor */}
                        {format(new Date(entry.timestamp), 'MMM d, HH:mm')}
                      </div>
                      <div className="flex-1 pb-6 border-l-2 border-zinc-100 pl-8 relative">
                         <div className="absolute w-3 h-3 rounded-full bg-black -left-[7px] top-0 border-4 border-white"></div>
                         <p className="text-xs font-black text-zinc-800 uppercase tracking-tight">{entry.change}</p>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {!readOnly && (
              <div className="p-8 border-t bg-zinc-50 flex justify-between items-center shrink-0">
                  {editingTask && (
                      <button type="button" onClick={() => handleDeleteTask(editingTask.id)} className="px-6 py-3 text-[10px] font-black uppercase tracking-widest text-red-500 hover:bg-red-50 rounded transition flex items-center space-x-2">
                          <Trash2 size={14} />
                          <span>Delete Operation</span>
                      </button>
                  )}
                  {!editingTask && <div></div>} {/* Spacer */}
                  <div className="flex items-center space-x-4">
                    <button type="button" onClick={() => setShowModal(false)} className="px-8 py-3 text-[11px] font-black uppercase tracking-widest text-zinc-400 hover:text-black transition">Cancel</button>
                    <button type="submit" form="taskForm" className="px-12 py-4 bg-black text-[#FDB913] rounded-full font-black uppercase text-xs tracking-widest shadow-2xl transition hover:brightness-110">Commit Operation</button>
                  </div>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default TaskBoard;

export type Status = 'Not Started' | 'In Progress' | 'Completed' | 'Blocked' | 'On Hold';
export type Priority = 'High' | 'Medium' | 'Low';
export type ProjectStatus = 'Planning' | 'In Progress' | 'On Hold' | 'Completed' | 'Cancelled';

export interface HistoryEntry {
  timestamp: string;
  change: string;
}

export interface Comment {
  user: string;
  timestamp: string;
  comment: string;
}

export interface Booking {
  id: string;
  date: string;
  userId: string;
  targetId: string; // Task or Project ID
  targetType: 'task' | 'project';
  hours: number;
  description: string;
}

export interface Task {
  id: string;
  category: string;
  task: string;
  owner: string;
  project: string;
  status: Status;
  priority: Priority;
  progress: number;
  hours: number; // Estimated hours
  startDate: string;
  dueDate: string;
  originalDueDate?: string;
  notes: string;
  okrLink?: string;
  keyResultLink?: string; // Linked specific KR ID
  ideaLink?: string;
  history: HistoryEntry[];
  comments: Comment[];
}

export interface Project {
  id: string;
  name: string;
  manager: string;
  status: ProjectStatus;
  startDate: string;
  endDate: string;
  hours: number; // Estimated hours
  description: string;
  progress?: number; // Manual % completion
}

export interface Activity {
  id: string;
  date: string;
  person: string;
  activity: string;
  hours: number;
  status: 'Completed' | 'In Progress' | 'Blocked';
  remarks: string;
}

export interface KPI {
  id: string;
  name: string;
  target: string;
  completion: number;
  remarks: string;
}

export interface Idea {
  id: string;
  idea: string;
  proposer: string;
  impact: 'High' | 'Medium' | 'Low';
  cost: 'High' | 'Medium' | 'Low';
  status: 'New' | 'Under Review' | 'Approved' | 'Implemented' | 'Rejected';
  date: string;
}

export interface Kudos {
  id: string;
  from: string;
  to: string;
  reason: string;
  date: string;
}

export interface KeyResult {
  id: string;
  kr: string;
}

export interface OKR {
  id: string;
  objective: string;
  keyResults: KeyResult[];
}

export interface User {
  name: string;
  capacity: number;
}

export type SafetyStatusEntry = { status: 'green' | 'yellow' | 'red'; notes: string };
