interface ProjectBoardProps {
  projects: Project[];
  users: string[];
  updateProjects: (projects: Project[]) => void;
}

const ProjectBoard: React.FC<ProjectBoardProps> = ({ projects, users, updateProjects }) => {
  const [showModal, setShowModal] = useState(false);
  const [editingProject, setEditingProject] = useState<Project | null>(null);
  const [tempProgress, setTempProgress] = useState(0);

  const handleSaveProject = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const projData: Partial<Project> = {
      name: formData.get('name') as string,
      manager: formData.get('manager') as string,
      status: formData.get('status') as ProjectStatus,
      startDate: formData.get('startDate') as string,
      endDate: formData.get('endDate') as string,
      hours: parseFloat(formData.get('hours') as string),
      description: formData.get('description') as string,
      progress: tempProgress
    };

    if (editingProject) {
      updateProjects(projects.map(p => p.id === editingProject.id ? { ...p, ...projData } : p));
    } else {
      const newProj: Project = {
        id: Math.random().toString(36).substr(2, 9),
        progress: 0,
        ...projData as any
      };
      updateProjects([...projects, newProj]);
    }
    setShowModal(false);
    setEditingProject(null);
  };

  const openEdit = (p: Project | null) => {
      setEditingProject(p);
      setTempProgress(p ? (p.progress || 0) : 0);
      setShowModal(true);
  }

  const handleDelete = (id: string) => {
    if (confirm('Delete this project?')) {
      updateProjects(projects.filter(p => p.id !== id));
