import React, { useState } from 'react';
import { 
  format, addMonths, endOfMonth, 
  endOfWeek, eachDayOfInterval, isSameMonth, 
  isSameDay, addDays, isToday
} from 'date-fns';
import { Task, SafetyStatus } from '../types';
import { ChevronLeft, ChevronRight, AlertCircle, CheckCircle2, Info } from 'lucide-react';
import { BRAND } from '../constants';

interface CalendarViewProps {
  tasks: Task[];
  safetyStatus: SafetyStatus;
  updateSafetyStatus: (status: SafetyStatus) => void;
}

const CalendarView: React.FC<CalendarViewProps> = ({ tasks, safetyStatus, updateSafetyStatus }) => {
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState(new Date());

  const onDateClick = (day: Date) => {
    setSelectedDate(day);
  };

  const nextMonth = () => setCurrentMonth(addMonths(currentMonth, 1));
  const prevMonth = () => setCurrentMonth(addMonths(currentMonth, -1));

  const jumpToToday = () => {
    const now = new Date();
    setCurrentMonth(now);
    setSelectedDate(now);
  };

  const renderHeader = () => (
    <div className="flex justify-between items-center bg-white p-4 rounded-t-lg border-b border-gray-100">
      <h2 className="text-xl font-bold flex items-center space-x-2">
        <span>{format(currentMonth, 'MMMM yyyy')}</span>
      </h2>
      <div className="flex items-center space-x-2">
        <button onClick={prevMonth} className="p-2 hover:bg-gray-100 rounded-full transition"><ChevronLeft size={20} /></button>
        <button onClick={jumpToToday} className="px-4 py-1 text-xs font-bold uppercase border border-gray-200 rounded hover:bg-gray-50">Today</button>
        <button onClick={nextMonth} className="p-2 hover:bg-gray-100 rounded-full transition"><ChevronRight size={20} /></button>
      </div>
    </div>
  );

  const renderDays = () => {
    const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    return (
      <div className="grid grid-cols-7 bg-gray-50 border-b border-gray-200">
        {days.map(d => (
          <div key={d} className="py-2 text-center text-[10px] font-bold uppercase text-gray-400 tracking-widest">{d}</div>
        ))}
      </div>
    );
  };

  const renderCells = () => {
    const monthStart = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), 1);
    const monthEnd = endOfMonth(monthStart);
    const startDate = new Date(monthStart);
    startDate.setDate(startDate.getDate() - startDate.getDay());
    const endDate = endOfWeek(monthEnd);
    const calendarDays = eachDayOfInterval({ start: startDate, end: endDate });

    const rows = [];
    let days = [];

    calendarDays.forEach((day, i) => {
      const dateStr = format(day, 'yyyy-MM-dd');
      const status = safetyStatus[dateStr]?.status || null;
      const dayTasks = tasks.filter(t => t.dueDate === dateStr);

      const isSelected = isSameDay(day, selectedDate);
      const isCurrentMonth = isSameMonth(day, monthStart);
      const isTodayDate = isToday(day);

      days.push(
        <div
          key={dateStr}
          className={`min-h-[100px] border-r border-b border-gray-100 p-2 cursor-pointer transition-colors relative
            ${!isCurrentMonth ? 'bg-gray-50 text-gray-300' : 'bg-white'}
            ${isSelected ? 'bg-yellow-50/50 ring-1 ring-inset ring-[#FDB913]' : ''}
            ${isTodayDate && !isSelected ? 'bg-gray-50 ring-2 ring-inset ring-black' : ''}
            hover:bg-gray-50
          `}
          onClick={() => onDateClick(day)}
        >
          {isTodayDate && (
              <div className="absolute top-1 right-1">
                 <span className="flex h-2 w-2 relative">
                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                    <span className="relative inline-flex rounded-full h-2 w-2 bg-red-500"></span>
                 </span>
              </div>
          )}
          <div className="flex justify-between items-start">
            <span className={`text-sm font-bold ${isSelected ? 'text-[#FDB913]' : isTodayDate ? 'text-black font-black' : ''}`}>
              {format(day, 'd')}
            </span>
            {status && (
              <div className={`w-2 h-2 rounded-full ${status === 'green' ? 'bg-green-500' : status === 'yellow' ? 'bg-orange-500' : 'bg-red-500'}`}></div>
            )}
          </div>
          <div className="mt-2 space-y-1">
            {dayTasks.slice(0, 3).map(t => (
              <div key={t.id} className="text-[9px] px-1 bg-gray-100 rounded text-gray-600 truncate font-medium">
                {t.task}
              </div>
            ))}
            {dayTasks.length > 3 && (
              <div className="text-[8px] text-gray-400 pl-1 font-bold">+{dayTasks.length - 3} more</div>
            )}
          </div>
        </div>
      );

      if ((i + 1) % 7 === 0) {
        rows.push(<div key={i} className="grid grid-cols-7">{days}</div>);
        days = [];
      }
    });

    return <div className="bg-white border-l border-t border-gray-100">{rows}</div>;
  };

  const setDayStatus = (status: 'green' | 'yellow' | 'red') => {
    const dateStr = format(selectedDate, 'yyyy-MM-dd');
    const newSafety = { ...safetyStatus };
    newSafety[dateStr] = { ...newSafety[dateStr], status };
    updateSafetyStatus(newSafety);
  };

  const setDayNotes = (notes: string) => {
    const dateStr = format(selectedDate, 'yyyy-MM-dd');
    const newSafety = { ...safetyStatus };
    newSafety[dateStr] = { ...newSafety[dateStr], notes };
    updateSafetyStatus(newSafety);
  };

  const selectedDateStr = format(selectedDate, 'yyyy-MM-dd');
  const selectedTasks = tasks.filter(t => t.dueDate === selectedDateStr);
  const currentSafety = safetyStatus[selectedDateStr];

  return (
    <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
      <div className="lg:col-span-3 bg-white rounded-lg shadow-sm border border-gray-100 overflow-hidden">
        {renderHeader()}
        {renderDays()}
        {renderCells()}
      </div>

      <div className="space-y-6">
        <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-100">
          <h3 className="text-sm font-bold uppercase tracking-widest text-gray-400 mb-4">Date Details</h3>
          <p className="text-xl font-bold mb-6">{format(selectedDate, 'EEEE, MMM do')}</p>

          <div className="space-y-4">
            <div>
              <label className="block text-[10px] font-bold text-gray-500 uppercase mb-2">Safety & Health Status</label>
              <div className="flex space-x-2">
                {[
                  { val: 'green', color: 'bg-green-500', label: 'Good' },
                  { val: 'yellow', color: 'bg-orange-500', label: 'Mod.' },
                  { val: 'red', color: 'bg-red-500', label: 'Poor' }
                ].map(s => (
                  <button
                    key={s.val}
                    onClick={() => setDayStatus(s.val as any)}
                    className={`flex-1 py-2 px-1 rounded flex flex-col items-center justify-center transition-all border-2 
                      ${currentSafety?.status === s.val ? 'border-black' : 'border-transparent opacity-40 hover:opacity-100'}
                    `}
                  >
                    <div className={`w-3 h-3 rounded-full ${s.color} mb-1`}></div>
                    <span className="text-[10px] font-bold">{s.label}</span>
                  </button>
                ))}
              </div>
            </div>

            <div>
              <label className="block text-[10px] font-bold text-gray-500 uppercase mb-2">Daily Notes</label>
              <textarea
                className="w-full border border-gray-200 rounded p-2 text-sm focus:outline-none focus:ring-2 focus:ring-[#FDB913]"
                rows={4}
                placeholder="Shift notes, safety reports..."
                value={currentSafety?.notes || ''}
                onChange={(e) => setDayNotes(e.target.value)}
              ></textarea>
            </div>
          </div>
        </div>

        <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-100">
          <h3 className="text-sm font-bold uppercase tracking-widest text-gray-400 mb-4">Tasks Due ({selectedTasks.length})</h3>
          <div className="space-y-3 max-h-[300px] overflow-y-auto pr-2">
            {selectedTasks.length === 0 ? (
              <p className="text-sm text-gray-400 italic">No tasks due this day</p>
            ) : (
              selectedTasks.map(t => (
                <div key={t.id} className="p-3 bg-gray-50 rounded border-l-4 border-[#FDB913]">
                  <p className="text-sm font-bold text-gray-800 line-clamp-2">{t.task}</p>
                  <div className="flex justify-between items-center mt-1">
                    <span className="text-[10px] font-bold uppercase text-gray-500">{t.owner}</span>
                    <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded ${t.status === 'Completed' ? 'bg-green-100 text-green-700' : 'bg-gray-200'}`}>
                      {t.status}
                    </span>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default CalendarView;

import React, { useState, useEffect, useRef } from 'react';
import { 
  Calendar, CheckSquare, LayoutDashboard, Target, Clock, 
  Settings, Save, HardDrive, FileCode, Wifi, WifiOff,
  Lightbulb, Award, BarChart3, ListChecks, RefreshCw,
  Download, Upload, ShieldCheck, Database, History, Eye, Play,
  AlertTriangle, RotateCw, Link, RefreshCcw
} from 'lucide-react';
import { AppState, Task, Project, User, Idea, Kudos, OKR, Booking } from './types';
import { DEFAULT_USERS, DEFAULT_CATEGORIES, DEFAULT_AGENDA, BRAND } from './constants';
import Dashboard from './components/Dashboard';
import TaskBoard from './components/TaskBoard';
import ProjectBoard from './components/ProjectBoard';
import CalendarView from './components/CalendarView';
import IdeaMatrix from './components/IdeaMatrix';
import KudosBoard from './components/KudosBoard';
import OKRBoard from './components/OKRBoard';
import Masters from './components/Masters';
import HoursBooking from './components/HoursBooking';
import { Logo } from './components/Logo';

const STORAGE_KEY = 'epiroc_pulse_v5_final';
const APP_VERSION = '5.7.3';

const tabs = [
  { id: 'dashboard', name: 'Dashboard', icon: <LayoutDashboard size={18} /> },
  { id: 'calendar', name: 'Safety Calendar', icon: <Calendar size={18} /> },
  { id: 'tasks', name: 'Operations', icon: <CheckSquare size={18} /> },
  { id: 'projects', name: 'Projects', icon: <BarChart3 size={18} /> },
  { id: 'bookings', name: 'Time Logs', icon: <Clock size={18} /> },
  { id: 'okrs', name: 'Strategy', icon: <Target size={18} /> },
  { id: 'ideas', name: 'Improvements', icon: <Lightbulb size={18} /> },
  { id: 'kudos', name: 'Recognition', icon: <Award size={18} /> },
  { id: 'masters', name: 'Admin', icon: <Settings size={18} /> },
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isReadOnly, setIsReadOnly] = useState(false);
  const [data, setData] = useState<AppState>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) return JSON.parse(saved);
    return {
      version: APP_VERSION,
      tasks: [],
      projects: [],
      ideas: [],
      kudos: [],
      okrs: [],
      users: DEFAULT_USERS.map(name => ({ name, capacity: 160 })),
      bookings: [],
      categories: DEFAULT_CATEGORIES,
      safetyStatus: {},
      dailyAgenda: DEFAULT_AGENDA,
      deletedItemIds: []
    };
  });

  const [fileHandle, setFileHandle] = useState<FileSystemFileHandle | null>(null);
  const [backupDirHandle, setBackupDirHandle] = useState<FileSystemDirectoryHandle | null>(null);
  const [isAutoSaving, setIsAutoSaving] = useState(false);
  const [lastFileHash, setLastFileHash] = useState<string>('');
  const [lastSyncTime, setLastSyncTime] = useState<Date | null>(null);
  const [needsBackupAuth, setNeedsBackupAuth] = useState(false);

  const dataRef = useRef(data);
  useEffect(() => { dataRef.current = data; }, [data]);

  useEffect(() => {
    if (!isReadOnly) {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
    }
  }, [data, isReadOnly]);

  const performAutoBackup = async () => {
    if (!backupDirHandle || isReadOnly) return;

    const today = new Date().toISOString().split('T')[0];
    if (data.lastBackupDate === today) return;

    try {
      // @ts-ignore
      const permission = await backupDirHandle.queryPermission({ mode: 'readwrite' });
      if (permission !== 'granted') {
        setNeedsBackupAuth(true);
        return;
      }

      const fileName = `epiroc_daily_snapshot_${today}.json`;
      const newFileHandle = await backupDirHandle.getFileHandle(fileName, { create: true });
      // @ts-ignore
      const writable = await newFileHandle.createWritable();
      await writable.write(JSON.stringify(data, null, 2));
      await writable.close();

      setData(prev => ({ ...prev, lastBackupDate: today }));
      setNeedsBackupAuth(false);
    } catch (err) {
      console.error("Auto-backup failed", err);
      setNeedsBackupAuth(true);
    }
  };

  useEffect(() => {
    const timer = setTimeout(() => {
      if (backupDirHandle) performAutoBackup();
    }, 3000);
    return () => clearTimeout(timer);
  }, [backupDirHandle, data.lastBackupDate]);

  const mergeData = (local: AppState, remote: AppState): AppState => {
    // 1. Combine Tombstones (Deleted IDs) from both local and remote
    const allDeletedIds = new Set([
      ...(local.deletedItemIds || []),
      ...(remote.deletedItemIds || [])
    ]);

    // 2. Helper to merge arrays while respecting tombstones
    const mergeById = (a: any[], b: any[]) => {
      const map = new Map();
      [...(a || []), ...(b || [])].forEach(item => {
        // Only add item if its ID is NOT in the deleted list
        if (item && item.id && !allDeletedIds.has(item.id)) {
          // If collision, prefer remote (latest server state) or implicit "last write" from auto-sync
          map.set(item.id, item);
        }
      });
      return Array.from(map.values());
    };

    return {
      ...remote,
      version: APP_VERSION,
      tasks: mergeById(local.tasks, remote.tasks),
      projects: mergeById(local.projects, remote.projects),
      ideas: mergeById(local.ideas, remote.ideas),
      kudos: mergeById(local.kudos, remote.kudos),
      okrs: mergeById(local.okrs, remote.okrs),
      bookings: mergeById(local.bookings, remote.bookings),
      safetyStatus: { ...(local.safetyStatus || {}), ...(remote.safetyStatus || {}) },
      deletedItemIds: Array.from(allDeletedIds)
    };
  };

  const linkSharedFile = async () => {
    try {
      // @ts-ignore
      const [handle] = await window.showOpenFilePicker({
        types: [{ description: 'Epiroc Database', accept: { 'application/json': ['.json'] } }],
        multiple: false
      });
      setFileHandle(handle);
      setIsReadOnly(false);
      const file = await handle.getFile();
      const content = await file.text();
      if (content) {
        const remoteData = JSON.parse(content);
        setData(prev => mergeData(prev, remoteData));
        setLastFileHash(content);
      }
      setLastSyncTime(new Date());
    } catch (err) { console.error(err); }
  };

  const linkBackupDir = async () => {
    try {
      // @ts-ignore
      const handle = await window.showDirectoryPicker();
      setBackupDirHandle(handle);
      setNeedsBackupAuth(false);
      performAutoBackup();
    } catch (e) { console.error("Folder selection cancelled"); }
  };

  const reAuthBackup = async () => {
    if (!backupDirHandle) return;
    try {
      // @ts-ignore
      const permission = await backupDirHandle.requestPermission({ mode: 'readwrite' });
      if (permission === 'granted') {
        setNeedsBackupAuth(false);
        performAutoBackup();
      }
    } catch (e) { linkBackupDir(); }
  };

  const exportData = () => {
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `epiroc_manual_export_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
  };

  const manualSync = async () => {
    if (!fileHandle) return;
    setIsAutoSaving(true);
    try {
      const file = await fileHandle.getFile();
      const content = await file.text();

      const remoteData = JSON.parse(content);
      const merged = mergeData(dataRef.current, remoteData);

      // Perform write-back to ensure file has our latest local changes too
      // This mimics the auto-sync logic but forces it immediately
      const mergedContent = JSON.stringify(merged, null, 2);

      // @ts-ignore
      const writable = await fileHandle.createWritable();
      await writable.write(mergedContent);
      await writable.close();

      setData(merged);
      setLastFileHash(mergedContent);
      setLastSyncTime(new Date());
    } catch (err) { 
      console.error("Manual sync failed", err); 
    } finally { 
      setIsAutoSaving(false); 
    }
  };

  useEffect(() => {
    if (!fileHandle || isReadOnly) return;
    const interval = setInterval(async () => {
      try {
        setIsAutoSaving(true);
        const file = await fileHandle.getFile();
        const content = await file.text();
        if (content !== lastFileHash) {
          const remoteData = JSON.parse(content);
          const merged = mergeData(dataRef.current, remoteData);
          setData(merged);
          setLastFileHash(JSON.stringify(merged));
          setLastSyncTime(new Date());
        } else {
          const localContent = JSON.stringify(dataRef.current, null, 2);
          if (localContent !== lastFileHash) {
            // @ts-ignore
            const writable = await fileHandle.createWritable();
            await writable.write(localContent);
            await writable.close();
            setLastFileHash(localContent);
            setLastSyncTime(new Date());
          }
        }
      } catch (err) { console.error(err); } finally { setIsAutoSaving(false); }
    }, 10000);
    return () => clearInterval(interval);
  }, [fileHandle, lastFileHash, isReadOnly]);

  const updateData = (newData: Partial<AppState>) => {
    if (isReadOnly) return;

    setData(prev => {
      const deletedIds = new Set(prev.deletedItemIds || []);

      // Detect deleted items by comparing prev vs newData arrays
      const keysToCheck: (keyof AppState)[] = ['tasks', 'projects', 'ideas', 'kudos', 'okrs', 'bookings'];

      keysToCheck.forEach(key => {
        if (newData[key] && Array.isArray(newData[key]) && Array.isArray(prev[key])) {
          const prevArr = prev[key] as any[];
          const newArr = newData[key] as any[];

          // If item existed in prev but not in new, it was deleted
          prevArr.forEach(p => {
             if (p.id && !newArr.some(n => n.id === p.id)) {
               deletedIds.add(p.id);
             }
          });
        }
      });

      return { 
        ...prev, 
        ...newData,
        deletedItemIds: Array.from(deletedIds)
      };
    });
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#F8F9FA] relative">
      {needsBackupAuth && !isReadOnly && (
        <div className="bg-[#E74C3C] text-white py-2 px-8 flex items-center justify-between text-[11px] font-black uppercase tracking-widest z-[100] shadow-lg">
          <div className="flex items-center space-x-3">
             <AlertTriangle size={14} />
             <span>Daily Backup Engine requires authorization</span>
          </div>
          <button onClick={reAuthBackup} className="bg-white text-[#E74C3C] px-4 py-1 rounded-full flex items-center space-x-2 hover:bg-zinc-100 transition shadow-sm font-black">
            <Play size={10} fill="currentColor" />
            <span>AUTHORIZE SNAPSHOTS</span>
          </button>
        </div>
      )}

      {/* Brand Header */}
      <header className="h-32 flex items-center px-8 relative overflow-hidden transition-colors duration-500 text-[#3d4d5b]" style={{ backgroundColor: BRAND.YELLOW }}>
        <div className="flex flex-col z-10">
          <div className="flex items-center">
             <Logo />
          </div>

          {/* Operational Status below logo */}
          <div className="flex items-center space-x-6 ml-1 mt-2 text-[9px] uppercase tracking-[0.25em] font-black opacity-80">
            <span className="flex items-center">
              {fileHandle ? <Wifi size={11} className="mr-2" /> : <WifiOff size={11} className="mr-2" />}
              {fileHandle ? 'CONNECTED' : 'STANDALONE'}
            </span>
            <span className="flex items-center">
              <ShieldCheck size={11} className={`mr-2 ${backupDirHandle ? 'text-green-700' : ''}`} />
              BACKUP: {backupDirHandle ? 'ACTIVE' : 'OFF'}
            </span>
          </div>
        </div>

        <div className="flex-1"></div>

        <div className="flex items-center space-x-4 z-10">
           {!isReadOnly && (
              <button onClick={exportData} title="Export System Data" className="p-3.5 bg-[#3d4d5b]/10 rounded-full hover:bg-[#3d4d5b]/20 transition group">
                <Download size={22} className="group-hover:translate-y-0.5 transition" />
              </button>
           )}

           {fileHandle ? (
             <div className="flex items-center bg-white/40 pl-2 pr-6 py-1.5 rounded-full border border-black/5 shadow-lg backdrop-blur-sm space-x-4">
                <button 
                  onClick={manualSync}
                  title="Force Refresh & Sync"
                  className="px-5 py-2.5 bg-black text-[#FDB913] rounded-full hover:bg-zinc-800 transition shadow-sm flex items-center space-x-2"
                >
                   <RotateCw size={14} className={isAutoSaving ? 'animate-spin' : ''} />
                   <span className="text-[10px] font-black uppercase tracking-widest">SYNC NOW</span>
                </button>

                <div className="flex flex-col items-end border-r border-black/10 pr-4 py-1">
                  <span className="text-[9px] font-black uppercase opacity-60 tracking-widest">Database</span>
                  <div className="flex items-center space-x-1.5">
                    {isAutoSaving ? <RefreshCw size={10} className="animate-spin" /> : <Save size={10} />}
                    <span className="text-[10px] font-black tracking-tighter">{isAutoSaving ? 'SYNCING...' : 'LIVE'}</span>
                  </div>
                </div>
                <div className="flex flex-col items-end py-1">
                   <span className="text-[9px] font-black uppercase opacity-60 tracking-widest">Last Sync</span>
                   <span className="text-[10px] font-black">{lastSyncTime ? lastSyncTime.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) : '--:--'}</span>
                </div>
             </div>
           ) : !isReadOnly && (
             <div className="flex items-center space-x-2">
                 <button 
                    onClick={() => window.location.reload()} 
                    className="bg-white/80 hover:bg-white text-[#3d4d5b] px-6 py-5 rounded-full font-black text-xs uppercase tracking-widest shadow-sm flex items-center space-x-2 transition-all border border-black/5"
                    title="Reload Application Data"
                 >
                     <RefreshCcw size={16} />
                     <span>MANUAL REFRESH</span>
                 </button>
                 <button onClick={linkSharedFile} className="bg-[#3d4d5b] text-[#FDB913] hover:brightness-110 px-10 py-5 rounded-full font-black text-xs uppercase tracking-[0.25em] shadow-2xl flex items-center space-x-4 transition-all">
                   <FileCode size={20} />
                   <span>ESTABLISH TEAM LINK</span>
                 </button>
             </div>
           )}
        </div>
      </header>

      <nav className="bg-white border-b border-gray-200 sticky top-0 z-40 shadow-sm overflow-x-auto">
        <div className="max-w-7xl mx-auto flex min-w-max">
          {tabs.map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex items-center space-x-3 px-8 py-5 transition-all border-b-4 ${
                activeTab === tab.id ? 'border-[#FDB913] text-black font-black bg-gray-50' : 'border-transparent text-gray-400 hover:text-black hover:bg-gray-50'
              }`}
            >
              {tab.icon}
              <span className="text-[11px] uppercase tracking-[0.15em] font-black">{tab.name}</span>
            </button>
          ))}
        </div>
      </nav>

      <main className="flex-1 p-6 max-w-[1600px] mx-auto w-full mb-8">
        {activeTab === 'dashboard' && <Dashboard state={data} />}
        {activeTab === 'calendar' && <CalendarView tasks={data.tasks} safetyStatus={data.safetyStatus} updateSafetyStatus={(newStatus) => updateData({ safetyStatus: newStatus })} />}
        {activeTab === 'tasks' && <TaskBoard readOnly={isReadOnly} tasks={data.tasks} ideas={data.ideas} users={data.users.map(u => u.name)} categories={data.categories} projects={data.projects} okrs={data.okrs} bookings={data.bookings} updateTasks={(tasks) => updateData({ tasks })} />}
        {activeTab === 'projects' && <ProjectBoard projects={data.projects} users={data.users.map(u => u.name)} updateProjects={(projects) => updateData({ projects })} />}
        {activeTab === 'bookings' && <HoursBooking readOnly={isReadOnly} bookings={data.bookings} tasks={data.tasks} projects={data.projects} users={data.users.map(u => u.name)} updateBookings={(bookings) => updateData({ bookings })} />}
        {activeTab === 'okrs' && <OKRBoard okrs={data.okrs} tasks={data.tasks} updateOkrs={(okrs) => updateData({ okrs })} />}
        {activeTab === 'ideas' && <IdeaMatrix ideas={data.ideas} tasks={data.tasks} users={data.users.map(u => u.name)} updateIdeas={(ideas) => updateData({ ideas })} updateTasks={(tasks) => updateData({ tasks })} />}
        {activeTab === 'kudos' && <KudosBoard kudos={data.kudos} users={data.users.map(u => u.name)} updateKudos={(kudos) => updateData({ kudos })} />}
        {activeTab === 'masters' && (
          <div className="space-y-6">
            <div className="bg-white p-8 rounded-xl shadow-sm border border-gray-100 flex items-center justify-between">
               <div className="flex items-center space-x-5">
                  <div className={`p-4 rounded-xl ${backupDirHandle ? 'bg-green-50 text-green-600' : 'bg-zinc-50 text-zinc-400'}`}>
                    <Database size={32} />
                  </div>
                  <div>
                    <h3 className="text-xl font-black uppercase tracking-tight">System Snapshot Controller</h3>
                    <p className="text-sm text-gray-500 font-bold uppercase tracking-widest">
                      {backupDirHandle ? `Current Active Path: ${backupDirHandle.name}` : 'Establish a daily snapshot target directory for disaster recovery'}
                    </p>
                  </div>
               </div>
               <button onClick={linkBackupDir} className="bg-black text-[#FDB913] px-8 py-3 rounded-full text-[10px] font-black uppercase tracking-widest shadow-xl transition hover:brightness-110">
                 {backupDirHandle ? 'REMAP TARGET' : 'ENABLE SNAPSHOTS'}
               </button>
            </div>
            <Masters users={data.users} categories={data.categories} updateUsers={(users) => updateData({ users })} updateCategories={(categories) => updateData({ categories })} />
          </div>
        )}
      </main>

      <footer className="fixed bottom-2 right-4 text-[9px] text-gray-300 font-mono pointer-events-none z-50 mix-blend-multiply">
        Created by: Aditya Shitut
      </footer>
    </div>
  );
};

export default App;

export type Status = 'Not Started' | 'In Progress' | 'Completed' | 'Blocked' | 'On Hold';
export type Priority = 'High' | 'Medium' | 'Low';
export type ProjectStatus = 'Planning' | 'In Progress' | 'On Hold' | 'Completed' | 'Cancelled';

export interface HistoryEntry {
  timestamp: string;
  change: string;
  user?: string;
}

export interface GlobalActivity {
  id: string;
  timestamp: string;
  user: string;
  action: string;
  targetId: string;
  targetType: 'task' | 'project' | 'idea' | 'kudos' | 'okr' | 'system';
  description: string;
}

export interface ActiveLock {
  itemId: string;
  user: string;
  timestamp: string;
}

export interface Task {
  id: string;
  category: string;
  task: string;
  owner: string;
  project: string;
  status: Status;
  priority: Priority;
  progress: number;
  hours: number;
  startDate: string;
  dueDate: string;
  notes: string;
  updatedAt: string; // Used for property-level merging
  history: HistoryEntry[];
  okrLink?: string;
  keyResultLink?: string;
  ideaLink?: string;
}

export interface Project {
  id: string;
  name: string;
  manager: string;
  status: ProjectStatus;
  startDate: string;
  endDate: string;
  hours: number;
  description: string;
  progress: number;
  updatedAt: string;
}

export interface Idea {
  id: string;
  idea: string;
  proposer: string;
  impact: 'High' | 'Medium' | 'Low';
  cost: 'High' | 'Medium' | 'Low';
  status: 'New' | 'Under Review' | 'Approved' | 'Implemented' | 'Rejected';
  date: string;
  updatedAt: string;
}

export interface Kudos {
  id: string;
  from: string;
  to: string;
  reason: string;
  date: string;
}

export interface OKR {
  id: string;
  objective: string;
  keyResults: { id: string; kr: string }[];
  updatedAt: string;
}

export interface Booking {
  id: string;
  date: string;
  userId: string;
  targetId: string;
  targetType: 'task' | 'project';
  hours: number;
  description: string;
}

export interface User {
  name: string;
  capacity: number;
}

export type SafetyStatus = Record<string, { status: 'green' | 'yellow' | 'red'; notes: string }>;

export interface AppState {
  version: string;
  tasks: Task[];
  projects: Project[];
  ideas: Idea[];
  kudos: Kudos[];
  okrs: OKR[];
  users: User[];
  bookings: Booking[];
  categories: string[];
  safetyStatus: SafetyStatus;
  dailyAgenda: Record<string, string>;
  lastBackupDate?: string;
  deletedItemIds: string[];
  activeLocks: ActiveLock[]; // Multi-user soft locking
  globalActivity: GlobalActivity[]; // Centralized audit stream
  archivedTasks?: Task[]; // Suggestion #4: Archiving
}

import React, { useState, useEffect, useRef } from 'react';
import { 
  Calendar, CheckSquare, LayoutDashboard, Target, Clock, 
  Settings, Save, HardDrive, FileCode, Wifi, WifiOff,
  Lightbulb, Award, BarChart3, ListChecks, RefreshCw,
  Download, ShieldCheck, Database, Play,
  AlertTriangle, RotateCw, RefreshCcw, UserCircle, BellRing,
  Trash2, Archive
} from 'lucide-react';
import { AppState, Task, Project, User, Idea, Kudos, OKR, Booking, GlobalActivity, ActiveLock } from './types';
import { DEFAULT_USERS, DEFAULT_CATEGORIES, DEFAULT_AGENDA, BRAND } from './constants';
import Dashboard from './components/Dashboard';
import TaskBoard from './components/TaskBoard';
import ProjectBoard from './components/ProjectBoard';
import CalendarView from './components/CalendarView';
import IdeaMatrix from './components/IdeaMatrix';
import KudosBoard from './components/KudosBoard';
import OKRBoard from './components/OKRBoard';
import Masters from './components/Masters';
import HoursBooking from './components/HoursBooking';
import { Logo } from './components/Logo';

const STORAGE_KEY = 'epiroc_pulse_v6_pro';
const APP_VERSION = '6.0.0';

const tabs = [
  { id: 'dashboard', name: 'Dashboard', icon: <LayoutDashboard size={18} /> },
  { id: 'calendar', name: 'Safety Calendar', icon: <Calendar size={18} /> },
  { id: 'tasks', name: 'Operations', icon: <CheckSquare size={18} /> },
  { id: 'projects', name: 'Projects', icon: <BarChart3 size={18} /> },
  { id: 'bookings', name: 'Time Logs', icon: <Clock size={18} /> },
  { id: 'okrs', name: 'Strategy', icon: <Target size={18} /> },
  { id: 'ideas', name: 'Improvements', icon: <Lightbulb size={18} /> },
  { id: 'kudos', name: 'Recognition', icon: <Award size={18} /> },
  { id: 'masters', name: 'Admin', icon: <Settings size={18} /> },
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [currentUser, setCurrentUser] = useState<string>(() => localStorage.getItem('epiroc_user') || 'Guest');
  const [toasts, setToasts] = useState<{id: string, message: string, type: 'info' | 'warn'}[]>([]);

  const [data, setData] = useState<AppState>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) return JSON.parse(saved);
    return {
      version: APP_VERSION,
      tasks: [],
      projects: [],
      ideas: [],
      kudos: [],
      okrs: [],
      users: DEFAULT_USERS.map(name => ({ name, capacity: 160 })),
      bookings: [],
      categories: DEFAULT_CATEGORIES,
      safetyStatus: {},
      dailyAgenda: DEFAULT_AGENDA,
      deletedItemIds: [],
      activeLocks: [],
      globalActivity: [],
      archivedTasks: []
    };
  });

  const [fileHandle, setFileHandle] = useState<FileSystemFileHandle | null>(null);
  const [backupDirHandle, setBackupDirHandle] = useState<FileSystemDirectoryHandle | null>(null);
  const [isAutoSaving, setIsAutoSaving] = useState(false);
  const [lastFileHash, setLastFileHash] = useState<string>('');
  const [lastSyncTime, setLastSyncTime] = useState<Date | null>(null);
  const [needsBackupAuth, setNeedsBackupAuth] = useState(false);

  const dataRef = useRef(data);
  useEffect(() => { dataRef.current = data; }, [data]);

  // Persist local state
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
    localStorage.setItem('epiroc_user', currentUser);
  }, [data, currentUser]);

  const addToast = (message: string, type: 'info' | 'warn' = 'info') => {
    const id = Math.random().toString(36).substring(7);
    setToasts(prev => [...prev, { id, message, type }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 4000);
  };

  const logActivity = (action: string, description: string, targetId: string, targetType: GlobalActivity['targetType']) => {
    const newActivity: GlobalActivity = {
      id: Math.random().toString(36).substring(7),
      timestamp: new Date().toISOString(),
      user: currentUser,
      action,
      description,
      targetId,
      targetType
    };
    setData(prev => ({
      ...prev,
      globalActivity: [newActivity, ...(prev.globalActivity || [])].slice(0, 50)
    }));
  };

  // Property-Level Merge Logic (Suggestion #1)
  const mergePropLevel = (local: any[], remote: any[], deletedIds: Set<string>) => {
    const map = new Map();
    [...(local || []), ...(remote || [])].forEach(item => {
      if (!item?.id || deletedIds.has(item.id)) return;
      const existing = map.get(item.id);
      if (!existing || new Date(item.updatedAt || 0) > new Date(existing.updatedAt || 0)) {
        map.set(item.id, item);
      }
    });
    return Array.from(map.values());
  };

  const mergeData = (local: AppState, remote: AppState): AppState => {
    const allDeletedIds = new Set([...(local.deletedItemIds || []), ...(remote.deletedItemIds || [])]);

    // Prune expired locks (Suggestion #2)
    const now = new Date();
    const activeLocks = (remote.activeLocks || []).filter(l => 
      (now.getTime() - new Date(l.timestamp).getTime()) < 1000 * 60 * 5 // 5 min expiry
    );

    // Alert user if something they are editing was just updated by others
    if (remote.globalActivity && remote.globalActivity[0]?.user !== currentUser) {
      if (new Date(remote.globalActivity[0].timestamp) > (lastSyncTime || new Date(0))) {
        addToast(`Update from ${remote.globalActivity[0].user}: ${remote.globalActivity[0].action}`);
      }
    }

    return {
      ...remote,
      version: APP_VERSION,
      tasks: mergePropLevel(local.tasks, remote.tasks, allDeletedIds),
      projects: mergePropLevel(local.projects, remote.projects, allDeletedIds),
      ideas: mergePropLevel(local.ideas, remote.ideas, allDeletedIds),
      okrs: mergePropLevel(local.okrs, remote.okrs, allDeletedIds),
      kudos: [...(remote.kudos || [])], // Small arrays just replace
      bookings: [...(remote.bookings || [])],
      deletedItemIds: Array.from(allDeletedIds),
      activeLocks,
      globalActivity: [...(remote.globalActivity || [])].slice(0, 50)
    };
  };

  const linkSharedFile = async () => {
    try {
      // @ts-ignore
      const [handle] = await window.showOpenFilePicker({
        types: [{ description: 'Epiroc Pulse DB', accept: { 'application/json': ['.json'] } }],
        multiple: false
      });
      setFileHandle(handle);
      const file = await handle.getFile();
      const content = await file.text();
      if (content) {
        const remoteData = JSON.parse(content);
        setData(prev => mergeData(prev, remoteData));
        setLastFileHash(content);
      }
      setLastSyncTime(new Date());
      addToast("Team Link Established Successfully");
    } catch (err) { console.error(err); }
  };

  // Periodic Sync Engine
  useEffect(() => {
    if (!fileHandle) return;
    const interval = setInterval(async () => {
      try {
        setIsAutoSaving(true);
        const file = await fileHandle.getFile();
        const content = await file.text();

        // Data Integrity Check (Suggestion #3)
        let remoteData;
        try { 
          remoteData = JSON.parse(content); 
          if (!remoteData.version) throw new Error("Invalid Format");
        } catch (e) {
          addToast("Shared file corrupted! Using local version.", "warn");
          return;
        }

        if (content !== lastFileHash) {
          const merged = mergeData(dataRef.current, remoteData);
          setData(merged);
          setLastFileHash(JSON.stringify(merged));
          setLastSyncTime(new Date());
        } else {
          const localContent = JSON.stringify(dataRef.current, null, 2);
          if (localContent !== lastFileHash) {
            // @ts-ignore
            const writable = await fileHandle.createWritable();
            await writable.write(localContent);
            await writable.close();
            setLastFileHash(localContent);
            setLastSyncTime(new Date());
          }
        }
      } catch (err) { console.error(err); } finally { setIsAutoSaving(false); }
    }, 10000);
    return () => clearInterval(interval);
  }, [fileHandle, lastFileHash]);

  const updateData = (newData: Partial<AppState>) => {
    setData(prev => {
      const deletedIds = new Set(prev.deletedItemIds || []);
      const keys: (keyof AppState)[] = ['tasks', 'projects', 'ideas', 'okrs'];

      keys.forEach(k => {
        if (newData[k] && Array.isArray(newData[k])) {
          (prev[k] as any[]).forEach(p => {
             if (p.id && !(newData[k] as any[]).some(n => n.id === p.id)) {
               deletedIds.add(p.id);
             }
          });
        }
      });

      return { ...prev, ...newData, deletedItemIds: Array.from(deletedIds) };
    });
  };

  // Locking Logic (Suggestion #2)
  const setLock = (itemId: string | null) => {
    setData(prev => {
      let locks = [...(prev.activeLocks || [])];
      if (itemId) {
        if (!locks.some(l => l.itemId === itemId)) {
          locks.push({ itemId, user: currentUser, timestamp: new Date().toISOString() });
        }
      } else {
        locks = locks.filter(l => l.user !== currentUser);
      }
      return { ...prev, activeLocks: locks };
    });
  };

  // Archiving Engine (Suggestion #4)
  const archiveCompleted = () => {
    setData(prev => {
      const completed = prev.tasks.filter(t => t.status === 'Completed');
      const active = prev.tasks.filter(t => t.status !== 'Completed');
      addToast(`Archived ${completed.length} completed operations`);
      logActivity("Archive", `Moved ${completed.length} tasks to long-term storage`, 'system', 'system');
      return {
        ...prev,
        tasks: active,
        archivedTasks: [...(prev.archivedTasks || []), ...completed],
        deletedItemIds: [...prev.deletedItemIds, ...completed.map(t => t.id)]
      };
    });
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#F8F9FA] relative text-[#3d4d5b]">
      {/* Toast System (Suggestion #8) */}
      <div className="fixed bottom-6 left-6 z-[200] space-y-3 pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className={`${t.type === 'warn' ? 'bg-red-600' : 'bg-black'} text-white px-6 py-4 rounded-lg shadow-2xl flex items-center space-x-3 animate-bounce font-bold text-xs uppercase tracking-widest pointer-events-auto`}>
            <BellRing size={16} className="animate-pulse text-[#FDB913]" />
            <span>{t.message}</span>
          </div>
        ))}
      </div>

      <header className="h-32 flex items-center px-8 relative overflow-hidden transition-colors duration-500" style={{ backgroundColor: BRAND.YELLOW }}>
        <div className="flex flex-col z-10">
          <Logo />
          <div className="flex items-center space-x-6 ml-1 mt-2 text-[9px] uppercase tracking-[0.25em] font-black opacity-80">
            <span className="flex items-center">
              {fileHandle ? <Wifi size={11} className="mr-2" /> : <WifiOff size={11} className="mr-2" />}
              {fileHandle ? 'TEAM CONNECTED' : 'STANDALONE MODE'}
            </span>
            <div className="flex items-center group cursor-pointer">
               <UserCircle size={11} className="mr-2" />
               <select 
                 value={currentUser} 
                 onChange={(e) => setCurrentUser(e.target.value)}
                 className="bg-transparent border-none outline-none font-black text-[9px] cursor-pointer hover:bg-black/5 rounded px-1"
               >
                 {DEFAULT_USERS.map(u => <option key={u} value={u} className="bg-white text-black">{u}</option>)}
               </select>
            </div>
          </div>
        </div>

        <div className="flex-1"></div>

        <div className="flex items-center space-x-4 z-10">
           {fileHandle ? (
             <div className="flex items-center bg-white/40 pl-2 pr-6 py-1.5 rounded-full border border-black/5 shadow-lg backdrop-blur-sm space-x-4">
                <button onClick={async () => { await manualSync(); addToast("Manual Sync Triggered"); }} className="px-5 py-2.5 bg-black text-[#FDB913] rounded-full hover:bg-zinc-800 transition shadow-sm flex items-center space-x-2">
                   <RotateCw size={14} className={isAutoSaving ? 'animate-spin' : ''} />
                   <span className="text-[10px] font-black uppercase tracking-widest">SYNC NOW</span>
                </button>
                <div className="flex flex-col items-end py-1">
                   <span className="text-[9px] font-black uppercase opacity-60 tracking-widest">Shared Link</span>
                   <span className="text-[10px] font-black">{lastSyncTime ? lastSyncTime.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) : '--:--'}</span>
                </div>
             </div>
           ) : (
             <div className="flex items-center space-x-2">
                 <button onClick={() => window.location.reload()} className="bg-white/80 hover:bg-white px-6 py-5 rounded-full font-black text-xs uppercase tracking-widest shadow-sm flex items-center space-x-2 transition-all border border-black/5">
