import React, { useMemo, useState } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, 
  PieChart, Pie, Cell 
} from 'recharts';
import { AppState, SafetyStatusEntry } from '../types';
import { 
  Briefcase, CheckCircle2, Clock, Target, Layers, Filter, Activity, User
} from 'lucide-react';
import { 
  format, differenceInDays, 
  endOfMonth, endOfYear, addMonths, eachMonthOfInterval,
  isSameMonth, endOfWeek, eachDayOfInterval, eachWeekOfInterval, 
  addWeeks, addDays
} from 'date-fns';

const Dashboard: React.FC<{ state: AppState }> = ({ state }) => {
  const [timelineZoom, setTimelineZoom] = useState<'week' | 'month' | 'year'>('month');
  const [utilizationFilter, setUtilizationFilter] = useState<'week' | 'month' | 'year'>('month');
  const [stakeholderFilter, setStakeholderFilter] = useState('All');
  const [waterfallMode, setWaterfallMode] = useState<'timeline' | 'hierarchy'>('timeline');

  // Safety Analytics
  const safetyStats = useMemo(() => {
    const today = new Date();
    const currentMonthData = Object.entries(state.safetyStatus || {})
      .filter(([date]) => isSameMonth(new Date(date), today));

    const statusCounts = { green: 0, yellow: 0, red: 0 };
    currentMonthData.forEach(([_, val]) => {
      const entry = val as SafetyStatusEntry;
      if (entry && entry.status) statusCounts[entry.status]++;
    });

    return [
      { name: 'Safe Ops', value: statusCounts.green || 0 },
      { name: 'Risks Noted', value: statusCounts.yellow || 0 },
      { name: 'Incidents', value: statusCounts.red || 0 }
    ].filter(s => s.value > 0 || s.name === 'Safe Ops');
  }, [state.safetyStatus]);

  // Utilization
  const workloadData = useMemo(() => {
    const now = new Date();
    let intervals: Date[] = [];
    if (utilizationFilter === 'week') intervals = eachWeekOfInterval({ start: addWeeks(now, -2), end: addWeeks(now, 5) });
    else if (utilizationFilter === 'month') intervals = eachMonthOfInterval({ start: new Date(now.getFullYear(), 0, 1), end: addMonths(new Date(now.getFullYear(), 0, 1), 11) });
    else intervals = [new Date(now.getFullYear(), 0, 1), new Date(now.getFullYear() + 1, 0, 1)];

    return intervals.map(start => {
      let end, label;
      if (utilizationFilter === 'week') { end = addWeeks(start, 1); label = `W${format(start, 'w')}`; }
      else if (utilizationFilter === 'month') { end = addMonths(start, 1); label = format(start, 'MMM yy'); }
      else { end = addMonths(start, 12); label = format(start, 'yyyy'); }

      const filteredUsers = stakeholderFilter === 'All' ? state.users : state.users.filter(u => u.name === stakeholderFilter);
      const totalDailyCapacity = filteredUsers.reduce((acc, u) => acc + (u.capacity || 160), 0) * 12 / 365;
      const intervalCapacity = totalDailyCapacity * differenceInDays(end, start);

      let assigned = 0;
      state.projects.forEach(p => {
        if (p.status === 'Completed' || p.status === 'Cancelled') return;
        if (stakeholderFilter !== 'All' && p.manager !== stakeholderFilter) return;
        const overlapStart = new Date(p.startDate) > start ? new Date(p.startDate) : start;
        const overlapEnd = addDays(new Date(p.endDate), 1) < end ? addDays(new Date(p.endDate), 1) : end;
        if (overlapStart < overlapEnd) {
           assigned += ((p.hours || 0) / Math.max(1, differenceInDays(addDays(new Date(p.endDate), 1), new Date(p.startDate)))) * differenceInDays(overlapEnd, overlapStart);
        }
      });

      return { name: label, assigned: Math.round(assigned), capacity: Math.round(intervalCapacity) };
    });
  }, [state.tasks, state.projects, state.users, utilizationFilter, stakeholderFilter]);

  // Waterfall Items
  const timelineRange = useMemo(() => {
    const now = new Date();
    if (timelineZoom === 'week') return { start: startOfWeek(now), end: endOfWeek(now), total: 7 };
    if (timelineZoom === 'month') return { start: new Date(now.getFullYear(), now.getMonth(), 1), end: endOfMonth(new Date(now.getFullYear(), now.getMonth(), 1)), total: differenceInDays(endOfMonth(new Date(now.getFullYear(), now.getMonth(), 1)), new Date(now.getFullYear(), now.getMonth(), 1)) + 1 };
    return { start: new Date(now.getFullYear(), 0, 1), end: endOfYear(new Date(now.getFullYear(), 0, 1)), total: 365 };
  }, [timelineZoom]);

  function startOfWeek(date: Date) {
    const d = new Date(date);
    d.setDate(d.getDate() - d.getDay());
    return d;
  }

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        {[
          { label: 'Live Operations', value: state.tasks.filter(t => t.status !== 'Completed').length, icon: <Briefcase size={20} />, color: 'bg-black' },
          { label: 'Strategic Targets', value: state.okrs.length, icon: <Target size={20} />, color: 'bg-[#FDB913] text-black' },
          { label: 'Site Health', value: 'OPTIMAL', icon: <CheckCircle2 size={20} />, color: 'bg-green-600' },
          { label: 'Active Locks', value: state.activeLocks?.length || 0, icon: <Clock size={20} />, color: 'bg-zinc-800' },
        ].map((card, i) => (
          <div key={i} className={`${card.color} ${card.color.includes('text-black') ? '' : 'text-white'} p-6 rounded shadow-sm flex justify-between items-center transition hover:scale-[1.01]`}>
            <div>
              <p className="text-[10px] font-black uppercase opacity-60 mb-1">{card.label}</p>
              <p className="text-2xl font-black">{card.value}</p>
            </div>
            <div className="opacity-30">{card.icon}</div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Global Activity Stream (Suggestion #5) */}
        <div className="lg:col-span-1 bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex flex-col">
            <div className="flex items-center space-x-3 mb-6">
               <Activity className="text-[#FDB913]" size={20} />
               <h3 className="text-lg font-black uppercase tracking-tight">Team Pulse</h3>
            </div>
            <div className="flex-1 overflow-y-auto max-h-[600px] space-y-4 pr-2 custom-scrollbar">
               {state.globalActivity?.length ? state.globalActivity.map(a => (
                 <div key={a.id} className="relative pl-6 border-l-2 border-zinc-100 group">
                    <div className="absolute -left-[7px] top-1 w-3 h-3 rounded-full bg-white border-2 border-[#FDB913] group-hover:scale-125 transition"></div>
                    <div className="flex justify-between items-start">
                       <p className="text-[10px] font-black uppercase text-gray-400">{format(new Date(a.timestamp), 'HH:mm')}</p>
                       <span className="text-[8px] font-black bg-zinc-100 px-1.5 py-0.5 rounded text-zinc-500 uppercase">{a.user}</span>
                    </div>
                    <p className="text-xs font-black text-zinc-800 mt-0.5">{a.action}</p>
                    <p className="text-[10px] text-gray-500 line-clamp-1">{a.description}</p>
                 </div>
               )) : (
                 <p className="text-center py-10 text-gray-300 font-black uppercase text-[10px] tracking-widest">No Recent Activity</p>
               )}
            </div>
        </div>

        <div className="lg:col-span-2 space-y-6">
            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                <div className="flex justify-between items-center mb-8">
                   <div className="flex items-center space-x-3">
                      <Layers className="text-[#FDB913]" size={22} />
                      <h3 className="text-lg font-black uppercase tracking-tight">Resource Utilization</h3>
                   </div>
                   <div className="flex space-x-2">
                       <select className="bg-zinc-50 border border-zinc-200 rounded px-3 py-1.5 text-[10px] font-black uppercase outline-none" value={stakeholderFilter} onChange={(e) => setStakeholderFilter(e.target.value)}>
                         <option value="All">All Stakeholders</option>
                         {state.users.map(u => <option key={u.name} value={u.name}>{u.name}</option>)}
                       </select>
                   </div>
                </div>
                <div className="h-[320px]">
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={workloadData}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f5f5f5" />
                        <XAxis dataKey="name" tick={{fontSize: 10, fontWeight: 'bold', fill: '#bbb'}} axisLine={false} tickLine={false} />
                        <YAxis tick={{fontSize: 10, fill: '#bbb'}} axisLine={false} tickLine={false} />
                        <Tooltip contentStyle={{backgroundColor: '#000', color: '#fff', border: 'none', borderRadius: '8px', fontSize: '10px'}} />
                        <Bar name="Projected Load" dataKey="assigned" fill="#000" radius={[4, 4, 0, 0]} barSize={28} />
                        <Bar name="Capacity Limit" dataKey="capacity" fill="#FDB913" radius={[4, 4, 0, 0]} barSize={28} />
                      </BarChart>
                    </ResponsiveContainer>
                </div>
            </div>

            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex flex-col md:flex-row items-center">
                 <div className="flex-1 h-[250px] w-full">
                    <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                        <Pie data={safetyStats} innerRadius={60} outerRadius={85} paddingAngle={10} dataKey="value" stroke="none">
                          {safetyStats.map((entry, index) => (
                            <Cell key={index} fill={entry.name === 'Safe Ops' ? '#2ECC71' : entry.name === 'Risks Noted' ? '#F39C12' : '#E74C3C'} />
                          ))}
                        </Pie>
                        <Tooltip />
                      </PieChart>
                    </ResponsiveContainer>
                 </div>
                 <div className="flex-1 space-y-4 md:pl-10 md:border-l border-zinc-100 w-full mt-6 md:mt-0">
                    <h3 className="text-xs font-black uppercase text-gray-400 tracking-[0.2em] mb-4">Site Safety Snapshot</h3>
                    {safetyStats.map((s, i) => (
                         <div key={i} className="flex justify-between items-end border-b border-zinc-50 pb-2">
                            <span className="text-[10px] font-black uppercase text-gray-400">{s.name}</span>
                            <span className="text-xl font-black text-zinc-900">{s.value}</span>
                         </div>
                    ))}
                 </div>
            </div>
        </div>
      </div>
    </div>
  );
};

