import React, { useState, useMemo } from 'react';
import { Task, Status, Priority, OKR, Booking, Idea, ActiveLock } from '../types';
import { Plus, Trash2, Search, Target, Clock, ListChecks, History, Link, LayoutGrid, List, FileSpreadsheet, Lock } from 'lucide-react';
import { format } from 'date-fns';

interface TaskBoardProps {
  tasks: Task[];
  users: string[];
  categories: string[];
  projects: any[];
  okrs: OKR[];
  ideas?: Idea[];
  bookings: Booking[];
  currentUser: string;
  locks: ActiveLock[];
  setLock: (id: string | null) => void;
  logActivity: (action: string, desc: string, targetId: string, type: 'task') => void;
  updateTasks: (tasks: Task[]) => void;
}

const TaskBoard: React.FC<TaskBoardProps> = ({ 
  tasks, users, categories, projects, okrs, ideas = [], bookings, 
  currentUser, locks, setLock, logActivity, updateTasks 
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterOwner, setFilterOwner] = useState('All');
  const [viewMode, setViewMode] = useState<'list' | 'kanban'>('list');
  const [editingTask, setEditingTask] = useState<Task | null>(null);
  const [showModal, setShowModal] = useState(false);
  const [activeSubTab, setActiveSubTab] = useState<'details' | 'history'>('details');
  const [tempProgress, setTempProgress] = useState(0);

  const filteredTasks = useMemo(() => {
    return tasks.filter(t => {
      const matchSearch = t.task.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          t.owner.toLowerCase().includes(searchTerm.toLowerCase());
      const matchOwner = filterOwner === 'All' || t.owner === filterOwner;
      return matchSearch && matchOwner;
    });
  }, [tasks, searchTerm, filterOwner]);

  const exportCSV = () => {
    const headers = ['Task', 'Owner', 'Status', 'Priority', 'Progress', 'Hours', 'DueDate'];
    const rows = filteredTasks.map(t => [t.task, t.owner, t.status, t.priority, t.progress, t.hours, t.dueDate]);
    const content = [headers, ...rows].map(e => e.join(",")).join("\n");
    const blob = new Blob([content], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `epiroc_ops_${format(new Date(), 'yyyyMMdd')}.csv`;
    a.click();
  };

  const handleSaveTask = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const taskData: Partial<Task> = {
      task: formData.get('task') as string,
      owner: formData.get('owner') as string,
      category: formData.get('category') as string,
      project: formData.get('project') as string,
      status: formData.get('status') as Status,
      priority: formData.get('priority') as Priority,
      progress: tempProgress,
      hours: parseFloat(formData.get('hours') as string) || 0,
      startDate: formData.get('startDate') as string,
      dueDate: formData.get('dueDate') as string,
      notes: formData.get('notes') as string,
      updatedAt: new Date().toISOString()
    };

    if (editingTask) {
      logActivity("Update", `Modified operation: ${taskData.task}`, editingTask.id, 'task');
      updateTasks(tasks.map(t => t.id === editingTask.id ? { ...t, ...taskData } : t));
    } else {
      const newTask: Task = {
        id: Math.random().toString(36).substr(2, 9),
        history: [{ timestamp: new Date().toISOString(), change: 'Operation initialized', user: currentUser }],
        comments: [],
        ...taskData as any
      };
      logActivity("Create", `New operation: ${taskData.task}`, newTask.id, 'task');
      updateTasks([...tasks, newTask]);
    }
    setShowModal(false);
    setLock(null);
  };

  const openEdit = (task: Task | null) => {
    if (task) {
      const lock = locks.find(l => l.itemId === task.id);
      if (lock && lock.user !== currentUser) {
        alert(`This item is currently being edited by ${lock.user}. Please wait.`);
        return;
      }
      setLock(task.id);
    }
    setEditingTask(task);
    setTempProgress(task ? task.progress : 0);
    setShowModal(true);
  };

  const closeModal = () => {
    setLock(null);
    setShowModal(false);
  };

  const columns: Status[] = ['Not Started', 'In Progress', 'Blocked', 'On Hold', 'Completed'];

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap justify-between items-center gap-4 bg-white p-5 rounded shadow-sm border border-gray-100">
        <div className="flex items-center space-x-3 flex-1 max-w-2xl">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-400" size={18} />
            <input type="text" placeholder="Search team operations..." className="w-full pl-10 pr-4 py-3 border border-zinc-100 bg-zinc-50 rounded font-bold text-sm outline-none focus:bg-white" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
          </div>
          <div className="flex bg-zinc-100 p-1 rounded">
             <button onClick={() => setViewMode('list')} className={`p-2 rounded ${viewMode === 'list' ? 'bg-white shadow text-black' : 'text-gray-400'}`}><List size={18} /></button>
             <button onClick={() => setViewMode('kanban')} className={`p-2 rounded ${viewMode === 'kanban' ? 'bg-white shadow text-black' : 'text-gray-400'}`}><LayoutGrid size={18} /></button>
          </div>
        </div>
