        </div>
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
        {projects.map(project => (
          <div key={project.id} className="bg-white border border-gray-100 rounded-lg shadow-sm hover:shadow-md transition p-6 relative group">
            <div className="flex justify-between items-start mb-4">
