const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [currentUser, setCurrentUser] = useState<string>(() => localStorage.getItem('epiroc_user') || 'Guest');
  const [toasts, setToasts] = useState<{id: string, message: string, type: 'info' | 'warn'}[]>([]);

  const [data, setData] = useState<AppState>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) return JSON.parse(saved);
    return {
      version: APP_VERSION,
      tasks: [],
      projects: [],
      ideas: [],
      kudos: [],
      okrs: [],
      users: DEFAULT_USERS.map(name => ({ name, capacity: 160 })),
      bookings: [],
      categories: DEFAULT_CATEGORIES,
      safetyStatus: {},
      dailyAgenda: DEFAULT_AGENDA,
      deletedItemIds: [],
      activeLocks: [],
      globalActivity: [],
      archivedTasks: []
    };
  });

  const [fileHandle, setFileHandle] = useState<FileSystemFileHandle | null>(null);
  const [backupDirHandle, setBackupDirHandle] = useState<FileSystemDirectoryHandle | null>(null);
  const [isAutoSaving, setIsAutoSaving] = useState(false);
  const [lastFileHash, setLastFileHash] = useState<string>('');
  const [lastSyncTime, setLastSyncTime] = useState<Date | null>(null);
  const [needsBackupAuth, setNeedsBackupAuth] = useState(false);

  const dataRef = useRef(data);
  useEffect(() => { dataRef.current = data; }, [data]);

  // Persist local state
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
    localStorage.setItem('epiroc_user', currentUser);
  }, [data, currentUser]);

  const addToast = (message: string, type: 'info' | 'warn' = 'info') => {
    const id = Math.random().toString(36).substring(7);
    setToasts(prev => [...prev, { id, message, type }]);
    setTimeout(() => setToasts(prev => prev.filter(t => t.id !== id)), 4000);
  };

  const logActivity = (action: string, description: string, targetId: string, targetType: GlobalActivity['targetType']) => {
    const newActivity: GlobalActivity = {
      id: Math.random().toString(36).substring(7),
      timestamp: new Date().toISOString(),
      user: currentUser,
      action,
      description,
      targetId,
      targetType
    };
    setData(prev => ({
      ...prev,
      globalActivity: [newActivity, ...(prev.globalActivity || [])].slice(0, 50)
    }));
  };

  // Property-Level Merge Logic (Suggestion #1)
  const mergePropLevel = (local: any[], remote: any[], deletedIds: Set<string>) => {
    const map = new Map();
    [...(local || []), ...(remote || [])].forEach(item => {
      if (!item?.id || deletedIds.has(item.id)) return;
      const existing = map.get(item.id);
      if (!existing || new Date(item.updatedAt || 0) > new Date(existing.updatedAt || 0)) {
        map.set(item.id, item);
      }
    });
    return Array.from(map.values());
  };

  const mergeData = (local: AppState, remote: AppState): AppState => {
    const allDeletedIds = new Set([...(local.deletedItemIds || []), ...(remote.deletedItemIds || [])]);

    // Prune expired locks (Suggestion #2)
    const now = new Date();
    const activeLocks = (remote.activeLocks || []).filter(l => 
      (now.getTime() - new Date(l.timestamp).getTime()) < 1000 * 60 * 5 // 5 min expiry
    );

    // Alert user if something they are editing was just updated by others
    if (remote.globalActivity && remote.globalActivity[0]?.user !== currentUser) {
      if (new Date(remote.globalActivity[0].timestamp) > (lastSyncTime || new Date(0))) {
        addToast(`Update from ${remote.globalActivity[0].user}: ${remote.globalActivity[0].action}`);
      }
    }

    return {
      ...remote,
      version: APP_VERSION,
      tasks: mergePropLevel(local.tasks, remote.tasks, allDeletedIds),
      projects: mergePropLevel(local.projects, remote.projects, allDeletedIds),
      ideas: mergePropLevel(local.ideas, remote.ideas, allDeletedIds),
      okrs: mergePropLevel(local.okrs, remote.okrs, allDeletedIds),
      kudos: [...(remote.kudos || [])], // Small arrays just replace
      bookings: [...(remote.bookings || [])],
      deletedItemIds: Array.from(allDeletedIds),
      activeLocks,
      globalActivity: [...(remote.globalActivity || [])].slice(0, 50)
    };
  };

  const linkSharedFile = async () => {
    try {
      // @ts-ignore
      const [handle] = await window.showOpenFilePicker({
        types: [{ description: 'Epiroc Pulse DB', accept: { 'application/json': ['.json'] } }],
        multiple: false
      });
      setFileHandle(handle);
      const file = await handle.getFile();
      const content = await file.text();
      if (content) {
        const remoteData = JSON.parse(content);
        setData(prev => mergeData(prev, remoteData));
        setLastFileHash(content);
      }
      setLastSyncTime(new Date());
      addToast("Team Link Established Successfully");
    } catch (err) { console.error(err); }
  };

  // Manual Sync Implementation
  const manualSync = async () => {
    if (!fileHandle) return;
    try {
      setIsAutoSaving(true);
      const file = await fileHandle.getFile();
      const content = await file.text();

      let remoteData;
      try { 
        remoteData = JSON.parse(content); 
        if (!remoteData.version) throw new Error("Invalid Format");
      } catch (e) {
        addToast("Shared file corrupted! Using local version.", "warn");
        return;
      }

      const merged = mergeData(dataRef.current, remoteData);
      setData(merged);

      const localContent = JSON.stringify(merged, null, 2);
      // @ts-ignore
      const writable = await fileHandle.createWritable();
      await writable.write(localContent);
      await writable.close();

      setLastFileHash(localContent);
      setLastSyncTime(new Date());
    } catch (err) { 
      console.error(err); 
      addToast("Manual Sync Failed", "warn");
    } finally { 
      setIsAutoSaving(false); 
    }
  };

  // Periodic Sync Engine
  useEffect(() => {
    if (!fileHandle) return;
    const interval = setInterval(async () => {
      try {
        setIsAutoSaving(true);
        const file = await fileHandle.getFile();
        const content = await file.text();

        // Data Integrity Check (Suggestion #3)
        let remoteData;
        try { 
          remoteData = JSON.parse(content); 
          if (!remoteData.version) throw new Error("Invalid Format");
        } catch (e) {
          addToast("Shared file corrupted! Using local version.", "warn");
          return;
        }

        if (content !== lastFileHash) {
          const merged = mergeData(dataRef.current, remoteData);
          setData(merged);
          setLastFileHash(JSON.stringify(merged));
          setLastSyncTime(new Date());
        } else {
          const localContent = JSON.stringify(dataRef.current, null, 2);
          if (localContent !== lastFileHash) {
            // @ts-ignore
            const writable = await fileHandle.createWritable();
            await writable.write(localContent);
            await writable.close();
            setLastFileHash(localContent);
            setLastSyncTime(new Date());
          }
        }
      } catch (err) { console.error(err); } finally { setIsAutoSaving(false); }
    }, 10000);
    return () => clearInterval(interval);
  }, [fileHandle, lastFileHash]);

  const updateData = (newData: Partial<AppState>) => {
    setData(prev => {
      const deletedIds = new Set(prev.deletedItemIds || []);
      const keys: (keyof AppState)[] = ['tasks', 'projects', 'ideas', 'okrs'];

      keys.forEach(k => {
        if (newData[k] && Array.isArray(newData[k])) {
          (prev[k] as any[]).forEach(p => {
             if (p.id && !(newData[k] as any[]).some(n => n.id === p.id)) {
               deletedIds.add(p.id);
             }
          });
        }
      });

      return { ...prev, ...newData, deletedItemIds: Array.from(deletedIds) };
    });
  };

  // Locking Logic (Suggestion #2)
  const setLock = (itemId: string | null) => {
    setData(prev => {
      let locks = [...(prev.activeLocks || [])];
      if (itemId) {
        if (!locks.some(l => l.itemId === itemId)) {
          locks.push({ itemId, user: currentUser, timestamp: new Date().toISOString() });
        }
      } else {
        locks = locks.filter(l => l.user !== currentUser);
      }
      return { ...prev, activeLocks: locks };
    });
  };

  // Archiving Engine (Suggestion #4)
  const archiveCompleted = () => {
    setData(prev => {
      const completed = prev.tasks.filter(t => t.status === 'Completed');
      const active = prev.tasks.filter(t => t.status !== 'Completed');
      addToast(`Archived ${completed.length} completed operations`);
      logActivity("Archive", `Moved ${completed.length} tasks to long-term storage`, 'system', 'system');
      return {
        ...prev,
        tasks: active,
        archivedTasks: [...(prev.archivedTasks || []), ...completed],
        deletedItemIds: [...prev.deletedItemIds, ...completed.map(t => t.id)]
      };
    });
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#F8F9FA] relative text-[#3d4d5b]">
      {/* Toast System (Suggestion #8) */}
      <div className="fixed bottom-6 left-6 z-[200] space-y-3 pointer-events-none">
        {toasts.map(t => (
          <div key={t.id} className={`${t.type === 'warn' ? 'bg-red-600' : 'bg-black'} text-white px-6 py-4 rounded-lg shadow-2xl flex items-center space-x-3 animate-bounce font-bold text-xs uppercase tracking-widest pointer-events-auto`}>
            <BellRing size={16} className="animate-pulse text-[#FDB913]" />
            <span>{t.message}</span>
          </div>
        ))}
      </div>

      <header className="h-32 flex items-center px-8 relative overflow-hidden transition-colors duration-500" style={{ backgroundColor: BRAND.YELLOW }}>
        <div className="flex flex-col z-10">
          <Logo />
          <div className="flex items-center space-x-6 ml-1 mt-2 text-[9px] uppercase tracking-[0.25em] font-black opacity-80">
            <span className="flex items-center">
              {fileHandle ? <Wifi size={11} className="mr-2" /> : <WifiOff size={11} className="mr-2" />}
              {fileHandle ? 'TEAM CONNECTED' : 'STANDALONE MODE'}
            </span>
            <div className="flex items-center group cursor-pointer">
               <UserCircle size={11} className="mr-2" />
               <select 
                 value={currentUser} 
                 onChange={(e) => setCurrentUser(e.target.value)}
                 className="bg-transparent border-none outline-none font-black text-[9px] cursor-pointer hover:bg-black/5 rounded px-1"
               >
                 {DEFAULT_USERS.map(u => <option key={u} value={u} className="bg-white text-black">{u}</option>)}
               </select>
            </div>
          </div>
        </div>

        <div className="flex-1"></div>

        <div className="flex items-center space-x-4 z-10">
           {fileHandle ? (
             <div className="flex items-center bg-white/40 pl-2 pr-6 py-1.5 rounded-full border border-black/5 shadow-lg backdrop-blur-sm space-x-4">
                <button onClick={async () => { await manualSync(); addToast("Manual Sync Triggered"); }} className="px-5 py-2.5 bg-black text-[#FDB913] rounded-full hover:bg-zinc-800 transition shadow-sm flex items-center space-x-2">
                   <RotateCw size={14} className={isAutoSaving ? 'animate-spin' : ''} />
                   <span className="text-[10px] font-black uppercase tracking-widest">SYNC NOW</span>
                </button>
                <div className="flex flex-col items-end py-1">
                   <span className="text-[9px] font-black uppercase opacity-60 tracking-widest">Shared Link</span>
                   <span className="text-[10px] font-black">{lastSyncTime ? lastSyncTime.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) : '--:--'}</span>
                </div>
             </div>
           ) : (
             <div className="flex items-center space-x-2">
                 <button onClick={() => window.location.reload()} className="bg-white/80 hover:bg-white px-6 py-5 rounded-full font-black text-xs uppercase tracking-widest shadow-sm flex items-center space-x-2 transition-all border border-black/5">
                     <RefreshCcw size={16} />
                     <span>REFRESH</span>
                 </button>
                 <button onClick={linkSharedFile} className="bg-[#3d4d5b] text-[#FDB913] hover:brightness-110 px-10 py-5 rounded-full font-black text-xs uppercase tracking-[0.25em] shadow-2xl flex items-center space-x-4 transition-all">
                   <FileCode size={20} />
                   <span>CONNECT TEAM</span>
                 </button>
             </div>
           )}
        </div>
      </header>

      <nav className="bg-white border-b border-gray-200 sticky top-0 z-40 shadow-sm overflow-x-auto custom-scrollbar">
        <div className="max-w-7xl mx-auto flex min-w-max">
          {tabs.map(tab => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id)} className={`flex items-center space-x-3 px-8 py-5 transition-all border-b-4 ${activeTab === tab.id ? 'border-[#FDB913] text-black font-black bg-gray-50' : 'border-transparent text-gray-400 hover:text-black hover:bg-gray-50'}`}>
              {tab.icon}
              <span className="text-[11px] uppercase tracking-[0.15em] font-black">{tab.name}</span>
            </button>
          ))}
        </div>
      </nav>

      <main className="flex-1 p-6 max-w-[1600px] mx-auto w-full mb-8">
        {activeTab === 'dashboard' && <Dashboard state={data} />}
        {activeTab === 'calendar' && <CalendarView tasks={data.tasks} safetyStatus={data.safetyStatus} updateSafetyStatus={(newStatus) => updateData({ safetyStatus: newStatus })} />}
        {activeTab === 'tasks' && <TaskBoard currentUser={currentUser} locks={data.activeLocks} setLock={setLock} logActivity={logActivity} tasks={data.tasks} ideas={data.ideas} users={data.users.map(u => u.name)} categories={data.categories} projects={data.projects} okrs={data.okrs} bookings={data.bookings} updateTasks={(tasks) => updateData({ tasks })} />}
        {activeTab === 'projects' && <ProjectBoard projects={data.projects} users={data.users.map(u => u.name)} updateProjects={(projects) => updateData({ projects })} />}
        {activeTab === 'bookings' && <HoursBooking bookings={data.bookings} tasks={data.tasks} projects={data.projects} users={data.users.map(u => u.name)} updateBookings={(bookings) => updateData({ bookings })} />}
        {activeTab === 'okrs' && <OKRBoard okrs={data.okrs} tasks={data.tasks} updateOkrs={(okrs) => updateData({ okrs })} />}
        {activeTab === 'ideas' && <IdeaMatrix ideas={data.ideas} tasks={data.tasks} users={data.users.map(u => u.name)} updateIdeas={(ideas) => updateData({ ideas })} updateTasks={(tasks) => updateData({ tasks })} />}
        {activeTab === 'kudos' && <KudosBoard kudos={data.kudos} users={data.users.map(u => u.name)} updateKudos={(kudos) => updateData({ kudos })} />}
        {activeTab === 'masters' && (
          <div className="space-y-6">
            <div className="bg-white p-8 rounded-xl shadow-sm border border-gray-100 flex items-center justify-between">
               <div className="flex items-center space-x-5">
                  <div className="p-4 rounded-xl bg-zinc-900 text-[#FDB913]">
                    <Archive size={32} />
                  </div>
                  <div>
                    <h3 className="text-xl font-black uppercase tracking-tight">Operation Archive Engine</h3>
                    <p className="text-sm text-gray-500 font-bold uppercase tracking-widest">Maintenance: Clear completed items from the active sync loop to maintain peak performance</p>
                  </div>
               </div>
               <button onClick={archiveCompleted} className="bg-black text-[#FDB913] px-8 py-3 rounded-full text-[10px] font-black uppercase tracking-widest shadow-xl transition hover:brightness-110 flex items-center space-x-2">
                 <Trash2 size={14} />
                 <span>PURGE & ARCHIVE COMPLETED</span>
               </button>
            </div>
            <Masters users={data.users} categories={data.categories} updateUsers={(users) => updateData({ users })} updateCategories={(categories) => updateData({ categories })} />
          </div>
        )}
      </main>

      <footer className="fixed bottom-2 right-4 text-[9px] text-gray-300 font-mono pointer-events-none z-50 mix-blend-multiply">
        Created by: Aditya Shitut | Pro Sync v6
      </footer>
    </div>
  );
};

export default App;

import React, { useMemo, useState } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, 
  PieChart, Pie, Cell 
} from 'recharts';
import { AppState, SafetyStatusEntry } from '../types';
import { 
  Briefcase, CheckCircle2, Clock, Target, Layers, Filter, Activity, User
} from 'lucide-react';
import { 
  format, differenceInDays, 
  endOfMonth, endOfYear, addMonths, eachMonthOfInterval,
  isSameMonth, endOfWeek, eachDayOfInterval, eachWeekOfInterval, 
  addWeeks, addDays
} from 'date-fns';

const Dashboard: React.FC<{ state: AppState }> = ({ state }) => {
  const [timelineZoom, setTimelineZoom] = useState<'week' | 'month' | 'year'>('month');
  const [utilizationFilter, setUtilizationFilter] = useState<'week' | 'month' | 'year'>('month');
  const [stakeholderFilter, setStakeholderFilter] = useState('All');
  const [waterfallMode, setWaterfallMode] = useState<'timeline' | 'hierarchy'>('timeline');

  // Safety Analytics
  const safetyStats = useMemo(() => {
    const today = new Date();
    const currentMonthData = Object.entries(state.safetyStatus || {})
      .filter(([date]) => isSameMonth(new Date(date), today));

    const statusCounts = { green: 0, yellow: 0, red: 0 };
    currentMonthData.forEach(([_, val]) => {
      const entry = val as SafetyStatusEntry;
      if (entry && entry.status) statusCounts[entry.status]++;
    });

    return [
      { name: 'Safe Ops', value: statusCounts.green || 0 },
      { name: 'Risks Noted', value: statusCounts.yellow || 0 },
      { name: 'Incidents', value: statusCounts.red || 0 }
    ].filter(s => s.value > 0 || s.name === 'Safe Ops');
  }, [state.safetyStatus]);

  // Utilization
  const workloadData = useMemo(() => {
    const now = new Date();
    let intervals: Date[] = [];
    if (utilizationFilter === 'week') intervals = eachWeekOfInterval({ start: addWeeks(now, -2), end: addWeeks(now, 5) });
    else if (utilizationFilter === 'month') intervals = eachMonthOfInterval({ start: new Date(now.getFullYear(), 0, 1), end: addMonths(new Date(now.getFullYear(), 0, 1), 11) });
    else intervals = [new Date(now.getFullYear(), 0, 1), new Date(now.getFullYear() + 1, 0, 1)];

    return intervals.map(start => {
      let end, label;
      if (utilizationFilter === 'week') { end = addWeeks(start, 1); label = `W${format(start, 'w')}`; }
      else if (utilizationFilter === 'month') { end = addMonths(start, 1); label = format(start, 'MMM yy'); }
      else { end = addMonths(start, 12); label = format(start, 'yyyy'); }

      const filteredUsers = stakeholderFilter === 'All' ? state.users : state.users.filter(u => u.name === stakeholderFilter);
      const totalDailyCapacity = filteredUsers.reduce((acc, u) => acc + (u.capacity || 160), 0) * 12 / 365;
      const intervalCapacity = totalDailyCapacity * differenceInDays(end, start);

      let assigned = 0;
      state.projects.forEach(p => {
        if (p.status === 'Completed' || p.status === 'Cancelled') return;
        if (stakeholderFilter !== 'All' && p.manager !== stakeholderFilter) return;
        const overlapStart = new Date(p.startDate) > start ? new Date(p.startDate) : start;
        const overlapEnd = addDays(new Date(p.endDate), 1) < end ? addDays(new Date(p.endDate), 1) : end;
        if (overlapStart < overlapEnd) {
           assigned += ((p.hours || 0) / Math.max(1, differenceInDays(addDays(new Date(p.endDate), 1), new Date(p.startDate)))) * differenceInDays(overlapEnd, overlapStart);
        }
      });

      return { name: label, assigned: Math.round(assigned), capacity: Math.round(intervalCapacity) };
    });
  }, [state.tasks, state.projects, state.users, utilizationFilter, stakeholderFilter]);

  // Waterfall Items
  const timelineRange = useMemo(() => {
    const now = new Date();
    if (timelineZoom === 'week') return { start: startOfWeek(now), end: endOfWeek(now), total: 7 };
    if (timelineZoom === 'month') return { start: new Date(now.getFullYear(), now.getMonth(), 1), end: endOfMonth(new Date(now.getFullYear(), now.getMonth(), 1)), total: differenceInDays(endOfMonth(new Date(now.getFullYear(), now.getMonth(), 1)), new Date(now.getFullYear(), now.getMonth(), 1)) + 1 };
    return { start: new Date(now.getFullYear(), 0, 1), end: endOfYear(new Date(now.getFullYear(), 0, 1)), total: 365 };
  }, [timelineZoom]);

  function startOfWeek(date: Date) {
    const d = new Date(date);
    d.setDate(d.getDate() - d.getDay());
    return d;
  }

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        {[
          { label: 'Live Operations', value: state.tasks.filter(t => t.status !== 'Completed').length, icon: <Briefcase size={20} />, color: 'bg-black' },
          { label: 'Strategic Targets', value: state.okrs.length, icon: <Target size={20} />, color: 'bg-[#FDB913] text-black' },
          { label: 'Site Health', value: 'OPTIMAL', icon: <CheckCircle2 size={20} />, color: 'bg-green-600' },
          { label: 'Active Locks', value: state.activeLocks?.length || 0, icon: <Clock size={20} />, color: 'bg-zinc-800' },
        ].map((card, i) => (
          <div key={i} className={`${card.color} ${card.color.includes('text-black') ? '' : 'text-white'} p-6 rounded shadow-sm flex justify-between items-center transition hover:scale-[1.01]`}>
            <div>
              <p className="text-[10px] font-black uppercase opacity-60 mb-1">{card.label}</p>
              <p className="text-2xl font-black">{card.value}</p>
            </div>
            <div className="opacity-30">{card.icon}</div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Global Activity Stream (Suggestion #5) */}
        <div className="lg:col-span-1 bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex flex-col">
            <div className="flex items-center space-x-3 mb-6">
               <Activity className="text-[#FDB913]" size={20} />
               <h3 className="text-lg font-black uppercase tracking-tight">Team Pulse</h3>
            </div>
            <div className="flex-1 overflow-y-auto max-h-[600px] space-y-4 pr-2 custom-scrollbar">
               {state.globalActivity?.length ? state.globalActivity.map(a => (
                 <div key={a.id} className="relative pl-6 border-l-2 border-zinc-100 group">
                    <div className="absolute -left-[7px] top-1 w-3 h-3 rounded-full bg-white border-2 border-[#FDB913] group-hover:scale-125 transition"></div>
                    <div className="flex justify-between items-start">
                       <p className="text-[10px] font-black uppercase text-gray-400">{format(new Date(a.timestamp), 'HH:mm')}</p>
                       <span className="text-[8px] font-black bg-zinc-100 px-1.5 py-0.5 rounded text-zinc-500 uppercase">{a.user}</span>
                    </div>
                    <p className="text-xs font-black text-zinc-800 mt-0.5">{a.action}</p>
                    <p className="text-[10px] text-gray-500 line-clamp-1">{a.description}</p>
                 </div>
               )) : (
                 <p className="text-center py-10 text-gray-300 font-black uppercase text-[10px] tracking-widest">No Recent Activity</p>
               )}
            </div>
        </div>

        <div className="lg:col-span-2 space-y-6">
            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100">
                <div className="flex justify-between items-center mb-8">
                   <div className="flex items-center space-x-3">
                      <Layers className="text-[#FDB913]" size={22} />
                      <h3 className="text-lg font-black uppercase tracking-tight">Resource Utilization</h3>
                   </div>
                   <div className="flex space-x-2">
                       <select className="bg-zinc-50 border border-zinc-200 rounded px-3 py-1.5 text-[10px] font-black uppercase outline-none" value={stakeholderFilter} onChange={(e) => setStakeholderFilter(e.target.value)}>
                         <option value="All">All Stakeholders</option>
                         {state.users.map(u => <option key={u.name} value={u.name}>{u.name}</option>)}
                       </select>
                   </div>
                </div>
                <div className="h-[320px]">
                    <ResponsiveContainer width="100%" height="100%">
                      <BarChart data={workloadData}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f5f5f5" />
                        <XAxis dataKey="name" tick={{fontSize: 10, fontWeight: 'bold', fill: '#bbb'}} axisLine={false} tickLine={false} />
                        <YAxis tick={{fontSize: 10, fill: '#bbb'}} axisLine={false} tickLine={false} />
                        <Tooltip contentStyle={{backgroundColor: '#000', color: '#fff', border: 'none', borderRadius: '8px', fontSize: '10px'}} />
                        <Bar name="Projected Load" dataKey="assigned" fill="#000" radius={[4, 4, 0, 0]} barSize={28} />
                        <Bar name="Capacity Limit" dataKey="capacity" fill="#FDB913" radius={[4, 4, 0, 0]} barSize={28} />
                      </BarChart>
                    </ResponsiveContainer>
                </div>
            </div>

            <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex flex-col md:flex-row items-center">
                 <div className="flex-1 h-[250px] w-full">
                    <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                        <Pie data={safetyStats} innerRadius={60} outerRadius={85} paddingAngle={10} dataKey="value" stroke="none">
                          {safetyStats.map((entry, index) => (
                            <Cell key={index} fill={entry.name === 'Safe Ops' ? '#2ECC71' : entry.name === 'Risks Noted' ? '#F39C12' : '#E74C3C'} />
                          ))}
                        </Pie>
                        <Tooltip />
                      </PieChart>
                    </ResponsiveContainer>
                 </div>
                 <div className="flex-1 space-y-4 md:pl-10 md:border-l border-zinc-100 w-full mt-6 md:mt-0">
                    <h3 className="text-xs font-black uppercase text-gray-400 tracking-[0.2em] mb-4">Site Safety Snapshot</h3>
                    {safetyStats.map((s, i) => (
                         <div key={i} className="flex justify-between items-end border-b border-zinc-50 pb-2">
                            <span className="text-[10px] font-black uppercase text-gray-400">{s.name}</span>
                            <span className="text-xl font-black text-zinc-900">{s.value}</span>
                         </div>
                    ))}
                 </div>
            </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Idea, Task } from '../types';
import { Lightbulb, Plus, Trash2, TrendingUp, DollarSign } from 'lucide-react';

interface IdeaMatrixProps {
  ideas: Idea[];
  tasks: Task[];
  users: string[];
  updateIdeas: (ideas: Idea[]) => void;
  updateTasks: (tasks: Task[]) => void;
}

const IdeaMatrix: React.FC<IdeaMatrixProps> = ({ ideas, tasks, users, updateIdeas, updateTasks }) => {
  const [showModal, setShowModal] = useState(false);

  const quadrants = [
    { impact: 'High', cost: 'Low', label: 'Quick Wins 🚀', color: 'bg-green-50' },
    { impact: 'High', cost: 'Medium', label: 'Growth Ops 📈', color: 'bg-blue-50' },
    { impact: 'High', cost: 'High', label: 'Major Projects ⛰️', color: 'bg-purple-50' },
    { impact: 'Medium', cost: 'Low', label: 'Steady Wins ✨', color: 'bg-green-50/50' },
    { impact: 'Medium', cost: 'Medium', label: 'Tactical Needs 🛠️', color: 'bg-gray-50' },
    { impact: 'Medium', cost: 'High', label: 'Review Carefully 🧐', color: 'bg-orange-50' },
    { impact: 'Low', cost: 'Low', label: 'Fill-ins 🧹', color: 'bg-gray-100' },
    { impact: 'Low', cost: 'Medium', label: 'Low Priority 📉', color: 'bg-orange-50/50' },
    { impact: 'Low', cost: 'High', label: 'Reconsider ❌', color: 'bg-red-50' },
  ];

  const handleSaveIdea = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
