import React, { useMemo, useState } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  PieChart, Pie, Cell 
} from 'recharts';
import { AppState, SafetyStatusEntry } from '../types';
import { 
  Briefcase, CheckCircle2, Clock, Target, Layers
} from 'lucide-react';
import { 
  format, differenceInDays, 
  eachMonthOfInterval,
  isSameMonth, eachWeekOfInterval, 
  addWeeks, addDays, addMonths
} from 'date-fns';

const Dashboard: React.FC<{ state: AppState }> = ({ state }) => {
  const [utilizationFilter] = useState<'month'>('month');
  const [stakeholderFilter, setStakeholderFilter] = useState('All');

  const safetyStats = useMemo(() => {
    const today = new Date();
    const currentMonthData = Object.entries(state.safetyStatus || {})
      .filter(([date]) => isSameMonth(new Date(date), today));

    const statusCounts = { green: 0, yellow: 0, red: 0 };
    currentMonthData.forEach(([_, val]) => {
      const entry = val as SafetyStatusEntry;
      if (entry && entry.status) statusCounts[entry.status]++;
    });

    return [
      { name: 'Safe Ops', value: statusCounts.green || 0 },
      { name: 'Risks Noted', value: statusCounts.yellow || 0 },
      { name: 'Incidents', value: statusCounts.red || 0 }
    ].filter(s => s.value > 0 || s.name === 'Safe Ops');
  }, [state.safetyStatus]);

  const workloadData = useMemo(() => {
    const now = new Date();
    const intervals = eachMonthOfInterval({ start: new Date(now.getFullYear(), 0, 1), end: addMonths(new Date(now.getFullYear(), 0, 1), 11) });

    return intervals.map(start => {
      const end = addMonths(start, 1);
      const label = format(start, 'MMM yy');

      const filteredUsers = stakeholderFilter === 'All' ? state.users : state.users.filter(u => u.name === stakeholderFilter);
      const totalDailyCapacity = filteredUsers.reduce((acc, u) => acc + (u.capacity || 160), 0) * 12 / 365;
      const intervalCapacity = totalDailyCapacity * differenceInDays(end, start);

      let assigned = 0;
      state.projects.forEach(p => {
        if (p.status === 'Completed' || p.status === 'Cancelled') return;
        if (stakeholderFilter !== 'All' && p.manager !== stakeholderFilter) return;
        const overlapStart = new Date(p.startDate) > start ? new Date(p.startDate) : start;
        const overlapEnd = addDays(new Date(p.endDate), 1) < end ? addDays(new Date(p.endDate), 1) : end;
        if (overlapStart < overlapEnd) {
           assigned += ((p.hours || 0) / Math.max(1, differenceInDays(addDays(new Date(p.endDate), 1), new Date(p.startDate)))) * differenceInDays(overlapEnd, overlapStart);
        }
      });

      return { name: label, assigned: Math.round(assigned), capacity: Math.round(intervalCapacity) };
    });
  }, [state.projects, state.users, stakeholderFilter]);

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        {[
          { label: 'Live Operations', value: state.tasks.filter(t => t.status !== 'Completed').length, icon: <Briefcase size={20} />, color: 'bg-black' },
          { label: 'Strategic Targets', value: state.okrs.length, icon: <Target size={20} />, color: 'bg-[#FDB913] text-black' },
          { label: 'Site Health', value: 'OPTIMAL', icon: <CheckCircle2 size={20} />, color: 'bg-green-600' },
          { label: 'Active Locks', value: state.activeLocks?.length || 0, icon: <Clock size={20} />, color: 'bg-zinc-800' },
        ].map((card, i) => (
          <div key={i} className={`${card.color} ${card.color.includes('text-black') ? '' : 'text-white'} p-6 rounded shadow-sm flex justify-between items-center`}>
            <div>
              <p className="text-[10px] font-black uppercase opacity-60 mb-1">{card.label}</p>
              <p className="text-2xl font-black">{card.value}</p>
            </div>
            <div className="opacity-30">{card.icon}</div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 bg-white p-6 rounded-xl shadow-sm border border-gray-100">
            <div className="flex justify-between items-center mb-8">
                <div className="flex items-center space-x-3">
                    <Layers className="text-[#FDB913]" size={22} />
                    <h3 className="text-lg font-black uppercase tracking-tight">Resource Utilization</h3>
                </div>
                <select className="bg-zinc-50 border border-zinc-200 rounded px-3 py-1.5 text-[10px] font-black uppercase outline-none" value={stakeholderFilter} onChange={(e) => setStakeholderFilter(e.target.value)}>
                    <option value="All">All Stakeholders</option>
                    {state.users.map(u => <option key={u.name} value={u.name}>{u.name}</option>)}
                </select>
            </div>
            <div className="h-[320px]">
                <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={workloadData}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f5f5f5" />
                        <XAxis dataKey="name" tick={{fontSize: 10, fontWeight: 'bold', fill: '#bbb'}} axisLine={false} tickLine={false} />
                        <YAxis tick={{fontSize: 10, fill: '#bbb'}} axisLine={false} tickLine={false} />
                        <Tooltip />
                        <Bar name="Load" dataKey="assigned" fill="#000" radius={[4, 4, 0, 0]} barSize={28} />
                        <Bar name="Capacity" dataKey="capacity" fill="#FDB913" radius={[4, 4, 0, 0]} barSize={28} />
                    </BarChart>
                </ResponsiveContainer>
            </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-gray-100 flex flex-col justify-center">
            <div className="h-[250px] w-full">
                <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                        <Pie data={safetyStats} innerRadius={60} outerRadius={85} paddingAngle={10} dataKey="value" stroke="none">
                            {safetyStats.map((entry, index) => (
                                <Cell key={index} fill={entry.name === 'Safe Ops' ? '#2ECC71' : entry.name === 'Risks Noted' ? '#F39C12' : '#E74C3C'} />
                            ))}
                        </Pie>
                        <Tooltip />
                    </PieChart>
                </ResponsiveContainer>
            </div>
            <div className="space-y-4 mt-6">
                <h3 className="text-xs font-black uppercase text-gray-400 tracking-[0.2em] text-center">Safety Snapshot</h3>
                {safetyStats.map((s, i) => (
                    <div key={i} className="flex justify-between items-end border-b border-zinc-50 pb-2">
                        <span className="text-[10px] font-black uppercase text-gray-400">{s.name}</span>
                        <span className="text-xl font-black text-zinc-900">{s.value}</span>
                    </div>
                ))}
            </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { Task, Status, Priority, OKR, Booking, ActiveLock } from '../types';
import { Search, Lock } from 'lucide-react';

interface TaskBoardProps {
  tasks: Task[];
  users: string[];
  categories: string[];
  projects: any[];
  okrs: OKR[];
  bookings: Booking[];
  currentUser: string;
  locks: ActiveLock[];
  setLock: (id: string | null) => void;
  updateTasks: (tasks: Task[]) => void;
}

const TaskBoard: React.FC<TaskBoardProps> = ({ 
  tasks, users, categories, projects, okrs, bookings, 
  currentUser, locks, setLock, updateTasks 
}) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [editingTask, setEditingTask] = useState<Task | null>(null);
  const [showModal, setShowModal] = useState(false);
  const [tempProgress, setTempProgress] = useState(0);

  const filteredTasks = useMemo(() => {
    return tasks.filter(t => 
      t.task.toLowerCase().includes(searchTerm.toLowerCase()) ||
      t.owner.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [tasks, searchTerm]);

  const handleSaveTask = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const taskData: Partial<Task> = {
      task: formData.get('task') as string,
      owner: formData.get('owner') as string,
      category: formData.get('category') as string,
      project: formData.get('project') as string,
      status: formData.get('status') as Status,
      priority: formData.get('priority') as Priority,
      progress: tempProgress,
      hours: parseFloat(formData.get('hours') as string) || 0,
      startDate: formData.get('startDate') as string,
      dueDate: formData.get('dueDate') as string,
      notes: formData.get('notes') as string,
      updatedAt: new Date().toISOString()
    };

    if (editingTask) {
      updateTasks(tasks.map(t => t.id === editingTask.id ? { ...t, ...taskData } : t));
    } else {
      const newTask: Task = {
        id: Math.random().toString(36).substr(2, 9),
        history: [{ timestamp: new Date().toISOString(), change: 'Operation initialized' }],
        comments: [],
        ...taskData as any
      };
      updateTasks([...tasks, newTask]);
    }
    setShowModal(false);
    setLock(null);
  };

  const openEdit = (task: Task | null) => {
    if (task) {
      const lock = locks.find(l => l.itemId === task.id);
      if (lock && lock.user !== currentUser) {
        alert(`This item is currently being edited by ${lock.user}. Please wait.`);
        return;
      }
      setLock(task.id);
    }
    setEditingTask(task);
    setTempProgress(task ? task.progress : 0);
    setShowModal(true);
  };

  const closeModal = () => {
    setLock(null);
    setShowModal(false);
  };

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center bg-white p-5 rounded shadow-sm border border-gray-100">
        <div className="relative flex-1 max-w-2xl">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-400" size={18} />
          <input type="text" placeholder="Filter team operations..." className="w-full pl-10 pr-4 py-3 border border-zinc-100 bg-zinc-50 rounded font-bold text-sm outline-none" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
        </div>
        <button onClick={() => openEdit(null)} className="bg-black text-[#FDB913] px-8 py-3 rounded font-black text-xs uppercase tracking-widest shadow-xl ml-4">NEW OPERATION</button>
      </div>

      <div className="bg-white rounded shadow-sm border border-gray-100 overflow-hidden overflow-x-auto">
        <table className="w-full text-left min-w-[800px]">
          <thead className="bg-zinc-50 border-b border-gray-100">
            <tr>
              <th className="px-6 py-5 text-[10px] font-black uppercase text-gray-400 tracking-widest">Detail</th>
              <th className="px-6 py-5 text-[10px] font-black uppercase text-gray-400 tracking-widest">Stakeholder</th>
              <th className="px-6 py-5 text-[10px] font-black uppercase text-gray-400 tracking-widest">Lock Status</th>
              <th className="px-6 py-5 text-[10px] font-black uppercase text-gray-400 tracking-widest text-right">Progress</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-50">
            {filteredTasks.map(t => {
              const lock = locks.find(l => l.itemId === t.id);
              return (
                <tr key={t.id} className="hover:bg-zinc-50 transition cursor-pointer" onClick={() => openEdit(t)}>
                  <td className="px-6 py-5">
                    <p className="font-black text-zinc-900 text-sm mb-1">{t.task}</p>
                    <span className="text-[8px] font-black uppercase bg-zinc-100 text-zinc-500 px-2 py-0.5 rounded mr-2">{t.category}</span>
                    <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded ${t.status === 'Completed' ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-600'}`}>{t.status}</span>
                  </td>
                  <td className="px-6 py-5 text-xs font-black text-zinc-700 uppercase">{t.owner}</td>
                  <td className="px-6 py-5">
                     {lock ? (
                       <div className="flex items-center space-x-2 text-orange-500 font-black text-[9px]">
                          <Lock size={12} className="animate-pulse" />
                          <span>EDITING: {lock.user}</span>
                       </div>
                     ) : (
                       <span className="text-[9px] font-black uppercase text-gray-300 tracking-tighter">Available</span>
                     )}
                  </td>
                  <td className="px-6 py-5 text-right font-black">{t.progress}%</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {showModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md">
           <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl overflow-hidden">
              <div className="p-8 bg-[#FDB913] text-black flex justify-between items-center">
                <h2 className="text-2xl font-black uppercase tracking-tight">{editingTask ? 'Edit Operation' : 'New Operation'}</h2>
                <button onClick={closeModal} className="font-black text-3xl">×</button>
              </div>
              <form onSubmit={handleSaveTask} className="p-8 space-y-6">
                 <div className="grid grid-cols-2 gap-6">
                    <div className="col-span-2">
                      <label className="block text-[10px] font-black uppercase text-gray-400 mb-1">Task Description</label>
                      <input name="task" required defaultValue={editingTask?.task} className="w-full border-b-2 p-3 bg-zinc-50 text-lg font-black outline-none" />
                    </div>
                    <div>
                       <label className="block text-[10px] font-black uppercase text-gray-400 mb-1">Stakeholder</label>
                       <select name="owner" required defaultValue={editingTask?.owner || currentUser} className="w-full border p-3 rounded font-bold">
                          {users.map(u => <option key={u} value={u}>{u}</option>)}
                       </select>
                    </div>
                    <div>
                       <label className="block text-[10px] font-black uppercase text-gray-400 mb-1">Status</label>
                       <select name="status" defaultValue={editingTask?.status || 'Not Started'} className="w-full border p-3 rounded font-bold">
                          <option value="Not Started">Not Started</option>
                          <option value="In Progress">In Progress</option>
                          <option value="Completed">Completed</option>
                          <option value="Blocked">Blocked</option>
                       </select>
                    </div>
                    <div className="col-span-2">
                       <label className="text-[10px] font-black uppercase text-gray-400">Progress: {tempProgress}%</label>
                       <input type="range" min="0" max="100" value={tempProgress} onChange={e => setTempProgress(parseInt(e.target.value))} className="w-full accent-black h-2 bg-zinc-100 rounded-full mt-2" />
                    </div>
                 </div>
                 <div className="flex justify-end space-x-4 pt-6">
                    <button type="submit" className="px-12 py-3 bg-black text-[#FDB913] rounded-full font-black uppercase text-xs tracking-widest shadow-xl">Save Changes</button>
                 </div>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

