  const [searchTerm, setSearchTerm] = useState('');
  const [editingTask, setEditingTask] = useState<Task | null>(null);
  const [showModal, setShowModal] = useState(false);
  const [tempProgress, setTempProgress] = useState(0);

  const filteredTasks = useMemo(() => {
    return tasks.filter(t => 
      t.task.toLowerCase().includes(searchTerm.toLowerCase()) ||
      t.owner.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [tasks, searchTerm]);

  const handleSaveTask = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const taskData: Partial<Task> = {
      task: formData.get('task') as string,
      owner: formData.get('owner') as string,
      category: formData.get('category') as string,
      project: formData.get('project') as string,
      status: formData.get('status') as Status,
      priority: formData.get('priority') as Priority,
      progress: tempProgress,
      hours: parseFloat(formData.get('hours') as string) || 0,
      startDate: formData.get('startDate') as string,
      dueDate: formData.get('dueDate') as string,
      notes: formData.get('notes') as string,
      updatedAt: new Date().toISOString()
    };

    if (editingTask) {
      updateTasks(tasks.map(t => t.id === editingTask.id ? { ...t, ...taskData } : t));
    } else {
      const newTask: Task = {
        id: Math.random().toString(36).substr(2, 9),
        history: [{ timestamp: new Date().toISOString(), change: 'Operation initialized' }],
        comments: [],
        ...taskData as any
      };
      updateTasks([...tasks, newTask]);
    }
    setShowModal(false);
    setLock(null);
  };

  const openEdit = (task: Task | null) => {
    if (task) {
      const lock = locks.find(l => l.itemId === task.id);
      if (lock && lock.user !== currentUser) {
        alert(`This item is currently being edited by ${lock.user}. Please wait.`);
        return;
      }
      setLock(task.id);
    }
    setEditingTask(task);
    setTempProgress(task ? task.progress : 0);
    setShowModal(true);
  };

  const closeModal = () => {
    setLock(null);
    setShowModal(false);
  };

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center bg-white p-5 rounded shadow-sm border border-gray-100">
        <div className="relative flex-1 max-w-2xl">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-400" size={18} />
          <input type="text" placeholder="Filter team operations..." className="w-full pl-10 pr-4 py-3 border border-zinc-100 bg-zinc-50 rounded font-bold text-sm outline-none" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
        </div>
        <button onClick={() => openEdit(null)} className="bg-black text-[#FDB913] px-8 py-3 rounded font-black text-xs uppercase tracking-widest shadow-xl ml-4">NEW OPERATION</button>
      </div>

      <div className="bg-white rounded shadow-sm border border-gray-100 overflow-hidden overflow-x-auto">
        <table className="w-full text-left min-w-[800px]">
          <thead className="bg-zinc-50 border-b border-gray-100">
            <tr>
              <th className="px-6 py-5 text-[10px] font-black uppercase text-gray-400 tracking-widest">Detail</th>
              <th className="px-6 py-5 text-[10px] font-black uppercase text-gray-400 tracking-widest">Stakeholder</th>
              <th className="px-6 py-5 text-[10px] font-black uppercase text-gray-400 tracking-widest">Lock Status</th>
              <th className="px-6 py-5 text-[10px] font-black uppercase text-gray-400 tracking-widest text-right">Progress</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-50">
            {filteredTasks.map(t => {
              const lock = locks.find(l => l.itemId === t.id);
              return (
                <tr key={t.id} className="hover:bg-zinc-50 transition cursor-pointer" onClick={() => openEdit(t)}>
                  <td className="px-6 py-5">
                    <p className="font-black text-zinc-900 text-sm mb-1">{t.task}</p>
                    <span className="text-[8px] font-black uppercase bg-zinc-100 text-zinc-500 px-2 py-0.5 rounded mr-2">{t.category}</span>
                    <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded ${t.status === 'Completed' ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-600'}`}>{t.status}</span>
                  </td>
                  <td className="px-6 py-5 text-xs font-black text-zinc-700 uppercase">{t.owner}</td>
                  <td className="px-6 py-5">
                     {lock ? (
                       <div className="flex items-center space-x-2 text-orange-500 font-black text-[9px]">
                          <Lock size={12} className="animate-pulse" />
                          <span>EDITING: {lock.user}</span>
                       </div>
                     ) : (
                       <span className="text-[9px] font-black uppercase text-gray-300 tracking-tighter">Available</span>
                     )}
                  </td>
                  <td className="px-6 py-5 text-right font-black">{t.progress}%</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {showModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md">
           <div className="bg-white rounded-xl shadow-2xl w-full max-w-2xl overflow-hidden">
              <div className="p-8 bg-[#FDB913] text-black flex justify-between items-center">
                <h2 className="text-2xl font-black uppercase tracking-tight">{editingTask ? 'Edit Operation' : 'New Operation'}</h2>
                <button onClick={closeModal} className="font-black text-3xl">×</button>
              </div>
              <form onSubmit={handleSaveTask} className="p-8 space-y-6">
                 <div className="grid grid-cols-2 gap-6">
                    <div className="col-span-2">
                      <label className="block text-[10px] font-black uppercase text-gray-400 mb-1">Task Description</label>
                      <input name="task" required defaultValue={editingTask?.task} className="w-full border-b-2 p-3 bg-zinc-50 text-lg font-black outline-none" />
                    </div>
                    <div>
                       <label className="block text-[10px] font-black uppercase text-gray-400 mb-1">Stakeholder</label>
                       <select name="owner" required defaultValue={editingTask?.owner || currentUser} className="w-full border p-3 rounded font-bold">
                          {users.map(u => <option key={u} value={u}>{u}</option>)}
                       </select>
                    </div>
                    <div>
                       <label className="block text-[10px] font-black uppercase text-gray-400 mb-1">Status</label>
                       <select name="status" defaultValue={editingTask?.status || 'Not Started'} className="w-full border p-3 rounded font-bold">
                          <option value="Not Started">Not Started</option>
                          <option value="In Progress">In Progress</option>
                          <option value="Completed">Completed</option>
                          <option value="Blocked">Blocked</option>
                       </select>
                    </div>
                    <div className="col-span-2">
                       <label className="text-[10px] font-black uppercase text-gray-400">Progress: {tempProgress}%</label>
                       <input type="range" min="0" max="100" value={tempProgress} onChange={e => setTempProgress(parseInt(e.target.value))} className="w-full accent-black h-2 bg-zinc-100 rounded-full mt-2" />
                    </div>
                 </div>
                 <div className="flex justify-end space-x-4 pt-6">
                    <button type="submit" className="px-12 py-3 bg-black text-[#FDB913] rounded-full font-black uppercase text-xs tracking-widest shadow-xl">Save Changes</button>
                 </div>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

export default TaskBoard;

export type Status = 'Not Started' | 'In Progress' | 'Completed' | 'Blocked' | 'On Hold';
export type Priority = 'High' | 'Medium' | 'Low';
export type ProjectStatus = 'Planning' | 'In Progress' | 'On Hold' | 'Completed' | 'Cancelled';

export interface HistoryEntry {
  timestamp: string;
  change: string;
}

export interface Comment {
  user: string;
  timestamp: string;
  comment: string;
}

export interface ActiveLock {
  itemId: string;
  user: string;
  timestamp: string;
}

export interface Booking {
  id: string;
  date: string;
  userId: string;
  targetId: string;
  targetType: 'task' | 'project';
  hours: number;
  description: string;
}

export interface Task {
  id: string;
  category: string;
  task: string;
  owner: string;
  project: string;
  status: Status;
  priority: Priority;
  progress: number;
  hours: number;
  startDate: string;
  dueDate: string;
  notes: string;
  updatedAt: string; // Multi-user conflict resolution
  history: HistoryEntry[];
  comments: Comment[];
  okrLink?: string;
  keyResultLink?: string;
  ideaLink?: string;
}

export interface Project {
  id: string;
  name: string;
  manager: string;
  status: ProjectStatus;
  startDate: string;
  endDate: string;
  hours: number;
  description: string;
  progress?: number;
  updatedAt: string; // Multi-user conflict resolution
}

export interface Idea {
  id: string;
  idea: string;
  proposer: string;
  impact: 'High' | 'Medium' | 'Low';
  cost: 'High' | 'Medium' | 'Low';
  status: 'New' | 'Under Review' | 'Approved' | 'Implemented' | 'Rejected';
  date: string;
  updatedAt: string;
}

export interface Kudos {
  id: string;
  from: string;
  to: string;
  reason: string;
  date: string;
}

export interface OKR {
  id: string;
  objective: string;
  keyResults: { id: string; kr: string }[];
  updatedAt: string;
}

export interface User {
  name: string;
  capacity: number;
}

export interface AppState {
  version: string;
  tasks: Task[];
  projects: Project[];
  ideas: Idea[];
  kudos: Kudos[];
  okrs: OKR[];
  users: User[];
  bookings: Booking[];
  categories: string[];
  safetyStatus: Record<string, { status: 'green' | 'yellow' | 'red'; notes: string }>;
  dailyAgenda: Record<string, string>;
  lastBackupDate?: string;
  deletedItemIds?: string[];
  activeLocks: ActiveLock[]; // Multi-user presence
  archivedTasks?: Task[]; // Suggestion 4: Performance archiving
}

import React, { useState, useEffect, useRef } from 'react';
import { 
  Calendar, CheckSquare, LayoutDashboard, Target, Clock, 
  Settings, Save, FileCode, Wifi, WifiOff,
  Lightbulb, Award, BarChart3, RefreshCw,
  RotateCw, RefreshCcw, UserCircle, ShieldAlert,
  Archive, Trash2
} from 'lucide-react';
import { z } from 'zod';
import { AppState, Task, Project, User, Idea, Kudos, OKR, Booking, ActiveLock } from './types';
import { DEFAULT_USERS, DEFAULT_CATEGORIES, DEFAULT_AGENDA, BRAND } from './constants';
import Dashboard from './components/Dashboard';
import TaskBoard from './components/TaskBoard';
import ProjectBoard from './components/ProjectBoard';
import CalendarView from './components/CalendarView';
import IdeaMatrix from './components/IdeaMatrix';
import KudosBoard from './components/KudosBoard';
import OKRBoard from './components/OKRBoard';
import Masters from './components/Masters';
import HoursBooking from './components/HoursBooking';
import { Logo } from './components/Logo';

const STORAGE_KEY = 'epiroc_pulse_v6_pro';
const APP_VERSION = '6.0.1';

// Suggestion 3: Schema Validation
const stateSchema = z.object({
  version: z.string(),
  tasks: z.array(z.any()),
  projects: z.array(z.any()),
  ideas: z.array(z.any()),
  kudos: z.array(z.any()),
  okrs: z.array(z.any()),
  users: z.array(z.any()),
  bookings: z.array(z.any()),
  categories: z.array(z.string()),
  safetyStatus: z.record(z.any()),
  dailyAgenda: z.record(z.string()),
  deletedItemIds: z.array(z.string()).optional(),
  activeLocks: z.array(z.any()).optional(),
  archivedTasks: z.array(z.any()).optional()
});

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [currentUser, setCurrentUser] = useState<string>(() => localStorage.getItem('epiroc_user') || 'Guest');
  const [isSafeMode, setIsSafeMode] = useState(false);

  const [data, setData] = useState<AppState>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) return JSON.parse(saved);
    return {
      version: APP_VERSION,
      tasks: [],
      projects: [],
      ideas: [],
      kudos: [],
      okrs: [],
      users: DEFAULT_USERS.map(name => ({ name, capacity: 160 })),
      bookings: [],
      categories: DEFAULT_CATEGORIES,
      safetyStatus: {},
      dailyAgenda: DEFAULT_AGENDA,
      deletedItemIds: [],
      activeLocks: [],
      archivedTasks: []
    };
  });

  const [fileHandle, setFileHandle] = useState<FileSystemFileHandle | null>(null);
  const [isAutoSaving, setIsAutoSaving] = useState(false);
  const [lastFileHash, setLastFileHash] = useState<string>('');
  const [lastSyncTime, setLastSyncTime] = useState<Date | null>(null);

  const dataRef = useRef(data);
  useEffect(() => { dataRef.current = data; }, [data]);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
    localStorage.setItem('epiroc_user', currentUser);
  }, [data, currentUser]);

  // Suggestion 1: Property-Level Merging
  const mergePropLevel = (local: any[], remote: any[], deletedIds: Set<string>) => {
    const map = new Map();
    const combine = [...(local || []), ...(remote || [])];

    combine.forEach(item => {
      if (!item?.id || deletedIds.has(item.id)) return;
      const existing = map.get(item.id);
      if (!existing || new Date(item.updatedAt || 0) > new Date(existing.updatedAt || 0)) {
        map.set(item.id, item);
      }
    });
    return Array.from(map.values());
  };

  const mergeData = (local: AppState, remote: AppState): AppState => {
    const allDeletedIds = new Set([
      ...(local.deletedItemIds || []),
      ...(remote.deletedItemIds || [])
    ]);

    // Suggestion 2: Presence & Soft Locking expiration check (5 min)
    const now = new Date();
    const activeLocks = (remote.activeLocks || []).filter(lock => 
      (now.getTime() - new Date(lock.timestamp).getTime()) < 1000 * 60 * 5
    );

    return {
      ...remote,
      version: APP_VERSION,
      tasks: mergePropLevel(local.tasks, remote.tasks, allDeletedIds),
      projects: mergePropLevel(local.projects, remote.projects, allDeletedIds),
      ideas: mergePropLevel(local.ideas, remote.ideas, allDeletedIds),
      okrs: mergePropLevel(local.okrs, remote.okrs, allDeletedIds),
      kudos: remote.kudos || [],
      bookings: remote.bookings || [],
      deletedItemIds: Array.from(allDeletedIds),
      activeLocks,
      archivedTasks: mergePropLevel(local.archivedTasks || [], remote.archivedTasks || [], new Set())
    };
  };

  const linkSharedFile = async () => {
    try {
      // @ts-ignore
      const [handle] = await window.showOpenFilePicker({
        types: [{ description: 'Epiroc Pulse DB', accept: { 'application/json': ['.json'] } }],
        multiple: false
      });
      setFileHandle(handle);
      const file = await handle.getFile();
      const content = await file.text();
      if (content) {
        const remoteData = JSON.parse(content);
        // Suggestion 3: Validation
        const result = stateSchema.safeParse(remoteData);
        if (!result.success) {
          setIsSafeMode(true);
          return;
        }
        setData(prev => mergeData(prev, result.data as any));
        setLastFileHash(content);
      }
      setLastSyncTime(new Date());
    } catch (err) { console.error(err); }
  };

  const manualSync = async () => {
    if (!fileHandle) return;
    setIsAutoSaving(true);
    try {
      const file = await fileHandle.getFile();
      const content = await file.text();
      const remoteData = JSON.parse(content);
      const result = stateSchema.safeParse(remoteData);

      if (!result.success) {
        setIsSafeMode(true);
        return;
      }

      const merged = mergeData(dataRef.current, result.data as any);
      const mergedContent = JSON.stringify(merged, null, 2);

      // @ts-ignore
      const writable = await fileHandle.createWritable();
      await writable.write(mergedContent);
      await writable.close();

      setData(merged);
      setLastFileHash(mergedContent);
      setLastSyncTime(new Date());
      setIsSafeMode(false);
    } catch (err) { console.error(err); } finally { setIsAutoSaving(false); }
  };

  useEffect(() => {
    if (!fileHandle) return;
    const interval = setInterval(manualSync, 10000);
    return () => clearInterval(interval);
  }, [fileHandle, lastFileHash]);

  const updateData = (newData: Partial<AppState>) => {
    setData(prev => {
      const deletedIds = new Set(prev.deletedItemIds || []);
      const keysToCheck: (keyof AppState)[] = ['tasks', 'projects', 'ideas', 'okrs'];

      keysToCheck.forEach(key => {
        if (newData[key] && Array.isArray(newData[key]) && Array.isArray(prev[key])) {
          (prev[key] as any[]).forEach(p => {
             if (p.id && !(newData[key] as any[]).some(n => n.id === p.id)) {
               deletedIds.add(p.id);
             }
          });
        }
      });

      return { 
        ...prev, 
        ...newData,
        deletedItemIds: Array.from(deletedIds)
      };
    });
  };

  // Suggestion 2: Set/Release Lock
  const toggleLock = (itemId: string | null) => {
    setData(prev => {
      let locks = [...(prev.activeLocks || [])];
      // Clear user's existing locks first
      locks = locks.filter(l => l.user !== currentUser);

      if (itemId) {
        locks.push({
          itemId,
          user: currentUser,
          timestamp: new Date().toISOString()
        });
      }
      return { ...prev, activeLocks: locks };
    });
  };

  // Suggestion 4: Archive Completed Items
  const archiveCompleted = () => {
    setData(prev => {
      const completed = prev.tasks.filter(t => t.status === 'Completed');
      const active = prev.tasks.filter(t => t.status !== 'Completed');
      const deleted = [...(prev.deletedItemIds || []), ...completed.map(t => t.id)];

      return {
        ...prev,
        tasks: active,
        archivedTasks: [...(prev.archivedTasks || []), ...completed],
        deletedItemIds: deleted
      };
    });
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#F8F9FA] relative">
      {isSafeMode && (
        <div className="bg-red-600 text-white py-3 px-8 flex items-center justify-between font-black uppercase tracking-widest z-[100] animate-pulse">
          <div className="flex items-center space-x-3">
             <ShieldAlert size={20} />
             <span>DATABASE CORRUPTION DETECTED! Application in Safe Mode.</span>
          </div>
          <button onClick={() => window.location.reload()} className="bg-white text-red-600 px-6 py-1 rounded-full font-black">RELOAD SYSTEM</button>
        </div>
      )}

      <header className="h-32 flex items-center px-8 relative overflow-hidden transition-colors duration-500 text-[#3d4d5b]" style={{ backgroundColor: BRAND.YELLOW }}>
        <div className="flex flex-col z-10">
          <Logo />
          <div className="flex items-center space-x-6 ml-1 mt-2 text-[9px] uppercase tracking-[0.25em] font-black opacity-80">
            <span className="flex items-center">
              {fileHandle ? <Wifi size={11} className="mr-2" /> : <WifiOff size={11} className="mr-2" />}
              {fileHandle ? 'TEAM CONNECTED' : 'STANDALONE MODE'}
            </span>
            <div className="flex items-center group cursor-pointer">
               <UserCircle size={11} className="mr-2" />
               <select 
                 value={currentUser} 
                 onChange={(e) => setCurrentUser(e.target.value)}
                 className="bg-transparent border-none outline-none font-black text-[9px] cursor-pointer"
               >
                 {DEFAULT_USERS.map(u => <option key={u} value={u} className="bg-white text-black">{u}</option>)}
               </select>
            </div>
          </div>
        </div>

        <div className="flex-1"></div>

        <div className="flex items-center space-x-4 z-10">
           {fileHandle ? (
             <div className="flex items-center bg-white/40 pl-2 pr-6 py-1.5 rounded-full border border-black/5 shadow-lg backdrop-blur-sm space-x-4">
                <button onClick={manualSync} className="px-5 py-2.5 bg-black text-[#FDB913] rounded-full hover:bg-zinc-800 transition shadow-sm flex items-center space-x-2">
                   <RotateCw size={14} className={isAutoSaving ? 'animate-spin' : ''} />
                   <span className="text-[10px] font-black uppercase tracking-widest">SYNC NOW</span>
                </button>
                <div className="flex flex-col items-end py-1">
                   <span className="text-[9px] font-black uppercase opacity-60 tracking-widest">Shared Link</span>
                   <span className="text-[10px] font-black">{lastSyncTime ? lastSyncTime.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'}) : '--:--'}</span>
                </div>
             </div>
           ) : (
             <button onClick={linkSharedFile} className="bg-[#3d4d5b] text-[#FDB913] hover:brightness-110 px-10 py-5 rounded-full font-black text-xs uppercase tracking-[0.25em] shadow-2xl flex items-center space-x-4 transition-all">
               <FileCode size={20} />
               <span>CONNECT TO TEAM FOLDER</span>
             </button>
           )}
        </div>
      </header>

      <nav className="bg-white border-b border-gray-200 sticky top-0 z-40 shadow-sm overflow-x-auto">
        <div className="max-w-7xl mx-auto flex min-w-max">
          {tabs.map(tab => (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex items-center space-x-3 px-8 py-5 transition-all border-b-4 ${
                activeTab === tab.id ? 'border-[#FDB913] text-black font-black bg-gray-50' : 'border-transparent text-gray-400 hover:text-black hover:bg-gray-50'
              }`}
            >
              {tab.icon}
              <span className="text-[11px] uppercase tracking-[0.15em] font-black">{tab.name}</span>
            </button>
          ))}
        </div>
      </nav>

      <main className="flex-1 p-6 max-w-[1600px] mx-auto w-full mb-8">
        {activeTab === 'dashboard' && <Dashboard state={data} />}
        {activeTab === 'calendar' && <CalendarView tasks={data.tasks} safetyStatus={data.safetyStatus} updateSafetyStatus={(newStatus) => updateData({ safetyStatus: newStatus })} />}
        {activeTab === 'tasks' && <TaskBoard currentUser={currentUser} activeLocks={data.activeLocks} toggleLock={toggleLock} tasks={data.tasks} ideas={data.ideas} users={data.users.map(u => u.name)} categories={data.categories} projects={data.projects} okrs={data.okrs} bookings={data.bookings} updateTasks={(tasks) => updateData({ tasks })} />}
        {activeTab === 'projects' && <ProjectBoard currentUser={currentUser} activeLocks={data.activeLocks} toggleLock={toggleLock} projects={data.projects} users={data.users.map(u => u.name)} updateProjects={(projects) => updateData({ projects })} />}
        {activeTab === 'bookings' && <HoursBooking bookings={data.bookings} tasks={data.tasks} projects={data.projects} users={data.users.map(u => u.name)} updateBookings={(bookings) => updateData({ bookings })} />}
        {activeTab === 'okrs' && <OKRBoard okrs={data.okrs} tasks={data.tasks} updateOkrs={(okrs) => updateData({ okrs })} />}
        {activeTab === 'ideas' && <IdeaMatrix ideas={data.ideas} tasks={data.tasks} users={data.users.map(u => u.name)} updateIdeas={(ideas) => updateData({ ideas })} updateTasks={(tasks) => updateData({ tasks })} />}
        {activeTab === 'kudos' && <KudosBoard kudos={data.kudos} users={data.users.map(u => u.name)} updateKudos={(kudos) => updateData({ kudos })} />}
        {activeTab === 'masters' && (
          <div className="space-y-6">
            <div className="bg-white p-8 rounded-xl shadow-sm border border-gray-100 flex items-center justify-between">
               <div className="flex items-center space-x-5">
                  <div className="p-4 rounded-xl bg-zinc-900 text-[#FDB913]">
                    <Archive size={32} />
                  </div>
                  <div>
                    <h3 className="text-xl font-black uppercase tracking-tight text-gray-900">Operation Archive Engine</h3>
                    <p className="text-sm text-gray-500 font-bold uppercase tracking-widest">Speed up the system by moving completed tasks to long-term storage</p>
                  </div>
               </div>
               <button onClick={archiveCompleted} className="bg-black text-[#FDB913] px-8 py-3 rounded-full text-[10px] font-black uppercase tracking-widest shadow-xl transition hover:brightness-110 flex items-center space-x-2">
                 <Trash2 size={14} />
                 <span>ARCHIVE COMPLETED NOW</span>
               </button>
            </div>
            <Masters users={data.users} categories={data.categories} updateUsers={(users) => updateData({ users })} updateCategories={(categories) => updateData({ categories })} />
          </div>
        )}
      </main>

      <footer className="fixed bottom-2 right-4 text-[9px] text-gray-300 font-mono pointer-events-none z-50 mix-blend-multiply">
        Created by: Aditya Shitut | Pro Sync v6
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { Task, Status, Priority, OKR, Booking, Idea, ActiveLock } from '../types';
import { Plus, Trash2, Search, Target, Clock, AlertTriangle, ListChecks, History, Link, Lock } from 'lucide-react';
import { format } from 'date-fns';

interface TaskBoardProps {
  tasks: Task[];
  users: string[];
  categories: string[];
  projects: any[];
  okrs: OKR[];
  ideas?: Idea[];
  bookings: Booking[];
  currentUser: string;
  activeLocks: ActiveLock[];
  toggleLock: (id: string | null) => void;
  updateTasks: (tasks: Task[]) => void;
}

const TaskBoard: React.FC<TaskBoardProps> = ({ tasks, users, categories, projects, okrs, ideas = [], bookings, currentUser, activeLocks, toggleLock, updateTasks }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filterOwner, setFilterOwner] = useState('All');
  const [editingTask, setEditingTask] = useState<Task | null>(null);
  const [showModal, setShowModal] = useState(false);
  const [activeSubTab, setActiveSubTab] = useState<'details' | 'history'>('details');
  const [tempProgress, setTempProgress] = useState(0);

  const filteredTasks = useMemo(() => {
    return tasks.filter(t => {
      const matchSearch = t.task.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          t.owner.toLowerCase().includes(searchTerm.toLowerCase());
      const matchOwner = filterOwner === 'All' || t.owner === filterOwner;
      return matchSearch && matchOwner;
    });
  }, [tasks, searchTerm, filterOwner]);

  const handleSaveTask = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const taskData: Partial<Task> = {
      task: formData.get('task') as string,
      owner: formData.get('owner') as string,
      category: formData.get('category') as string,
      project: formData.get('project') as string,
      status: formData.get('status') as Status,
      priority: formData.get('priority') as Priority,
      progress: tempProgress,
      hours: parseFloat(formData.get('hours') as string) || 0,
      startDate: formData.get('startDate') as string,
      dueDate: formData.get('dueDate') as string,
      notes: formData.get('notes') as string,
      updatedAt: new Date().toISOString()
    };

    if (editingTask) {
      updateTasks(tasks.map(t => t.id === editingTask.id ? { ...t, ...taskData } : t));
    } else {
      const newTask: Task = {
        id: Math.random().toString(36).substr(2, 9),
        history: [{ timestamp: new Date().toISOString(), change: 'Operation initialized' }],
        comments: [],
        ...taskData as any
      };
      updateTasks([...tasks, newTask]);
    }
    setShowModal(false);
    toggleLock(null);
  };

  const openEdit = (task: Task | null) => {
    if (task) {
      const lock = activeLocks.find(l => l.itemId === task.id);
      if (lock && lock.user !== currentUser) {
        alert(`ACCESS DENIED: ${lock.user} is currently editing this operation.`);
        return;
      }
      toggleLock(task.id);
    }
    setEditingTask(task);
    setTempProgress(task ? task.progress : 0);
    setShowModal(true);
  };

  const closeModal = () => {
    setShowModal(false);
    toggleLock(null);
  };

  const isLockedByOther = editingTask ? activeLocks.some(l => l.itemId === editingTask.id && l.user !== currentUser) : false;
  const currentLock = editingTask ? activeLocks.find(l => l.itemId === editingTask.id) : null;

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap justify-between items-center gap-4 bg-white p-5 rounded shadow-sm border border-gray-100">
        <div className="flex items-center space-x-4 flex-1 max-w-2xl">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-zinc-400" size={18} />
            <input type="text" placeholder="Search team operations..." className="w-full pl-10 pr-4 py-3 border border-zinc-100 bg-zinc-50 rounded font-bold text-sm outline-none focus:bg-white" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
          </div>
        </div>
        <button onClick={() => openEdit(null)} className="bg-black text-[#FDB913] px-8 py-3 rounded font-black text-xs uppercase tracking-widest shadow-xl transition hover:brightness-110">INITIATE OPERATION</button>
      </div>

      <div className="bg-white rounded shadow-sm border border-gray-100 overflow-hidden">
        <table className="w-full text-left">
          <thead className="bg-zinc-50 border-b border-gray-100">
            <tr>
              <th className="px-6 py-5 text-[10px] font-black uppercase text-gray-400 tracking-widest">Detail</th>
              <th className="px-6 py-5 text-[10px] font-black uppercase text-gray-400 tracking-widest">Stakeholder</th>
              <th className="px-6 py-5 text-[10px] font-black uppercase text-gray-400 tracking-widest">Sync Status</th>
              <th className="px-6 py-5 text-[10px] font-black uppercase text-gray-400 tracking-widest text-right">Progress</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-50">
            {filteredTasks.map(t => {
              const lock = activeLocks.find(l => l.itemId === t.id);
              return (
                <tr key={t.id} className="hover:bg-zinc-50 transition cursor-pointer" onClick={() => openEdit(t)}>
                  <td className="px-6 py-5">
                    <p className="font-black text-zinc-900 text-sm mb-1">{t.task}</p>
                    <span className={`text-[8px] font-black uppercase px-2 py-0.5 rounded ${t.status === 'Completed' ? 'bg-green-100 text-green-700' : 'bg-gray-100 text-gray-600'}`}>{t.status}</span>
                  </td>
                  <td className="px-6 py-5 text-xs font-black text-zinc-700 uppercase">{t.owner}</td>
                  <td className="px-6 py-5">
                    {lock ? (
                      <div className="flex items-center space-x-2 text-orange-500 font-black text-[9px] uppercase animate-pulse">
                        <Lock size={12} />
                        <span>Editing by {lock.user}</span>
                      </div>
                    ) : (
                      <span className="text-[9px] font-black text-gray-300 uppercase">Available</span>
                    )}
                  </td>
                  <td className="px-6 py-5 text-right font-black">{t.progress}%</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {showModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-md">
           <div className="bg-white rounded-xl shadow-2xl w-full max-w-3xl max-h-[90vh] overflow-hidden flex flex-col">
              <div className="p-8 bg-[#FDB913] text-black flex justify-between items-center shrink-0">
                <div>
                  <h2 className="text-2xl font-black uppercase tracking-tight">{editingTask ? 'Edit Operation' : 'New Operation'}</h2>
                  {currentLock && (
                    <div className="flex items-center space-x-2 text-[10px] font-black uppercase bg-black/10 px-3 py-1 rounded-full mt-1">
                      <Lock size={12} />
                      <span>Editing Lock Active for {currentLock.user}</span>
                    </div>
                  )}
                </div>
                <button onClick={closeModal} className="font-black text-3xl">×</button>
              </div>

              <form onSubmit={handleSaveTask} className="p-8 space-y-6 overflow-y-auto">
                 <div className="grid grid-cols-2 gap-6">
                    <div className="col-span-2">
                      <label className="block text-[10px] font-black uppercase text-gray-400 mb-1">Operational Task *</label>
                      <input name="task" required defaultValue={editingTask?.task} className="w-full border-b-2 p-3 bg-zinc-50 text-lg font-black outline-none focus:border-black" disabled={isLockedByOther} />
                    </div>
                    <div>
                       <label className="block text-[10px] font-black uppercase text-gray-400 mb-1">Stakeholder</label>
                       <select name="owner" required defaultValue={editingTask?.owner} className="w-full border p-3 rounded font-bold" disabled={isLockedByOther}>
                          {users.map(u => <option key={u} value={u}>{u}</option>)}
                       </select>
                    </div>
                    <div>
                       <label className="block text-[10px] font-black uppercase text-gray-400 mb-1">Status</label>
                       <select name="status" defaultValue={editingTask?.status || 'Not Started'} className="w-full border p-3 rounded font-bold" disabled={isLockedByOther}>
                          <option value="Not Started">Not Started</option>
                          <option value="In Progress">In Progress</option>
                          <option value="Completed">Completed</option>
                       </select>
                    </div>
                    <div className="col-span-2">
                       <label className="block text-[10px] font-black uppercase text-gray-400 mb-1">Progress: {tempProgress}%</label>
                       <input type="range" min="0" max="100" value={tempProgress} onChange={e => setTempProgress(parseInt(e.target.value))} className="w-full h-2 bg-zinc-100 rounded-lg accent-black" disabled={isLockedByOther} />
                    </div>
                    <div className="col-span-2">
                       <label className="block text-[10px] font-black uppercase text-gray-400 mb-1">Remarks</label>
                       <textarea name="notes" rows={3} defaultValue={editingTask?.notes} className="w-full border p-3 rounded" disabled={isLockedByOther}></textarea>
                    </div>
                 </div>
                 <div className="flex justify-end space-x-4 pt-6 border-t">
                    <button type="button" onClick={closeModal} className="px-6 py-3 font-black text-gray-400 uppercase text-xs">Discard</button>
                    {!isLockedByOther && (
                      <button type="submit" className="px-12 py-3 bg-black text-[#FDB913] rounded-full font-black uppercase text-xs tracking-widest shadow-xl">Commit Changes</button>
                    )}
                 </div>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

export default TaskBoard;
